func (id CheckpointID) Path() string {
	if len(id) < 3 {
		return string(id)
	}
	return string(id[:2]) + "/" + string(id[2:])
}

// ValidateCheckpointID validates that a string is a valid checkpoint ID format.
// Returns an error if invalid, nil if valid.
func ValidateCheckpointID(id string) error {
	if !checkpointIDRegex.MatchString(id) {
