// WriteCommitted writes a committed checkpoint to the entire/sessions branch.
// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
//
// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
	_ = ctx // Reserved for future use

	// Validate identifiers to prevent path traversal and malformed data
	if err := trailers.ValidateCheckpointID(opts.CheckpointID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}

	// Ensure sessions branch exists
	if err := s.ensureSessionsBranch(); err != nil {
		return fmt.Errorf("failed to ensure sessions branch: %w", err)
	}

	// Get current branch tip and flatten tree
	ref, entries, err := s.getSessionsBranchEntries()
	if err != nil {
		return err
	}

	// Use sharded path: <id[:2]>/<id[2:]>/
	basePath := trailers.CheckpointPath(opts.CheckpointID) + "/"

	// Track task metadata path for commit trailer
	var taskMetadataPath string

	// Handle task checkpoints
	if opts.IsTask && opts.ToolUseID != "" {
		taskMetadataPath, err = s.writeTaskCheckpointEntries(opts, basePath, entries)
		if err != nil {
			return err
		}
	}

	// Write standard checkpoint entries (transcript, prompts, context, metadata)
	if err := s.writeStandardCheckpointEntries(opts, basePath, entries); err != nil {
		return err
	}

	// Build and commit
	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return err
	}

	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return err
	}

	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	newRef := plumbing.NewHashReference(refName, newCommitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}

	return nil
}

// getSessionsBranchEntries returns the sessions branch reference and flattened tree entries.
func (s *GitStore) getSessionsBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get sessions branch reference: %w", err)
	}

	parentCommit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	baseTree, err := parentCommit.Tree()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return nil, nil, err
	}

	return ref, entries, nil
}

// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
func (s *GitStore) writeTaskCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"

	if opts.IsIncremental {
		return s.writeIncrementalTaskCheckpoint(opts, taskPath, entries)
	}
	return s.writeFinalTaskCheckpoint(opts, taskPath, entries)
}

// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
	checkpoint := incrementalCheckpointData{
		Type:      opts.IncrementalType,
		ToolUseID: opts.ToolUseID,
		Timestamp: time.Now().UTC(),
		Data:      opts.IncrementalData,
	}
	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
	if err != nil {
		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
	}
	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
	if err != nil {
		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
	}

	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
	cpPath := taskPath + "checkpoints/" + cpFilename
	entries[cpPath] = object.TreeEntry{
		Name: cpPath,
		Mode: filemode.Regular,
		Hash: cpBlobHash,
	}
	return cpPath, nil
}

// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
	checkpoint := taskCheckpointData{
		SessionID:      opts.SessionID,
		ToolUseID:      opts.ToolUseID,
		CheckpointUUID: opts.CheckpointUUID,
		AgentID:        opts.AgentID,
	}
	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
	if err != nil {
		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
	}
	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
	if err != nil {
		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
	}

	checkpointFile := taskPath + "checkpoint.json"
	entries[checkpointFile] = object.TreeEntry{
		Name: checkpointFile,
		Mode: filemode.Regular,
		Hash: blobHash,
	}

	// Write subagent transcript if available
	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
		if readErr == nil {
			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
			if agentBlobErr == nil {
				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
				entries[agentPath] = object.TreeEntry{
					Name: agentPath,
					Mode: filemode.Regular,
					Hash: agentBlobHash,
				}
			}
		}
	}

	// Return task path without trailing slash
	return taskPath[:len(taskPath)-1], nil
}

// writeStandardCheckpointEntries writes transcript, prompts, context, metadata.json and any additional files.
// If the checkpoint already exists (from a previous session), archives the existing files to a numbered subfolder.
func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
	// Check if checkpoint already exists (multi-session support)
	var existingMetadata *CommittedMetadata
	metadataPath := basePath + paths.MetadataFileName
	if entry, exists := entries[metadataPath]; exists {
		// Read existing metadata to get session count
		existing, err := s.readMetadataFromBlob(entry.Hash)
		if err == nil {
			existingMetadata = existing
			// Archive existing session files to numbered subfolder
			s.archiveExistingSession(basePath, existingMetadata, entries)
		}
	}

	// Write transcript (from in-memory content or file path)
	if err := s.writeTranscript(opts, basePath, entries); err != nil {
		return err
	}

	// Write prompts
	if len(opts.Prompts) > 0 {
		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
		if err != nil {
			return err
		}
		entries[basePath+paths.PromptFileName] = object.TreeEntry{
			Name: basePath + paths.PromptFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Write context
	if len(opts.Context) > 0 {
		blobHash, err := CreateBlobFromContent(s.repo, opts.Context)
		if err != nil {
			return err
		}
		entries[basePath+paths.ContextFileName] = object.TreeEntry{
			Name: basePath + paths.ContextFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Copy additional metadata files from directory if specified
	if opts.MetadataDir != "" {
		if err := s.copyMetadataDir(opts.MetadataDir, basePath, entries); err != nil {
			return fmt.Errorf("failed to copy metadata directory: %w", err)
		}
	}

	// Write metadata.json (with merged info if existing metadata present)
	return s.writeMetadataJSON(opts, basePath, entries, existingMetadata)
}

// writeTranscript writes the transcript file from in-memory content or file path.
func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
	transcript := opts.Transcript
	if len(transcript) == 0 && opts.TranscriptPath != "" {
		var readErr error
		transcript, readErr = os.ReadFile(opts.TranscriptPath)
		if readErr != nil {
			// Non-fatal: transcript may not exist yet
			transcript = nil
		}
	}
	if len(transcript) == 0 {
		return nil
	}

	blobHash, err := CreateBlobFromContent(s.repo, transcript)
	if err != nil {
		return err
	}
	entries[basePath+paths.TranscriptFileName] = object.TreeEntry{
		Name: basePath + paths.TranscriptFileName,
		Mode: filemode.Regular,
		Hash: blobHash,
	}

	// Content hash for deduplication
	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
	if err != nil {
		return err
	}
	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
		Name: basePath + paths.ContentHashFileName,
		Mode: filemode.Regular,
		Hash: hashBlob,
	}
	return nil
}

// writeMetadataJSON writes the metadata.json file for the checkpoint.
// If existingMetadata is provided, merges session info from the previous session(s).
func (s *GitStore) writeMetadataJSON(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingMetadata *CommittedMetadata) error {
	metadata := CommittedMetadata{
		CheckpointID:           opts.CheckpointID,
		SessionID:              opts.SessionID,
		Strategy:               opts.Strategy,
		CreatedAt:              time.Now(),
		Branch:                 opts.Branch,
		CheckpointsCount:       opts.CheckpointsCount,
		FilesTouched:           opts.FilesTouched,
		Agent:                  opts.Agent,
		IsTask:                 opts.IsTask,
		ToolUseID:              opts.ToolUseID,
		SessionCount:           1,
		SessionIDs:             []string{opts.SessionID},
		TranscriptUUIDAtStart:  opts.TranscriptUUIDAtStart,
		TranscriptLinesAtStart: opts.TranscriptLinesAtStart,
		TokenUsage:             opts.TokenUsage,
	}

	// Merge with existing metadata if present (multi-session checkpoint)
	if existingMetadata != nil {
		// Get existing session count (default to 1 for backwards compat)
		existingCount := existingMetadata.SessionCount
		if existingCount == 0 {
			existingCount = 1
		}
		metadata.SessionCount = existingCount + 1

		// Merge session IDs
		existingIDs := existingMetadata.SessionIDs
		if len(existingIDs) == 0 {
			// Backwards compat: old metadata only had SessionID
			existingIDs = []string{existingMetadata.SessionID}
		}
		metadata.SessionIDs = append(metadata.SessionIDs[:0], existingIDs...)
		metadata.SessionIDs = append(metadata.SessionIDs, opts.SessionID)

		// Merge files touched (deduplicated)
		metadata.FilesTouched = mergeFilesTouched(existingMetadata.FilesTouched, opts.FilesTouched)

		// Sum checkpoint counts
		metadata.CheckpointsCount = existingMetadata.CheckpointsCount + opts.CheckpointsCount
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal metadata: %w", err)
	}
	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return err
	}
	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
		Name: basePath + paths.MetadataFileName,
		Mode: filemode.Regular,
		Hash: metadataHash,
	}
	return nil
}

// mergeFilesTouched combines two file lists, removing duplicates.
func mergeFilesTouched(existing, additional []string) []string {
	seen := make(map[string]bool)
	var result []string

	for _, f := range existing {
		if !seen[f] {
			seen[f] = true
			result = append(result, f)
		}
	}
	for _, f := range additional {
		if !seen[f] {
			seen[f] = true
			result = append(result, f)
		}
	}

	sort.Strings(result)
	return result
}

// readMetadataFromBlob reads CommittedMetadata from a blob hash.
func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
	blob, err := s.repo.BlobObject(hash)
	if err != nil {
		return nil, fmt.Errorf("failed to get blob: %w", err)
	}

	reader, err := blob.Reader()
	if err != nil {
		return nil, fmt.Errorf("failed to get blob reader: %w", err)
	}
	defer reader.Close()

	var metadata CommittedMetadata
	if err := json.NewDecoder(reader).Decode(&metadata); err != nil {
		return nil, fmt.Errorf("failed to decode metadata: %w", err)
	}

	return &metadata, nil
}

// archiveExistingSession moves existing session files to a numbered subfolder.
// The subfolder number is based on the current session count (so first archived session goes to "1/").
func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
	// Determine archive folder number
	sessionCount := existingMetadata.SessionCount
	if sessionCount == 0 {
		sessionCount = 1 // backwards compat
	}
	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)

	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
	filesToArchive := []string{
		paths.MetadataFileName,
		paths.TranscriptFileName,
		paths.PromptFileName,
		paths.ContextFileName,
		paths.ContentHashFileName,
	}

	// Move each file to archive folder
	for _, filename := range filesToArchive {
		srcPath := basePath + filename
		if entry, exists := entries[srcPath]; exists {
			// Add to archive location
			dstPath := archivePath + filename
			entries[dstPath] = object.TreeEntry{
				Name: dstPath,
				Mode: entry.Mode,
				Hash: entry.Hash,
			}
			// Remove from original location (will be overwritten by new session)
			delete(entries, srcPath)
		}
	}
}

// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
// Returns sessions ordered by folder index (oldest first).
func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int) []ArchivedSession {
	var archived []ArchivedSession

	// Archived sessions are in numbered folders: 1/, 2/, etc.
	// The most recent session is at the root level (not archived).
	// Session count N means there are N-1 archived sessions.
	for i := 1; i < sessionCount; i++ {
		folderName := strconv.Itoa(i)

		// Try to get the archived session subtree
		subTree, err := checkpointTree.Tree(folderName)
		if err != nil {
			continue // Folder doesn't exist, skip
		}

		session := ArchivedSession{
			FolderIndex: i,
		}

		// Read metadata to get session ID
		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
			if content, contentErr := metadataFile.Contents(); contentErr == nil {
				var metadata CommittedMetadata
				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
					session.SessionID = metadata.SessionID
				}
			}
		}

		// Read transcript (try current format first, then legacy)
		if file, fileErr := subTree.File(paths.TranscriptFileName); fileErr == nil {
			if content, contentErr := file.Contents(); contentErr == nil {
				session.Transcript = []byte(content)
			}
		} else if file, fileErr := subTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
			if content, contentErr := file.Contents(); contentErr == nil {
				session.Transcript = []byte(content)
			}
		}

		// Read prompts
		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
			if content, contentErr := file.Contents(); contentErr == nil {
				session.Prompts = content
			}
		}

		// Only add if we got a transcript
		if len(session.Transcript) > 0 {
			archived = append(archived, session)
		}
	}

	return archived
}

// buildCommitMessage constructs the commit message with proper trailers.
// The commit subject is always "Checkpoint: <id>" for consistency.
// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
	var commitMsg strings.Builder

	// Subject line is always the checkpoint ID for consistent formatting
	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))

	// Include custom description in body if provided (e.g., task checkpoint details)
	if opts.CommitSubject != "" {
		commitMsg.WriteString(opts.CommitSubject + "\n\n")
	}
	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
	if opts.Agent != "" {
		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
	}
	if opts.EphemeralBranch != "" {
		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", paths.EphemeralBranchTrailerKey, opts.EphemeralBranch))
	}
	if taskMetadataPath != "" {
		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", paths.MetadataTaskTrailerKey, taskMetadataPath))
	}

	return commitMsg.String()
}

// incrementalCheckpointData represents an incremental checkpoint during subagent execution.
// This mirrors strategy.SubagentCheckpoint but avoids import cycles.
type incrementalCheckpointData struct {
	Type      string          `json:"type"`
	ToolUseID string          `json:"tool_use_id"`
	Timestamp time.Time       `json:"timestamp"`
	Data      json.RawMessage `json:"data"`
}

// taskCheckpointData represents a final task checkpoint.
// This mirrors strategy.TaskCheckpoint but avoids import cycles.
type taskCheckpointData struct {
	SessionID      string `json:"session_id"`
	ToolUseID      string `json:"tool_use_id"`
	CheckpointUUID string `json:"checkpoint_uuid"`
	AgentID        string `json:"agent_id,omitempty"`
}

// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
// Returns nil, nil if the checkpoint doesn't exist.
//

func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID string) (*ReadCommittedResult, error) {
	_ = ctx // Reserved for future use

	tree, err := s.getSessionsBranchTree()
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
	}

	checkpointPath := trailers.CheckpointPath(checkpointID)
	checkpointTree, err := tree.Tree(checkpointPath)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
	}

	result := &ReadCommittedResult{}

	// Read metadata.json
	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
		if content, contentErr := metadataFile.Contents(); contentErr == nil {
			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
			json.Unmarshal([]byte(content), &result.Metadata)
			result.Metadata.Strategy = paths.NormalizeStrategyName(result.Metadata.Strategy)
		}
	}

	// Read transcript (try current format first, then legacy)
	if file, fileErr := checkpointTree.File(paths.TranscriptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Transcript = []byte(content)
		}
	} else if file, fileErr := checkpointTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Transcript = []byte(content)
		}
	}

	// Read prompts
	if file, fileErr := checkpointTree.File(paths.PromptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Prompts = content
		}
	}

	// Read context
	if file, fileErr := checkpointTree.File(paths.ContextFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Context = content
		}
	}

	// Read archived sessions if this is a multi-session checkpoint
	if result.Metadata.SessionCount > 1 {
		result.ArchivedSessions = s.readArchivedSessions(checkpointTree, result.Metadata.SessionCount)
	}

	return result, nil
}

// ListCommitted lists all committed checkpoints from the entire/sessions branch.
// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
//

func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
	_ = ctx // Reserved for future use

	tree, err := s.getSessionsBranchTree()
	if err != nil {
		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
	}

	var checkpoints []CommittedInfo

	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
	for _, bucketEntry := range tree.Entries {
		if bucketEntry.Mode != filemode.Dir {
			continue
		}
		// Bucket should be 2 hex chars
		if len(bucketEntry.Name) != 2 {
			continue
		}

		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
		if treeErr != nil {
			continue
		}

		// Each entry in the bucket is the remaining part of the checkpoint ID
		for _, checkpointEntry := range bucketTree.Entries {
			if checkpointEntry.Mode != filemode.Dir {
				continue
			}

			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
			if cpTreeErr != nil {
				continue
			}

			// Reconstruct checkpoint ID: <bucket><remaining>
			checkpointID := bucketEntry.Name + checkpointEntry.Name

			info := CommittedInfo{
				CheckpointID: checkpointID,
			}

			// Get details from metadata file
			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
				if content, contentErr := metadataFile.Contents(); contentErr == nil {
					var metadata CommittedMetadata
					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
						info.SessionID = metadata.SessionID
						info.CreatedAt = metadata.CreatedAt
						info.CheckpointsCount = metadata.CheckpointsCount
						info.FilesTouched = metadata.FilesTouched
						info.Agent = metadata.Agent
						info.IsTask = metadata.IsTask
						info.ToolUseID = metadata.ToolUseID
						info.SessionCount = metadata.SessionCount
						info.SessionIDs = metadata.SessionIDs
					}
				}
			}

			checkpoints = append(checkpoints, info)
		}
	}

	// Sort by time (most recent first)
	sort.Slice(checkpoints, func(i, j int) bool {
		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
	})

	return checkpoints, nil
}

// GetTranscript retrieves the transcript for a specific checkpoint ID.
func (s *GitStore) GetTranscript(ctx context.Context, checkpointID string) ([]byte, error) {
	result, err := s.ReadCommitted(ctx, checkpointID)
	if err != nil {
		return nil, err
	}
	if result == nil {
		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
	}
	if len(result.Transcript) == 0 {
		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
	}
	return result.Transcript, nil
}

// ensureSessionsBranch ensures the entire/sessions branch exists.
func (s *GitStore) ensureSessionsBranch() error {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	_, err := s.repo.Reference(refName, true)
	if err == nil {
		return nil // Branch exists
	}

	// Create orphan branch with empty tree
	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return err
	}

	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
	if err != nil {
		return err
	}

	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}
	return nil
}

// getSessionsBranchTree returns the tree object for the entire/sessions branch.
func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, fmt.Errorf("sessions branch not found: %w", err)
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	return tree, nil
}

// CreateBlobFromContent creates a blob object from in-memory content.
// Exported for use by strategy package (session_test.go)
func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(content)))

	writer, err := obj.Writer()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
	}

	_, err = writer.Write(content)
	if err != nil {
		_ = writer.Close()
		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
	}
	if err := writer.Close(); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
	}
	return hash, nil
}

// copyMetadataDir copies all files from a directory to the checkpoint path.
// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		// Skip symlinks to prevent reading files outside the metadata directory.
		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
		// then be captured in the checkpoint and stored in git history.
		if info.Mode()&os.ModeSymlink != 0 {
			return nil
		}

		// Get relative path within metadata dir
		relPath, err := filepath.Rel(metadataDir, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}

		// Prevent path traversal via symlinks pointing outside the metadata dir
		if strings.HasPrefix(relPath, "..") {
			return fmt.Errorf("path traversal detected: %s", relPath)
		}

		// Create blob from file
		blobHash, mode, err := createBlobFromFile(s.repo, path)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}

		// Store at checkpoint path
		fullPath := basePath + relPath
		entries[fullPath] = object.TreeEntry{
			Name: fullPath,
			Mode: mode,
			Hash: blobHash,
		}

		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk metadata directory: %w", err)
	}
	return nil
}

// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
	// Get repository config (includes local settings)
	cfg, err := repo.Config()
	if err == nil {
		name = cfg.User.Name
		email = cfg.User.Email
	}

	// Provide sensible defaults if git user is not configured
	if name == "" {
		name = "Unknown"
	}
	if email == "" {
		email = "unknown@local"
	}

	return name, email
}

package checkpoint

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// WriteCommitted writes a committed checkpoint to the entire/sessions branch.
// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
//
// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
	_ = ctx // Reserved for future use

	// Validate identifiers to prevent path traversal and malformed data
	if err := trailers.ValidateCheckpointID(opts.CheckpointID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}

	// Ensure sessions branch exists
	if err := s.ensureSessionsBranch(); err != nil {
		return fmt.Errorf("failed to ensure sessions branch: %w", err)
	}

	// Get current branch tip and flatten tree
	ref, entries, err := s.getSessionsBranchEntries()
	if err != nil {
		return err
	}

	// Use sharded path: <id[:2]>/<id[2:]>/
	basePath := trailers.CheckpointPath(opts.CheckpointID) + "/"

	// Track task metadata path for commit trailer
	var taskMetadataPath string

	// Handle task checkpoints
	if opts.IsTask && opts.ToolUseID != "" {
		taskMetadataPath, err = s.writeTaskCheckpointEntries(opts, basePath, entries)
		if err != nil {
			return err
		}
	}

	// Write standard checkpoint entries (transcript, prompts, context, metadata)
	if err := s.writeStandardCheckpointEntries(opts, basePath, entries); err != nil {
		return err
	}

	// Build and commit
	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return err
	}

	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return err
	}

	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	newRef := plumbing.NewHashReference(refName, newCommitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}

	return nil
}

// getSessionsBranchEntries returns the sessions branch reference and flattened tree entries.
func (s *GitStore) getSessionsBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get sessions branch reference: %w", err)
	}

	parentCommit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	baseTree, err := parentCommit.Tree()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return nil, nil, err
	}

	return ref, entries, nil
}

// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
func (s *GitStore) writeTaskCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"

	if opts.IsIncremental {
		return s.writeIncrementalTaskCheckpoint(opts, taskPath, entries)
	}
	return s.writeFinalTaskCheckpoint(opts, taskPath, entries)
}

// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
	checkpoint := incrementalCheckpointData{
		Type:      opts.IncrementalType,
		ToolUseID: opts.ToolUseID,
		Timestamp: time.Now().UTC(),
		Data:      opts.IncrementalData,
	}
	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
	if err != nil {
		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
	}
	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
	if err != nil {
		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
	}

	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
	cpPath := taskPath + "checkpoints/" + cpFilename
	entries[cpPath] = object.TreeEntry{
		Name: cpPath,
		Mode: filemode.Regular,
		Hash: cpBlobHash,
	}
	return cpPath, nil
}

// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
	checkpoint := taskCheckpointData{
		SessionID:      opts.SessionID,
		ToolUseID:      opts.ToolUseID,
		CheckpointUUID: opts.CheckpointUUID,
		AgentID:        opts.AgentID,
	}
	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
	if err != nil {
		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
	}
	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
	if err != nil {
		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
	}

	checkpointFile := taskPath + "checkpoint.json"
	entries[checkpointFile] = object.TreeEntry{
		Name: checkpointFile,
		Mode: filemode.Regular,
		Hash: blobHash,
	}

	// Write subagent transcript if available
	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
		if readErr == nil {
			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
			if agentBlobErr == nil {
				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
				entries[agentPath] = object.TreeEntry{
					Name: agentPath,
					Mode: filemode.Regular,
					Hash: agentBlobHash,
				}
			}
		}
	}

	// Return task path without trailing slash
	return taskPath[:len(taskPath)-1], nil
}

// writeStandardCheckpointEntries writes transcript, prompts, context, metadata.json and any additional files.
// If the checkpoint already exists (from a previous session), archives the existing files to a numbered subfolder.
func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
	// Check if checkpoint already exists (multi-session support)
	var existingMetadata *CommittedMetadata
	metadataPath := basePath + paths.MetadataFileName
	if entry, exists := entries[metadataPath]; exists {
		// Read existing metadata to get session count
		existing, err := s.readMetadataFromBlob(entry.Hash)
		if err == nil {
			existingMetadata = existing
			// Archive existing session files to numbered subfolder
			s.archiveExistingSession(basePath, existingMetadata, entries)
		}
	}

	// Write transcript (from in-memory content or file path)
	if err := s.writeTranscript(opts, basePath, entries); err != nil {
		return err
	}

	// Write prompts
	if len(opts.Prompts) > 0 {
		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
		if err != nil {
			return err
		}
		entries[basePath+paths.PromptFileName] = object.TreeEntry{
			Name: basePath + paths.PromptFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Write context
	if len(opts.Context) > 0 {
		blobHash, err := CreateBlobFromContent(s.repo, opts.Context)
		if err != nil {
			return err
		}
		entries[basePath+paths.ContextFileName] = object.TreeEntry{
			Name: basePath + paths.ContextFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Copy additional metadata files from directory if specified
	if opts.MetadataDir != "" {
		if err := s.copyMetadataDir(opts.MetadataDir, basePath, entries); err != nil {
			return fmt.Errorf("failed to copy metadata directory: %w", err)
		}
	}

	// Write metadata.json (with merged info if existing metadata present)
	return s.writeMetadataJSON(opts, basePath, entries, existingMetadata)
}

// writeTranscript writes the transcript file from in-memory content or file path.
func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
	transcript := opts.Transcript
	if len(transcript) == 0 && opts.TranscriptPath != "" {
		var readErr error
		transcript, readErr = os.ReadFile(opts.TranscriptPath)
		if readErr != nil {
			// Non-fatal: transcript may not exist yet
			transcript = nil
		}
	}
	if len(transcript) == 0 {
		return nil
	}

	blobHash, err := CreateBlobFromContent(s.repo, transcript)
	if err != nil {
		return err
	}
	entries[basePath+paths.TranscriptFileName] = object.TreeEntry{
		Name: basePath + paths.TranscriptFileName,
		Mode: filemode.Regular,
		Hash: blobHash,
	}

	// Content hash for deduplication
	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
	if err != nil {
		return err
	}
	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
		Name: basePath + paths.ContentHashFileName,
		Mode: filemode.Regular,
		Hash: hashBlob,
	}
	return nil
}

// writeMetadataJSON writes the metadata.json file for the checkpoint.
// If existingMetadata is provided, merges session info from the previous session(s).
func (s *GitStore) writeMetadataJSON(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingMetadata *CommittedMetadata) error {
	metadata := CommittedMetadata{
		CheckpointID:           opts.CheckpointID,
		SessionID:              opts.SessionID,
		Strategy:               opts.Strategy,
		CreatedAt:              time.Now(),
		Branch:                 opts.Branch,
		CheckpointsCount:       opts.CheckpointsCount,
		FilesTouched:           opts.FilesTouched,
		Agent:                  opts.Agent,
		IsTask:                 opts.IsTask,
		ToolUseID:              opts.ToolUseID,
		SessionCount:           1,
		SessionIDs:             []string{opts.SessionID},
		TranscriptUUIDAtStart:  opts.TranscriptUUIDAtStart,
		TranscriptLinesAtStart: opts.TranscriptLinesAtStart,
		TokenUsage:             opts.TokenUsage,
	}

	// Merge with existing metadata if present (multi-session checkpoint)
	if existingMetadata != nil {
		// Get existing session count (default to 1 for backwards compat)
		existingCount := existingMetadata.SessionCount
		if existingCount == 0 {
			existingCount = 1
		}
		metadata.SessionCount = existingCount + 1

		// Merge session IDs
		existingIDs := existingMetadata.SessionIDs
		if len(existingIDs) == 0 {
			// Backwards compat: old metadata only had SessionID
			existingIDs = []string{existingMetadata.SessionID}
		}
		metadata.SessionIDs = append(metadata.SessionIDs[:0], existingIDs...)
		metadata.SessionIDs = append(metadata.SessionIDs, opts.SessionID)

		// Merge files touched (deduplicated)
		metadata.FilesTouched = mergeFilesTouched(existingMetadata.FilesTouched, opts.FilesTouched)

		// Sum checkpoint counts
		metadata.CheckpointsCount = existingMetadata.CheckpointsCount + opts.CheckpointsCount
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal metadata: %w", err)
	}
	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return err
	}
	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
		Name: basePath + paths.MetadataFileName,
		Mode: filemode.Regular,
		Hash: metadataHash,
	}
	return nil
}

// mergeFilesTouched combines two file lists, removing duplicates.
func mergeFilesTouched(existing, additional []string) []string {
	seen := make(map[string]bool)
	var result []string

	for _, f := range existing {
		if !seen[f] {
			seen[f] = true
			result = append(result, f)
		}
	}
	for _, f := range additional {
		if !seen[f] {
			seen[f] = true
			result = append(result, f)
		}
	}

	sort.Strings(result)
	return result
}

// readMetadataFromBlob reads CommittedMetadata from a blob hash.
func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
	blob, err := s.repo.BlobObject(hash)
	if err != nil {
		return nil, fmt.Errorf("failed to get blob: %w", err)
	}

	reader, err := blob.Reader()
	if err != nil {
		return nil, fmt.Errorf("failed to get blob reader: %w", err)
	}
	defer reader.Close()

	var metadata CommittedMetadata
	if err := json.NewDecoder(reader).Decode(&metadata); err != nil {
		return nil, fmt.Errorf("failed to decode metadata: %w", err)
	}

	return &metadata, nil
}

// archiveExistingSession moves existing session files to a numbered subfolder.
// The subfolder number is based on the current session count (so first archived session goes to "1/").
func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
	// Determine archive folder number
	sessionCount := existingMetadata.SessionCount
	if sessionCount == 0 {
		sessionCount = 1 // backwards compat
	}
	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)

	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
	filesToArchive := []string{
		paths.MetadataFileName,
		paths.TranscriptFileName,
		paths.PromptFileName,
		paths.ContextFileName,
		paths.ContentHashFileName,
	}

	// Move each file to archive folder
	for _, filename := range filesToArchive {
		srcPath := basePath + filename
		if entry, exists := entries[srcPath]; exists {
			// Add to archive location
			dstPath := archivePath + filename
			entries[dstPath] = object.TreeEntry{
				Name: dstPath,
				Mode: entry.Mode,
				Hash: entry.Hash,
			}
			// Remove from original location (will be overwritten by new session)
			delete(entries, srcPath)
		}
	}
}

// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
// Returns sessions ordered by folder index (oldest first).
func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int) []ArchivedSession {
	var archived []ArchivedSession

	// Archived sessions are in numbered folders: 1/, 2/, etc.
	// The most recent session is at the root level (not archived).
	// Session count N means there are N-1 archived sessions.
	for i := 1; i < sessionCount; i++ {
		folderName := strconv.Itoa(i)

		// Try to get the archived session subtree
		subTree, err := checkpointTree.Tree(folderName)
		if err != nil {
			continue // Folder doesn't exist, skip
		}

		session := ArchivedSession{
			FolderIndex: i,
		}

		// Read metadata to get session ID
		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
			if content, contentErr := metadataFile.Contents(); contentErr == nil {
				var metadata CommittedMetadata
				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
					session.SessionID = metadata.SessionID
				}
			}
		}

		// Read transcript (try current format first, then legacy)
		if file, fileErr := subTree.File(paths.TranscriptFileName); fileErr == nil {
			if content, contentErr := file.Contents(); contentErr == nil {
				session.Transcript = []byte(content)
			}
		} else if file, fileErr := subTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
			if content, contentErr := file.Contents(); contentErr == nil {
				session.Transcript = []byte(content)
			}
		}

		// Read prompts
		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
			if content, contentErr := file.Contents(); contentErr == nil {
				session.Prompts = content
			}
		}

		// Only add if we got a transcript
		if len(session.Transcript) > 0 {
			archived = append(archived, session)
		}
	}

	return archived
}

// buildCommitMessage constructs the commit message with proper trailers.
// The commit subject is always "Checkpoint: <id>" for consistency.
// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
	var commitMsg strings.Builder

	// Subject line is always the checkpoint ID for consistent formatting
	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))

	// Include custom description in body if provided (e.g., task checkpoint details)
	if opts.CommitSubject != "" {
		commitMsg.WriteString(opts.CommitSubject + "\n\n")
	}
	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
	if opts.Agent != "" {
		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
	}
	if opts.EphemeralBranch != "" {
		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
	}
	if taskMetadataPath != "" {
		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", paths.MetadataTaskTrailerKey, taskMetadataPath))
	}

	return commitMsg.String()
}

// incrementalCheckpointData represents an incremental checkpoint during subagent execution.
// This mirrors strategy.SubagentCheckpoint but avoids import cycles.
type incrementalCheckpointData struct {
	Type      string          `json:"type"`
	ToolUseID string          `json:"tool_use_id"`
	Timestamp time.Time       `json:"timestamp"`
	Data      json.RawMessage `json:"data"`
}

// taskCheckpointData represents a final task checkpoint.
// This mirrors strategy.TaskCheckpoint but avoids import cycles.
type taskCheckpointData struct {
	SessionID      string `json:"session_id"`
	ToolUseID      string `json:"tool_use_id"`
	CheckpointUUID string `json:"checkpoint_uuid"`
	AgentID        string `json:"agent_id,omitempty"`
}

// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
// Returns nil, nil if the checkpoint doesn't exist.
//

func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID string) (*ReadCommittedResult, error) {
	_ = ctx // Reserved for future use

	tree, err := s.getSessionsBranchTree()
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
	}

	checkpointPath := trailers.CheckpointPath(checkpointID)
	checkpointTree, err := tree.Tree(checkpointPath)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
	}

	result := &ReadCommittedResult{}

	// Read metadata.json
	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
		if content, contentErr := metadataFile.Contents(); contentErr == nil {
			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
			json.Unmarshal([]byte(content), &result.Metadata)
			result.Metadata.Strategy = paths.NormalizeStrategyName(result.Metadata.Strategy)
		}
	}

	// Read transcript (try current format first, then legacy)
	if file, fileErr := checkpointTree.File(paths.TranscriptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Transcript = []byte(content)
		}
	} else if file, fileErr := checkpointTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Transcript = []byte(content)
		}
	}

	// Read prompts
	if file, fileErr := checkpointTree.File(paths.PromptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Prompts = content
		}
	}

	// Read context
	if file, fileErr := checkpointTree.File(paths.ContextFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Context = content
		}
	}

	// Read archived sessions if this is a multi-session checkpoint
	if result.Metadata.SessionCount > 1 {
		result.ArchivedSessions = s.readArchivedSessions(checkpointTree, result.Metadata.SessionCount)
	}

	return result, nil
}

// ListCommitted lists all committed checkpoints from the entire/sessions branch.
// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
//

func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
	_ = ctx // Reserved for future use

	tree, err := s.getSessionsBranchTree()
	if err != nil {
		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
	}

	var checkpoints []CommittedInfo

	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
	for _, bucketEntry := range tree.Entries {
		if bucketEntry.Mode != filemode.Dir {
			continue
		}
		// Bucket should be 2 hex chars
		if len(bucketEntry.Name) != 2 {
			continue
		}

		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
		if treeErr != nil {
			continue
		}

		// Each entry in the bucket is the remaining part of the checkpoint ID
		for _, checkpointEntry := range bucketTree.Entries {
			if checkpointEntry.Mode != filemode.Dir {
				continue
			}

			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
			if cpTreeErr != nil {
				continue
			}

			// Reconstruct checkpoint ID: <bucket><remaining>
			checkpointID := bucketEntry.Name + checkpointEntry.Name

			info := CommittedInfo{
				CheckpointID: checkpointID,
			}

			// Get details from metadata file
			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
				if content, contentErr := metadataFile.Contents(); contentErr == nil {
					var metadata CommittedMetadata
					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
						info.SessionID = metadata.SessionID
						info.CreatedAt = metadata.CreatedAt
						info.CheckpointsCount = metadata.CheckpointsCount
						info.FilesTouched = metadata.FilesTouched
						info.Agent = metadata.Agent
						info.IsTask = metadata.IsTask
						info.ToolUseID = metadata.ToolUseID
						info.SessionCount = metadata.SessionCount
						info.SessionIDs = metadata.SessionIDs
					}
				}
			}

			checkpoints = append(checkpoints, info)
		}
	}

	// Sort by time (most recent first)
	sort.Slice(checkpoints, func(i, j int) bool {
		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
	})

	return checkpoints, nil
}

// GetTranscript retrieves the transcript for a specific checkpoint ID.
func (s *GitStore) GetTranscript(ctx context.Context, checkpointID string) ([]byte, error) {
	result, err := s.ReadCommitted(ctx, checkpointID)
	if err != nil {
		return nil, err
	}
	if result == nil {
		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
	}
	if len(result.Transcript) == 0 {
		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
	}
	return result.Transcript, nil
}

// ensureSessionsBranch ensures the entire/sessions branch exists.
func (s *GitStore) ensureSessionsBranch() error {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	_, err := s.repo.Reference(refName, true)
	if err == nil {
		return nil // Branch exists
	}

	// Create orphan branch with empty tree
	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return err
	}

	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
	if err != nil {
		return err
	}

	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}
	return nil
}

// getSessionsBranchTree returns the tree object for the entire/sessions branch.
func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, fmt.Errorf("sessions branch not found: %w", err)
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	return tree, nil
}

// CreateBlobFromContent creates a blob object from in-memory content.
// Exported for use by strategy package (session_test.go)
func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(content)))

	writer, err := obj.Writer()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
	}

	_, err = writer.Write(content)
	if err != nil {
		_ = writer.Close()
		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
	}
	if err := writer.Close(); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
	}
	return hash, nil
}

// copyMetadataDir copies all files from a directory to the checkpoint path.
// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		// Skip symlinks to prevent reading files outside the metadata directory.
		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
		// then be captured in the checkpoint and stored in git history.
		if info.Mode()&os.ModeSymlink != 0 {
			return nil
		}

		// Get relative path within metadata dir
		relPath, err := filepath.Rel(metadataDir, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}

		// Prevent path traversal via symlinks pointing outside the metadata dir
		if strings.HasPrefix(relPath, "..") {
			return fmt.Errorf("path traversal detected: %s", relPath)
		}

		// Create blob from file
		blobHash, mode, err := createBlobFromFile(s.repo, path)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}

		// Store at checkpoint path
		fullPath := basePath + relPath
		entries[fullPath] = object.TreeEntry{
			Name: fullPath,
			Mode: mode,
			Hash: blobHash,
		}

		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk metadata directory: %w", err)
	}
	return nil
}

// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
	// Get repository config (includes local settings)
	cfg, err := repo.Config()
	if err == nil {
		name = cfg.User.Name
		email = cfg.User.Email
	}

	// Provide sensible defaults if git user is not configured
	if name == "" {
		name = "Unknown"
	}
	if email == "" {
		email = "unknown@local"
	}

	return name, email
}

package checkpoint

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// WriteCommitted writes a committed checkpoint to the entire/sessions branch.
// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
//
// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
	_ = ctx // Reserved for future use

	// Validate identifiers to prevent path traversal and malformed data
	if err := trailers.ValidateCheckpointID(opts.CheckpointID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}
	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
		return fmt.Errorf("invalid checkpoint options: %w", err)
	}

	// Ensure sessions branch exists
	if err := s.ensureSessionsBranch(); err != nil {
		return fmt.Errorf("failed to ensure sessions branch: %w", err)
	}

	// Get current branch tip and flatten tree
	ref, entries, err := s.getSessionsBranchEntries()
	if err != nil {
		return err
	}

	// Use sharded path: <id[:2]>/<id[2:]>/
	basePath := trailers.CheckpointPath(opts.CheckpointID) + "/"

	// Track task metadata path for commit trailer
	var taskMetadataPath string

	// Handle task checkpoints
	if opts.IsTask && opts.ToolUseID != "" {
		taskMetadataPath, err = s.writeTaskCheckpointEntries(opts, basePath, entries)
		if err != nil {
			return err
		}
	}

	// Write standard checkpoint entries (transcript, prompts, context, metadata)
	if err := s.writeStandardCheckpointEntries(opts, basePath, entries); err != nil {
		return err
	}

	// Build and commit
	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
	if err != nil {
		return err
	}

	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return err
	}

	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	newRef := plumbing.NewHashReference(refName, newCommitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}

	return nil
}

// getSessionsBranchEntries returns the sessions branch reference and flattened tree entries.
func (s *GitStore) getSessionsBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get sessions branch reference: %w", err)
	}

	parentCommit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	baseTree, err := parentCommit.Tree()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return nil, nil, err
	}

	return ref, entries, nil
}

// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
func (s *GitStore) writeTaskCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"

	if opts.IsIncremental {
		return s.writeIncrementalTaskCheckpoint(opts, taskPath, entries)
	}
	return s.writeFinalTaskCheckpoint(opts, taskPath, entries)
}

// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
	checkpoint := incrementalCheckpointData{
		Type:      opts.IncrementalType,
		ToolUseID: opts.ToolUseID,
		Timestamp: time.Now().UTC(),
		Data:      opts.IncrementalData,
	}
	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
	if err != nil {
		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
	}
	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
	if err != nil {
		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
	}

	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
	cpPath := taskPath + "checkpoints/" + cpFilename
	entries[cpPath] = object.TreeEntry{
		Name: cpPath,
		Mode: filemode.Regular,
		Hash: cpBlobHash,
	}
	return cpPath, nil
}

// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
	checkpoint := taskCheckpointData{
		SessionID:      opts.SessionID,
		ToolUseID:      opts.ToolUseID,
		CheckpointUUID: opts.CheckpointUUID,
		AgentID:        opts.AgentID,
	}
	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
	if err != nil {
		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
	}
	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
	if err != nil {
		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
	}

	checkpointFile := taskPath + "checkpoint.json"
	entries[checkpointFile] = object.TreeEntry{
		Name: checkpointFile,
		Mode: filemode.Regular,
		Hash: blobHash,
	}

	// Write subagent transcript if available
	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
		if readErr == nil {
			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
			if agentBlobErr == nil {
				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
				entries[agentPath] = object.TreeEntry{
					Name: agentPath,
					Mode: filemode.Regular,
					Hash: agentBlobHash,
				}
			}
		}
	}

	// Return task path without trailing slash
	return taskPath[:len(taskPath)-1], nil
}

// writeStandardCheckpointEntries writes transcript, prompts, context, metadata.json and any additional files.
// If the checkpoint already exists (from a previous session), archives the existing files to a numbered subfolder.
func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
	// Check if checkpoint already exists (multi-session support)
	var existingMetadata *CommittedMetadata
	metadataPath := basePath + paths.MetadataFileName
	if entry, exists := entries[metadataPath]; exists {
		// Read existing metadata to get session count
		existing, err := s.readMetadataFromBlob(entry.Hash)
		if err == nil {
			existingMetadata = existing
			// Archive existing session files to numbered subfolder
			s.archiveExistingSession(basePath, existingMetadata, entries)
		}
	}

	// Write transcript (from in-memory content or file path)
	if err := s.writeTranscript(opts, basePath, entries); err != nil {
		return err
	}

	// Write prompts
	if len(opts.Prompts) > 0 {
		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
		if err != nil {
			return err
		}
		entries[basePath+paths.PromptFileName] = object.TreeEntry{
			Name: basePath + paths.PromptFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Write context
	if len(opts.Context) > 0 {
		blobHash, err := CreateBlobFromContent(s.repo, opts.Context)
		if err != nil {
			return err
		}
		entries[basePath+paths.ContextFileName] = object.TreeEntry{
			Name: basePath + paths.ContextFileName,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Copy additional metadata files from directory if specified
	if opts.MetadataDir != "" {
		if err := s.copyMetadataDir(opts.MetadataDir, basePath, entries); err != nil {
			return fmt.Errorf("failed to copy metadata directory: %w", err)
		}
	}

	// Write metadata.json (with merged info if existing metadata present)
	return s.writeMetadataJSON(opts, basePath, entries, existingMetadata)
}

// writeTranscript writes the transcript file from in-memory content or file path.
func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
	transcript := opts.Transcript
	if len(transcript) == 0 && opts.TranscriptPath != "" {
		var readErr error
		transcript, readErr = os.ReadFile(opts.TranscriptPath)
		if readErr != nil {
			// Non-fatal: transcript may not exist yet
			transcript = nil
		}
	}
	if len(transcript) == 0 {
		return nil
	}

	blobHash, err := CreateBlobFromContent(s.repo, transcript)
	if err != nil {
		return err
	}
	entries[basePath+paths.TranscriptFileName] = object.TreeEntry{
		Name: basePath + paths.TranscriptFileName,
		Mode: filemode.Regular,
		Hash: blobHash,
	}

	// Content hash for deduplication
	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
	if err != nil {
		return err
	}
	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
		Name: basePath + paths.ContentHashFileName,
		Mode: filemode.Regular,
		Hash: hashBlob,
	}
	return nil
}

// writeMetadataJSON writes the metadata.json file for the checkpoint.
// If existingMetadata is provided, merges session info from the previous session(s).
func (s *GitStore) writeMetadataJSON(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingMetadata *CommittedMetadata) error {
	metadata := CommittedMetadata{
		CheckpointID:           opts.CheckpointID,
		SessionID:              opts.SessionID,
		Strategy:               opts.Strategy,
		CreatedAt:              time.Now(),
		Branch:                 opts.Branch,
		CheckpointsCount:       opts.CheckpointsCount,
		FilesTouched:           opts.FilesTouched,
		Agent:                  opts.Agent,
		IsTask:                 opts.IsTask,
		ToolUseID:              opts.ToolUseID,
		SessionCount:           1,
		SessionIDs:             []string{opts.SessionID},
		TranscriptUUIDAtStart:  opts.TranscriptUUIDAtStart,
		TranscriptLinesAtStart: opts.TranscriptLinesAtStart,
		TokenUsage:             opts.TokenUsage,
	}

	// Merge with existing metadata if present (multi-session checkpoint)
	if existingMetadata != nil {
		// Get existing session count (default to 1 for backwards compat)
		existingCount := existingMetadata.SessionCount
		if existingCount == 0 {
			existingCount = 1
		}
		metadata.SessionCount = existingCount + 1

		// Merge session IDs
		existingIDs := existingMetadata.SessionIDs
		if len(existingIDs) == 0 {
			// Backwards compat: old metadata only had SessionID
			existingIDs = []string{existingMetadata.SessionID}
		}
		metadata.SessionIDs = append(metadata.SessionIDs[:0], existingIDs...)
		metadata.SessionIDs = append(metadata.SessionIDs, opts.SessionID)

		// Merge files touched (deduplicated)
		metadata.FilesTouched = mergeFilesTouched(existingMetadata.FilesTouched, opts.FilesTouched)

		// Sum checkpoint counts
		metadata.CheckpointsCount = existingMetadata.CheckpointsCount + opts.CheckpointsCount
	}

	metadataJSON, err := jsonutil.MarshalIndentWithNewline(metadata, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal metadata: %w", err)
	}
	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
	if err != nil {
		return err
	}
	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
		Name: basePath + paths.MetadataFileName,
		Mode: filemode.Regular,
		Hash: metadataHash,
	}
	return nil
}

// mergeFilesTouched combines two file lists, removing duplicates.
func mergeFilesTouched(existing, additional []string) []string {
	seen := make(map[string]bool)
	var result []string

	for _, f := range existing {
		if !seen[f] {
			seen[f] = true
			result = append(result, f)
		}
	}
	for _, f := range additional {
		if !seen[f] {
			seen[f] = true
			result = append(result, f)
		}
	}

	sort.Strings(result)
	return result
}

// readMetadataFromBlob reads CommittedMetadata from a blob hash.
func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
	blob, err := s.repo.BlobObject(hash)
	if err != nil {
		return nil, fmt.Errorf("failed to get blob: %w", err)
	}

	reader, err := blob.Reader()
	if err != nil {
		return nil, fmt.Errorf("failed to get blob reader: %w", err)
	}
	defer reader.Close()

	var metadata CommittedMetadata
	if err := json.NewDecoder(reader).Decode(&metadata); err != nil {
		return nil, fmt.Errorf("failed to decode metadata: %w", err)
	}

	return &metadata, nil
}

// archiveExistingSession moves existing session files to a numbered subfolder.
// The subfolder number is based on the current session count (so first archived session goes to "1/").
func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
	// Determine archive folder number
	sessionCount := existingMetadata.SessionCount
	if sessionCount == 0 {
		sessionCount = 1 // backwards compat
	}
	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)

	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
	filesToArchive := []string{
		paths.MetadataFileName,
		paths.TranscriptFileName,
		paths.PromptFileName,
		paths.ContextFileName,
		paths.ContentHashFileName,
	}

	// Move each file to archive folder
	for _, filename := range filesToArchive {
		srcPath := basePath + filename
		if entry, exists := entries[srcPath]; exists {
			// Add to archive location
			dstPath := archivePath + filename
			entries[dstPath] = object.TreeEntry{
				Name: dstPath,
				Mode: entry.Mode,
				Hash: entry.Hash,
			}
			// Remove from original location (will be overwritten by new session)
			delete(entries, srcPath)
		}
	}
}

// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
// Returns sessions ordered by folder index (oldest first).
func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int) []ArchivedSession {
	var archived []ArchivedSession

	// Archived sessions are in numbered folders: 1/, 2/, etc.
	// The most recent session is at the root level (not archived).
	// Session count N means there are N-1 archived sessions.
	for i := 1; i < sessionCount; i++ {
		folderName := strconv.Itoa(i)

		// Try to get the archived session subtree
		subTree, err := checkpointTree.Tree(folderName)
		if err != nil {
			continue // Folder doesn't exist, skip
		}

		session := ArchivedSession{
			FolderIndex: i,
		}

		// Read metadata to get session ID
		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
			if content, contentErr := metadataFile.Contents(); contentErr == nil {
				var metadata CommittedMetadata
				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
					session.SessionID = metadata.SessionID
				}
			}
		}

		// Read transcript (try current format first, then legacy)
		if file, fileErr := subTree.File(paths.TranscriptFileName); fileErr == nil {
			if content, contentErr := file.Contents(); contentErr == nil {
				session.Transcript = []byte(content)
			}
		} else if file, fileErr := subTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
			if content, contentErr := file.Contents(); contentErr == nil {
				session.Transcript = []byte(content)
			}
		}

		// Read prompts
		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
			if content, contentErr := file.Contents(); contentErr == nil {
				session.Prompts = content
			}
		}

		// Only add if we got a transcript
		if len(session.Transcript) > 0 {
			archived = append(archived, session)
		}
	}

	return archived
}

// buildCommitMessage constructs the commit message with proper trailers.
// The commit subject is always "Checkpoint: <id>" for consistency.
// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
	var commitMsg strings.Builder

	// Subject line is always the checkpoint ID for consistent formatting
	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))

	// Include custom description in body if provided (e.g., task checkpoint details)
	if opts.CommitSubject != "" {
		commitMsg.WriteString(opts.CommitSubject + "\n\n")
	}
	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
	if opts.Agent != "" {
		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
	}
	if opts.EphemeralBranch != "" {
		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
	}
	if taskMetadataPath != "" {
		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
	}

	return commitMsg.String()
}

// incrementalCheckpointData represents an incremental checkpoint during subagent execution.
// This mirrors strategy.SubagentCheckpoint but avoids import cycles.
type incrementalCheckpointData struct {
	Type      string          `json:"type"`
	ToolUseID string          `json:"tool_use_id"`
	Timestamp time.Time       `json:"timestamp"`
	Data      json.RawMessage `json:"data"`
}

// taskCheckpointData represents a final task checkpoint.
// This mirrors strategy.TaskCheckpoint but avoids import cycles.
type taskCheckpointData struct {
	SessionID      string `json:"session_id"`
	ToolUseID      string `json:"tool_use_id"`
	CheckpointUUID string `json:"checkpoint_uuid"`
	AgentID        string `json:"agent_id,omitempty"`
}

// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
// Returns nil, nil if the checkpoint doesn't exist.
//

func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID string) (*ReadCommittedResult, error) {
	_ = ctx // Reserved for future use

	tree, err := s.getSessionsBranchTree()
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
	}

	checkpointPath := trailers.CheckpointPath(checkpointID)
	checkpointTree, err := tree.Tree(checkpointPath)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
	}

	result := &ReadCommittedResult{}

	// Read metadata.json
	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
		if content, contentErr := metadataFile.Contents(); contentErr == nil {
			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
			json.Unmarshal([]byte(content), &result.Metadata)
			result.Metadata.Strategy = paths.NormalizeStrategyName(result.Metadata.Strategy)
		}
	}

	// Read transcript (try current format first, then legacy)
	if file, fileErr := checkpointTree.File(paths.TranscriptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Transcript = []byte(content)
		}
	} else if file, fileErr := checkpointTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Transcript = []byte(content)
		}
	}

	// Read prompts
	if file, fileErr := checkpointTree.File(paths.PromptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Prompts = content
		}
	}

	// Read context
	if file, fileErr := checkpointTree.File(paths.ContextFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			result.Context = content
		}
	}

	// Read archived sessions if this is a multi-session checkpoint
	if result.Metadata.SessionCount > 1 {
		result.ArchivedSessions = s.readArchivedSessions(checkpointTree, result.Metadata.SessionCount)
	}

	return result, nil
}

// ListCommitted lists all committed checkpoints from the entire/sessions branch.
// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
//

func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
	_ = ctx // Reserved for future use

	tree, err := s.getSessionsBranchTree()
	if err != nil {
		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
	}

	var checkpoints []CommittedInfo

	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
	for _, bucketEntry := range tree.Entries {
		if bucketEntry.Mode != filemode.Dir {
			continue
		}
		// Bucket should be 2 hex chars
		if len(bucketEntry.Name) != 2 {
			continue
		}

		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
		if treeErr != nil {
			continue
		}

		// Each entry in the bucket is the remaining part of the checkpoint ID
		for _, checkpointEntry := range bucketTree.Entries {
			if checkpointEntry.Mode != filemode.Dir {
				continue
			}

			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
			if cpTreeErr != nil {
				continue
			}

			// Reconstruct checkpoint ID: <bucket><remaining>
			checkpointID := bucketEntry.Name + checkpointEntry.Name

			info := CommittedInfo{
				CheckpointID: checkpointID,
			}

			// Get details from metadata file
			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
				if content, contentErr := metadataFile.Contents(); contentErr == nil {
					var metadata CommittedMetadata
					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
						info.SessionID = metadata.SessionID
						info.CreatedAt = metadata.CreatedAt
						info.CheckpointsCount = metadata.CheckpointsCount
						info.FilesTouched = metadata.FilesTouched
						info.Agent = metadata.Agent
						info.IsTask = metadata.IsTask
						info.ToolUseID = metadata.ToolUseID
						info.SessionCount = metadata.SessionCount
						info.SessionIDs = metadata.SessionIDs
					}
				}
			}

			checkpoints = append(checkpoints, info)
		}
	}

	// Sort by time (most recent first)
	sort.Slice(checkpoints, func(i, j int) bool {
		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
	})

	return checkpoints, nil
}

// GetTranscript retrieves the transcript for a specific checkpoint ID.
func (s *GitStore) GetTranscript(ctx context.Context, checkpointID string) ([]byte, error) {
	result, err := s.ReadCommitted(ctx, checkpointID)
	if err != nil {
		return nil, err
	}
	if result == nil {
		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
	}
	if len(result.Transcript) == 0 {
		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
	}
	return result.Transcript, nil
}

// ensureSessionsBranch ensures the entire/sessions branch exists.
func (s *GitStore) ensureSessionsBranch() error {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	_, err := s.repo.Reference(refName, true)
	if err == nil {
		return nil // Branch exists
	}

	// Create orphan branch with empty tree
	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
	if err != nil {
		return err
	}

	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
	if err != nil {
		return err
	}

	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to set branch reference: %w", err)
	}
	return nil
}

// getSessionsBranchTree returns the tree object for the entire/sessions branch.
func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, fmt.Errorf("sessions branch not found: %w", err)
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	return tree, nil
}

// CreateBlobFromContent creates a blob object from in-memory content.
// Exported for use by strategy package (session_test.go)
func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(content)))

	writer, err := obj.Writer()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
	}

	_, err = writer.Write(content)
	if err != nil {
		_ = writer.Close()
		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
	}
	if err := writer.Close(); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
	}
	return hash, nil
}

// copyMetadataDir copies all files from a directory to the checkpoint path.
// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		// Skip symlinks to prevent reading files outside the metadata directory.
		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
		// then be captured in the checkpoint and stored in git history.
		if info.Mode()&os.ModeSymlink != 0 {
			return nil
		}

		// Get relative path within metadata dir
		relPath, err := filepath.Rel(metadataDir, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}

		// Prevent path traversal via symlinks pointing outside the metadata dir
		if strings.HasPrefix(relPath, "..") {
			return fmt.Errorf("path traversal detected: %s", relPath)
		}

		// Create blob from file
		blobHash, mode, err := createBlobFromFile(s.repo, path)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}

		// Store at checkpoint path
		fullPath := basePath + relPath
		entries[fullPath] = object.TreeEntry{
			Name: fullPath,
			Mode: mode,
			Hash: blobHash,
		}

		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk metadata directory: %w", err)
	}
	return nil
}

// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
	// Get repository config (includes local settings)
	cfg, err := repo.Config()
	if err == nil {
		name = cfg.User.Name
		email = cfg.User.Email
	}

	// Provide sensible defaults if git user is not configured
	if name == "" {
		name = "Unknown"
	}
	if email == "" {
		email = "unknown@local"
	}

	return name, email
}

package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	// ShadowBranchPrefix is the prefix for shadow branches.
	ShadowBranchPrefix = "entire/"

	// ShadowBranchHashLength is the number of hex characters used in shadow branch names.
	// Shadow branches are named "entire/<hash>" using the first 7 characters of the commit hash.
	ShadowBranchHashLength = 7

	// gitDir and entireDir are excluded from tree operations.
	gitDir    = ".git"
	entireDir = ".entire"
)

// WriteTemporary writes a temporary checkpoint to a shadow branch.
// Shadow branches are named entire/<base-commit-short-hash>.
// Returns the result containing commit hash and whether it was skipped.
// If the new tree hash matches the last checkpoint's tree hash, the checkpoint
// is skipped to avoid duplicate commits (deduplication).
func (s *GitStore) WriteTemporary(ctx context.Context, opts WriteTemporaryOptions) (WriteTemporaryResult, error) {
	_ = ctx // Reserved for future use (e.g., cancellation)

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return WriteTemporaryResult{}, errors.New("BaseCommit is required for temporary checkpoint")
	}

	// Validate session ID to prevent path traversal
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("invalid temporary checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Get the last checkpoint's tree hash for deduplication
	var lastTreeHash plumbing.Hash
	if parentHash != plumbing.ZeroHash {
		if lastCommit, err := s.repo.CommitObject(parentHash); err == nil {
			lastTreeHash = lastCommit.TreeHash
		}
	}

	// Collect all files to include
	var allFiles []string
	if opts.IsFirstCheckpoint {
		// For the first checkpoint of this session, capture ALL files in working directory
		// This ensures untracked files present at session start are included
		allFiles, err = collectWorkingDirectoryFiles()
		if err != nil {
			return WriteTemporaryResult{}, fmt.Errorf("failed to collect working directory files: %w", err)
		}
	} else {
		// For subsequent checkpoints, only include modified/new files
		allFiles = make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
		allFiles = append(allFiles, opts.ModifiedFiles...)
		allFiles = append(allFiles, opts.NewFiles...)
	}

	// Build tree with changes
	treeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, opts.MetadataDir, opts.MetadataDirAbs)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to build tree: %w", err)
	}

	// Deduplication: skip if tree hash matches the last checkpoint
	if lastTreeHash != plumbing.ZeroHash && treeHash == lastTreeHash {
		return WriteTemporaryResult{
			CommitHash: parentHash,
			Skipped:    true,
		}, nil
	}

	// Create checkpoint commit with trailers
	commitMsg := paths.FormatShadowCommitMessage(opts.CommitMessage, opts.MetadataDir, opts.SessionID)

	commitHash, err := s.createCommit(treeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to update branch reference: %w", err)
	}

	return WriteTemporaryResult{
		CommitHash: commitHash,
		Skipped:    false,
	}, nil
}

// ReadTemporary reads the latest checkpoint from a shadow branch.
// Returns nil if the shadow branch doesn't exist.
func (s *GitStore) ReadTemporary(ctx context.Context, baseCommit string) (*ReadTemporaryResult, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Branch not found is an expected case
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	// Extract session ID and metadata dir from commit trailers
	sessionID, _ := paths.ParseSessionTrailer(commit.Message)
	metadataDir, _ := paths.ParseMetadataTrailer(commit.Message)

	return &ReadTemporaryResult{
		CommitHash:  ref.Hash(),
		TreeHash:    commit.TreeHash,
		SessionID:   sessionID,
		MetadataDir: metadataDir,
		Timestamp:   commit.Author.When,
	}, nil
}

// ListTemporary lists all shadow branches with their checkpoint info.
func (s *GitStore) ListTemporary(ctx context.Context) ([]TemporaryInfo, error) {
	_ = ctx // Reserved for future use

	iter, err := s.repo.Branches()
	if err != nil {
		return nil, fmt.Errorf("failed to list branches: %w", err)
	}

	var results []TemporaryInfo
	err = iter.ForEach(func(ref *plumbing.Reference) error {
		branchName := ref.Name().Short()
		if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
			return nil
		}

		// Skip the sessions branch
		if branchName == paths.MetadataBranchName {
			return nil
		}

		commit, commitErr := s.repo.CommitObject(ref.Hash())
		if commitErr != nil {
			//nolint:nilerr // Skip branches we can't read (non-fatal)
			return nil
		}

		sessionID, _ := paths.ParseSessionTrailer(commit.Message)

		// Extract base commit from branch name
		baseCommit := strings.TrimPrefix(branchName, ShadowBranchPrefix)

		results = append(results, TemporaryInfo{
			BranchName:   branchName,
			BaseCommit:   baseCommit,
			LatestCommit: ref.Hash(),
			SessionID:    sessionID,
			Timestamp:    commit.Author.When,
		})

		return nil
	})

	if err != nil {
		return nil, fmt.Errorf("failed to iterate branches: %w", err)
	}

	return results, nil
}

// WriteTemporaryTask writes a task checkpoint to a shadow branch.
// Task checkpoints include both code changes and task-specific metadata.
// Returns the commit hash of the created checkpoint.
func (s *GitStore) WriteTemporaryTask(ctx context.Context, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	_ = ctx // Reserved for future use

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return plumbing.ZeroHash, errors.New("BaseCommit is required for task checkpoint")
	}

	// Validate identifiers to prevent path traversal and malformed data
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Collect all files to include in the commit
	allFiles := make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
	allFiles = append(allFiles, opts.ModifiedFiles...)
	allFiles = append(allFiles, opts.NewFiles...)

	// Build new tree with code changes (no metadata dir yet)
	newTreeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, "", "")
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to build tree: %w", err)
	}

	// Add task metadata to tree
	newTreeHash, err = s.addTaskMetadataToTree(newTreeHash, opts)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to add task metadata: %w", err)
	}

	// Create the commit
	commitHash, err := s.createCommit(newTreeHash, parentHash, opts.CommitMessage, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update shadow branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to update shadow branch reference: %w", err)
	}

	return commitHash, nil
}

// addTaskMetadataToTree adds task checkpoint metadata to a git tree.
// When IsIncremental is true, only adds the incremental checkpoint file.
func (s *GitStore) addTaskMetadataToTree(baseTreeHash plumbing.Hash, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	// Get base tree and flatten it
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten tree: %w", err)
	}

	// Compute metadata paths
	sessionMetadataDir := paths.EntireMetadataDir + "/" + opts.SessionID
	taskMetadataDir := sessionMetadataDir + "/tasks/" + opts.ToolUseID

	if opts.IsIncremental {
		// Incremental checkpoint: only add the checkpoint file
		// Use proper JSON marshaling to handle nil/empty IncrementalData correctly
		incrementalCheckpoint := struct {
			Type      string          `json:"type"`
			ToolUseID string          `json:"tool_use_id"`
			Timestamp time.Time       `json:"timestamp"`
			Data      json.RawMessage `json:"data"`
		}{
			Type:      opts.IncrementalType,
			ToolUseID: opts.ToolUseID,
			Timestamp: time.Now().UTC(),
			Data:      opts.IncrementalData,
		}
		cpData, err := jsonutil.MarshalIndentWithNewline(incrementalCheckpoint, "", "  ")
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
		}

		cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
		}
		cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
		cpPath := taskMetadataDir + "/checkpoints/" + cpFilename
		entries[cpPath] = object.TreeEntry{
			Name: cpPath,
			Mode: filemode.Regular,
			Hash: cpBlobHash,
		}
	} else {
		// Final checkpoint: add transcripts and checkpoint.json

		// Add session transcript
		if opts.TranscriptPath != "" {
			if transcriptContent, readErr := os.ReadFile(opts.TranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, transcriptContent); blobErr == nil {
					transcriptPath := sessionMetadataDir + "/" + paths.TranscriptFileName
					entries[transcriptPath] = object.TreeEntry{
						Name: transcriptPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add subagent transcript if available
		if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
			if agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, agentContent); blobErr == nil {
					agentPath := taskMetadataDir + "/agent-" + opts.AgentID + ".jsonl"
					entries[agentPath] = object.TreeEntry{
						Name: agentPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add checkpoint.json
		checkpointJSON := fmt.Sprintf(`{
  "session_id": %q,
  "tool_use_id": %q,
  "checkpoint_uuid": %q,
  "agent_id": %q
}`, opts.SessionID, opts.ToolUseID, opts.CheckpointUUID, opts.AgentID)

		blobHash, err := CreateBlobFromContent(s.repo, []byte(checkpointJSON))
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint blob: %w", err)
		}
		checkpointPath := taskMetadataDir + "/checkpoint.json"
		entries[checkpointPath] = object.TreeEntry{
			Name: checkpointPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Build new tree from entries
	return BuildTreeFromEntries(s.repo, entries)
}

// ListTemporaryCheckpoints lists all checkpoint commits on a shadow branch.
// This returns individual commits (rewind points), not just branch info.
// The sessionID filter, if provided, limits results to commits from that session.
func (s *GitStore) ListTemporaryCheckpoints(ctx context.Context, baseCommit string, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilerr // No shadow branch is expected case
	}

	iter, err := s.repo.Log(&git.LogOptions{From: ref.Hash()})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var results []TemporaryCheckpointInfo
	count := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= limit*5 { // Scan more to allow for session filtering
			return errStop
		}
		count++

		// Verify commit belongs to target session via Entire-Session trailer
		commitSessionID, hasTrailer := paths.ParseSessionTrailer(c.Message)
		if !hasTrailer {
			return nil // Skip commits without session trailer
		}
		if sessionID != "" && commitSessionID != sessionID {
			return nil // Skip commits from other sessions
		}

		// Get first line of message
		message := c.Message
		if idx := strings.Index(message, "\n"); idx > 0 {
			message = message[:idx]
		}

		info := TemporaryCheckpointInfo{
			CommitHash: c.Hash,
			Message:    message,
			SessionID:  commitSessionID,
			Timestamp:  c.Author.When,
		}

		// Check for task checkpoint first
		taskMetadataDir, foundTask := paths.ParseTaskMetadataTrailer(c.Message)
		if foundTask {
			info.IsTaskCheckpoint = true
			info.MetadataDir = taskMetadataDir
			info.ToolUseID = extractToolUseIDFromPath(taskMetadataDir)
		} else {
			metadataDir, found := paths.ParseMetadataTrailer(c.Message)
			if found {
				info.MetadataDir = metadataDir
			}
		}

		results = append(results, info)

		if len(results) >= limit {
			return errStop
		}
		return nil
	})

	if err != nil && !errors.Is(err, errStop) {
		return nil, fmt.Errorf("error iterating commits: %w", err)
	}

	return results, nil
}

// extractToolUseIDFromPath extracts the ToolUseID from a task metadata directory path.
// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
func extractToolUseIDFromPath(metadataDir string) string {
	parts := strings.Split(metadataDir, "/")
	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
		return parts[len(parts)-1]
	}
	return ""
}

// errStop is a sentinel error used to break out of git log iteration.
var errStop = errors.New("stop iteration")

// ShadowBranchExists checks if a shadow branch exists for the given base commit.
func (s *GitStore) ShadowBranchExists(baseCommit string) bool {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	_, err := s.repo.Reference(refName, true)
	return err == nil
}

// DeleteShadowBranch deletes the shadow branch for the given base commit.
func (s *GitStore) DeleteShadowBranch(baseCommit string) error {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	if err := s.repo.Storer.RemoveReference(refName); err != nil {
		return fmt.Errorf("failed to delete shadow branch %s: %w", shadowBranchName, err)
	}
	return nil
}

// ShadowBranchNameForCommit returns the shadow branch name for a base commit hash.
// Uses the first ShadowBranchHashLength characters of the commit hash.
func ShadowBranchNameForCommit(baseCommit string) string {
	if len(baseCommit) >= ShadowBranchHashLength {
		return ShadowBranchPrefix + baseCommit[:ShadowBranchHashLength]
	}
	return ShadowBranchPrefix + baseCommit
}

// getOrCreateShadowBranch gets or creates the shadow branch for checkpoints.
// Returns (parentHash, baseTreeHash, error).
func (s *GitStore) getOrCreateShadowBranch(branchName string) (plumbing.Hash, plumbing.Hash, error) {
	refName := plumbing.NewBranchReferenceName(branchName)
	ref, err := s.repo.Reference(refName, true)

	if err == nil {
		// Branch exists
		commit, err := s.repo.CommitObject(ref.Hash())
		if err != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
		}
		return ref.Hash(), commit.TreeHash, nil
	}

	// Branch doesn't exist, use current HEAD's tree as base
	head, err := s.repo.Head()
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
	}

	headCommit, err := s.repo.CommitObject(head.Hash())
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	return plumbing.ZeroHash, headCommit.TreeHash, nil
}

// buildTreeWithChanges builds a git tree with the given changes.
// metadataDir is the relative path for git tree entries, metadataDirAbs is the absolute path
// for filesystem operations (needed when CLI is run from a subdirectory).
func (s *GitStore) buildTreeWithChanges(
	baseTreeHash plumbing.Hash,
	modifiedFiles, deletedFiles []string,
	metadataDir, metadataDirAbs string,
) (plumbing.Hash, error) {
	// Get repo root for resolving file paths
	// This is critical because fileExists() and createBlobFromFile() use os.Stat()
	// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
	// so we must resolve them against repo root, not CWD.
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get repo root: %w", err)
	}

	// Get the base tree
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	// Flatten existing tree
	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten base tree: %w", err)
	}

	// Remove deleted files
	for _, file := range deletedFiles {
		delete(entries, file)
	}

	// Add/update modified files
	for _, file := range modifiedFiles {
		// Resolve path relative to repo root for filesystem operations
		absPath := filepath.Join(repoRoot, file)
		if !fileExists(absPath) {
			delete(entries, file)
			continue
		}

		blobHash, mode, err := createBlobFromFile(s.repo, absPath)
		if err != nil {
			// Skip files that can't be staged (may have been deleted since detection)
			continue
		}

		entries[file] = object.TreeEntry{
			Name: file,
			Mode: mode,
			Hash: blobHash,
		}
	}

	// Add metadata directory files
	if metadataDir != "" && metadataDirAbs != "" {
		if err := addDirectoryToEntriesWithAbsPath(s.repo, metadataDirAbs, metadataDir, entries); err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", err)
		}
	}

	// Build tree
	return BuildTreeFromEntries(s.repo, entries)
}

// createCommit creates a commit object.
func (s *GitStore) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}

	// Add parent if not a new branch
	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	obj := s.repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := s.repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

// Helper functions extracted from strategy/common.go
// These are exported for use by strategy package (push_common.go, session_test.go)

// FlattenTree recursively flattens a tree into a map of full paths to entries.
func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
	for _, entry := range tree.Entries {
		fullPath := entry.Name
		if prefix != "" {
			fullPath = prefix + "/" + entry.Name
		}

		if entry.Mode == filemode.Dir {
			// Recurse into subtree
			subtree, err := repo.TreeObject(entry.Hash)
			if err != nil {
				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
			}
			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
				return err
			}
		} else {
			entries[fullPath] = object.TreeEntry{
				Name: fullPath,
				Mode: entry.Mode,
				Hash: entry.Hash,
			}
		}
	}
	return nil
}

// fileExists checks if a file exists at the given path.
func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// createBlobFromFile creates a blob object from a file in the working directory.
func createBlobFromFile(repo *git.Repository, filePath string) (plumbing.Hash, filemode.FileMode, error) {
	info, err := os.Stat(filePath)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
	}

	// Determine file mode
	mode := filemode.Regular
	if info.Mode()&0o111 != 0 {
		mode = filemode.Executable
	}
	if info.Mode()&os.ModeSymlink != 0 {
		mode = filemode.Symlink
	}

	// Read file contents
	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
	}

	// Create blob object
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(content)))

	writer, err := obj.Writer()
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
	}

	_, err = writer.Write(content)
	if err != nil {
		_ = writer.Close()
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to write blob content: %w", err)
	}
	if err := writer.Close(); err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to close blob writer: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to store blob object: %w", err)
	}

	return hash, mode, nil
}

// addDirectoryToEntriesWithAbsPath recursively adds all files in a directory to the entries map.
func addDirectoryToEntriesWithAbsPath(repo *git.Repository, dirPathAbs, dirPathRel string, entries map[string]object.TreeEntry) error {
	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		// Calculate relative path within the directory, then join with dirPathRel for tree entry
		relWithinDir, err := filepath.Rel(dirPathAbs, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}

		blobHash, mode, err := createBlobFromFile(repo, path)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}

		treePath := filepath.Join(dirPathRel, relWithinDir)
		entries[treePath] = object.TreeEntry{
			Name: treePath,
			Mode: mode,
			Hash: blobHash,
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
	}
	return nil
}

// treeNode represents a node in our tree structure.
type treeNode struct {
	entries map[string]*treeNode // subdirectories
	files   []object.TreeEntry   // files in this directory
}

// BuildTreeFromEntries builds a proper git tree structure from flattened file entries.
// Exported for use by strategy package (push_common.go, session_test.go)
func BuildTreeFromEntries(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	// Build a tree structure
	root := &treeNode{
		entries: make(map[string]*treeNode),
		files:   []object.TreeEntry{},
	}

	// Insert all entries into the tree structure
	for fullPath, entry := range entries {
		parts := strings.Split(fullPath, "/")
		insertIntoTree(root, parts, entry)
	}

	// Recursively build tree objects from bottom up
	return buildTreeObject(repo, root)
}

// insertIntoTree inserts a file entry into the tree structure.
func insertIntoTree(node *treeNode, pathParts []string, entry object.TreeEntry) {
	if len(pathParts) == 1 {
		// This is a file in the current directory
		node.files = append(node.files, object.TreeEntry{
			Name: pathParts[0],
			Mode: entry.Mode,
			Hash: entry.Hash,
		})
		return
	}

	// This is in a subdirectory
	dirName := pathParts[0]
	if node.entries[dirName] == nil {
		node.entries[dirName] = &treeNode{
			entries: make(map[string]*treeNode),
			files:   []object.TreeEntry{},
		}
	}
	insertIntoTree(node.entries[dirName], pathParts[1:], entry)
}

// buildTreeObject recursively builds tree objects from a treeNode.
func buildTreeObject(repo *git.Repository, node *treeNode) (plumbing.Hash, error) {
	var treeEntries []object.TreeEntry

	// Add files
	treeEntries = append(treeEntries, node.files...)

	// Recursively build subtrees
	for name, subnode := range node.entries {
		subHash, err := buildTreeObject(repo, subnode)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		treeEntries = append(treeEntries, object.TreeEntry{
			Name: name,
			Mode: filemode.Dir,
			Hash: subHash,
		})
	}

	// Sort entries (git requires sorted entries)
	sortTreeEntries(treeEntries)

	// Create tree object
	tree := &object.Tree{Entries: treeEntries}

	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
	}

	return hash, nil
}

// sortTreeEntries sorts tree entries in git's required order.
// Git sorts tree entries by name, with directories having a trailing /
func sortTreeEntries(entries []object.TreeEntry) {
	sort.Slice(entries, func(i, j int) bool {
		nameI := entries[i].Name
		nameJ := entries[j].Name
		if entries[i].Mode == filemode.Dir {
			nameI += "/"
		}
		if entries[j].Mode == filemode.Dir {
			nameJ += "/"
		}
		return nameI < nameJ
	})
}

// collectWorkingDirectoryFiles collects all files in the working directory.
// Excludes .git/ and .entire/ directories.
func collectWorkingDirectoryFiles() ([]string, error) {
	// Get repository root to walk from there
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "." // Fallback to current directory
	}

	var files []string
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		// Get path relative to repo root
		relPath, err := filepath.Rel(repoRoot, path)
		if err != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories
		if info.IsDir() {
			// Skip .git and .entire directories
			if relPath == gitDir || relPath == entireDir ||
				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		files = append(files, relPath)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to walk directory: %w", err)
	}

	return files, nil
}

package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	// ShadowBranchPrefix is the prefix for shadow branches.
	ShadowBranchPrefix = "entire/"

	// ShadowBranchHashLength is the number of hex characters used in shadow branch names.
	// Shadow branches are named "entire/<hash>" using the first 7 characters of the commit hash.
	ShadowBranchHashLength = 7

	// gitDir and entireDir are excluded from tree operations.
	gitDir    = ".git"
	entireDir = ".entire"
)

// WriteTemporary writes a temporary checkpoint to a shadow branch.
// Shadow branches are named entire/<base-commit-short-hash>.
// Returns the result containing commit hash and whether it was skipped.
// If the new tree hash matches the last checkpoint's tree hash, the checkpoint
// is skipped to avoid duplicate commits (deduplication).
func (s *GitStore) WriteTemporary(ctx context.Context, opts WriteTemporaryOptions) (WriteTemporaryResult, error) {
	_ = ctx // Reserved for future use (e.g., cancellation)

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return WriteTemporaryResult{}, errors.New("BaseCommit is required for temporary checkpoint")
	}

	// Validate session ID to prevent path traversal
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("invalid temporary checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Get the last checkpoint's tree hash for deduplication
	var lastTreeHash plumbing.Hash
	if parentHash != plumbing.ZeroHash {
		if lastCommit, err := s.repo.CommitObject(parentHash); err == nil {
			lastTreeHash = lastCommit.TreeHash
		}
	}

	// Collect all files to include
	var allFiles []string
	if opts.IsFirstCheckpoint {
		// For the first checkpoint of this session, capture ALL files in working directory
		// This ensures untracked files present at session start are included
		allFiles, err = collectWorkingDirectoryFiles()
		if err != nil {
			return WriteTemporaryResult{}, fmt.Errorf("failed to collect working directory files: %w", err)
		}
	} else {
		// For subsequent checkpoints, only include modified/new files
		allFiles = make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
		allFiles = append(allFiles, opts.ModifiedFiles...)
		allFiles = append(allFiles, opts.NewFiles...)
	}

	// Build tree with changes
	treeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, opts.MetadataDir, opts.MetadataDirAbs)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to build tree: %w", err)
	}

	// Deduplication: skip if tree hash matches the last checkpoint
	if lastTreeHash != plumbing.ZeroHash && treeHash == lastTreeHash {
		return WriteTemporaryResult{
			CommitHash: parentHash,
			Skipped:    true,
		}, nil
	}

	// Create checkpoint commit with trailers
	commitMsg := paths.FormatShadowCommitMessage(opts.CommitMessage, opts.MetadataDir, opts.SessionID)

	commitHash, err := s.createCommit(treeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to update branch reference: %w", err)
	}

	return WriteTemporaryResult{
		CommitHash: commitHash,
		Skipped:    false,
	}, nil
}

// ReadTemporary reads the latest checkpoint from a shadow branch.
// Returns nil if the shadow branch doesn't exist.
func (s *GitStore) ReadTemporary(ctx context.Context, baseCommit string) (*ReadTemporaryResult, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Branch not found is an expected case
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	// Extract session ID and metadata dir from commit trailers
	sessionID, _ := paths.ParseSessionTrailer(commit.Message)
	metadataDir, _ := paths.ParseMetadataTrailer(commit.Message)

	return &ReadTemporaryResult{
		CommitHash:  ref.Hash(),
		TreeHash:    commit.TreeHash,
		SessionID:   sessionID,
		MetadataDir: metadataDir,
		Timestamp:   commit.Author.When,
	}, nil
}

// ListTemporary lists all shadow branches with their checkpoint info.
func (s *GitStore) ListTemporary(ctx context.Context) ([]TemporaryInfo, error) {
	_ = ctx // Reserved for future use

	iter, err := s.repo.Branches()
	if err != nil {
		return nil, fmt.Errorf("failed to list branches: %w", err)
	}

	var results []TemporaryInfo
	err = iter.ForEach(func(ref *plumbing.Reference) error {
		branchName := ref.Name().Short()
		if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
			return nil
		}

		// Skip the sessions branch
		if branchName == paths.MetadataBranchName {
			return nil
		}

		commit, commitErr := s.repo.CommitObject(ref.Hash())
		if commitErr != nil {
			//nolint:nilerr // Skip branches we can't read (non-fatal)
			return nil
		}

		sessionID, _ := paths.ParseSessionTrailer(commit.Message)

		// Extract base commit from branch name
		baseCommit := strings.TrimPrefix(branchName, ShadowBranchPrefix)

		results = append(results, TemporaryInfo{
			BranchName:   branchName,
			BaseCommit:   baseCommit,
			LatestCommit: ref.Hash(),
			SessionID:    sessionID,
			Timestamp:    commit.Author.When,
		})

		return nil
	})

	if err != nil {
		return nil, fmt.Errorf("failed to iterate branches: %w", err)
	}

	return results, nil
}

// WriteTemporaryTask writes a task checkpoint to a shadow branch.
// Task checkpoints include both code changes and task-specific metadata.
// Returns the commit hash of the created checkpoint.
func (s *GitStore) WriteTemporaryTask(ctx context.Context, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	_ = ctx // Reserved for future use

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return plumbing.ZeroHash, errors.New("BaseCommit is required for task checkpoint")
	}

	// Validate identifiers to prevent path traversal and malformed data
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Collect all files to include in the commit
	allFiles := make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
	allFiles = append(allFiles, opts.ModifiedFiles...)
	allFiles = append(allFiles, opts.NewFiles...)

	// Build new tree with code changes (no metadata dir yet)
	newTreeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, "", "")
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to build tree: %w", err)
	}

	// Add task metadata to tree
	newTreeHash, err = s.addTaskMetadataToTree(newTreeHash, opts)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to add task metadata: %w", err)
	}

	// Create the commit
	commitHash, err := s.createCommit(newTreeHash, parentHash, opts.CommitMessage, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update shadow branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to update shadow branch reference: %w", err)
	}

	return commitHash, nil
}

// addTaskMetadataToTree adds task checkpoint metadata to a git tree.
// When IsIncremental is true, only adds the incremental checkpoint file.
func (s *GitStore) addTaskMetadataToTree(baseTreeHash plumbing.Hash, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	// Get base tree and flatten it
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten tree: %w", err)
	}

	// Compute metadata paths
	sessionMetadataDir := paths.EntireMetadataDir + "/" + opts.SessionID
	taskMetadataDir := sessionMetadataDir + "/tasks/" + opts.ToolUseID

	if opts.IsIncremental {
		// Incremental checkpoint: only add the checkpoint file
		// Use proper JSON marshaling to handle nil/empty IncrementalData correctly
		incrementalCheckpoint := struct {
			Type      string          `json:"type"`
			ToolUseID string          `json:"tool_use_id"`
			Timestamp time.Time       `json:"timestamp"`
			Data      json.RawMessage `json:"data"`
		}{
			Type:      opts.IncrementalType,
			ToolUseID: opts.ToolUseID,
			Timestamp: time.Now().UTC(),
			Data:      opts.IncrementalData,
		}
		cpData, err := jsonutil.MarshalIndentWithNewline(incrementalCheckpoint, "", "  ")
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
		}

		cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
		}
		cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
		cpPath := taskMetadataDir + "/checkpoints/" + cpFilename
		entries[cpPath] = object.TreeEntry{
			Name: cpPath,
			Mode: filemode.Regular,
			Hash: cpBlobHash,
		}
	} else {
		// Final checkpoint: add transcripts and checkpoint.json

		// Add session transcript
		if opts.TranscriptPath != "" {
			if transcriptContent, readErr := os.ReadFile(opts.TranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, transcriptContent); blobErr == nil {
					transcriptPath := sessionMetadataDir + "/" + paths.TranscriptFileName
					entries[transcriptPath] = object.TreeEntry{
						Name: transcriptPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add subagent transcript if available
		if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
			if agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, agentContent); blobErr == nil {
					agentPath := taskMetadataDir + "/agent-" + opts.AgentID + ".jsonl"
					entries[agentPath] = object.TreeEntry{
						Name: agentPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add checkpoint.json
		checkpointJSON := fmt.Sprintf(`{
  "session_id": %q,
  "tool_use_id": %q,
  "checkpoint_uuid": %q,
  "agent_id": %q
}`, opts.SessionID, opts.ToolUseID, opts.CheckpointUUID, opts.AgentID)

		blobHash, err := CreateBlobFromContent(s.repo, []byte(checkpointJSON))
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint blob: %w", err)
		}
		checkpointPath := taskMetadataDir + "/checkpoint.json"
		entries[checkpointPath] = object.TreeEntry{
			Name: checkpointPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Build new tree from entries
	return BuildTreeFromEntries(s.repo, entries)
}

// ListTemporaryCheckpoints lists all checkpoint commits on a shadow branch.
// This returns individual commits (rewind points), not just branch info.
// The sessionID filter, if provided, limits results to commits from that session.
func (s *GitStore) ListTemporaryCheckpoints(ctx context.Context, baseCommit string, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilerr // No shadow branch is expected case
	}

	iter, err := s.repo.Log(&git.LogOptions{From: ref.Hash()})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var results []TemporaryCheckpointInfo
	count := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= limit*5 { // Scan more to allow for session filtering
			return errStop
		}
		count++

		// Verify commit belongs to target session via Entire-Session trailer
		commitSessionID, hasTrailer := paths.ParseSessionTrailer(c.Message)
		if !hasTrailer {
			return nil // Skip commits without session trailer
		}
		if sessionID != "" && commitSessionID != sessionID {
			return nil // Skip commits from other sessions
		}

		// Get first line of message
		message := c.Message
		if idx := strings.Index(message, "\n"); idx > 0 {
			message = message[:idx]
		}

		info := TemporaryCheckpointInfo{
			CommitHash: c.Hash,
			Message:    message,
			SessionID:  commitSessionID,
			Timestamp:  c.Author.When,
		}

		// Check for task checkpoint first
		taskMetadataDir, foundTask := paths.ParseTaskMetadataTrailer(c.Message)
		if foundTask {
			info.IsTaskCheckpoint = true
			info.MetadataDir = taskMetadataDir
			info.ToolUseID = extractToolUseIDFromPath(taskMetadataDir)
		} else {
			metadataDir, found := paths.ParseMetadataTrailer(c.Message)
			if found {
				info.MetadataDir = metadataDir
			}
		}

		results = append(results, info)

		if len(results) >= limit {
			return errStop
		}
		return nil
	})

	if err != nil && !errors.Is(err, errStop) {
		return nil, fmt.Errorf("error iterating commits: %w", err)
	}

	return results, nil
}

// extractToolUseIDFromPath extracts the ToolUseID from a task metadata directory path.
// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
func extractToolUseIDFromPath(metadataDir string) string {
	parts := strings.Split(metadataDir, "/")
	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
		return parts[len(parts)-1]
	}
	return ""
}

// errStop is a sentinel error used to break out of git log iteration.
var errStop = errors.New("stop iteration")

// ShadowBranchExists checks if a shadow branch exists for the given base commit.
func (s *GitStore) ShadowBranchExists(baseCommit string) bool {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	_, err := s.repo.Reference(refName, true)
	return err == nil
}

// DeleteShadowBranch deletes the shadow branch for the given base commit.
func (s *GitStore) DeleteShadowBranch(baseCommit string) error {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	if err := s.repo.Storer.RemoveReference(refName); err != nil {
		return fmt.Errorf("failed to delete shadow branch %s: %w", shadowBranchName, err)
	}
	return nil
}

// ShadowBranchNameForCommit returns the shadow branch name for a base commit hash.
// Uses the first ShadowBranchHashLength characters of the commit hash.
func ShadowBranchNameForCommit(baseCommit string) string {
	if len(baseCommit) >= ShadowBranchHashLength {
		return ShadowBranchPrefix + baseCommit[:ShadowBranchHashLength]
	}
	return ShadowBranchPrefix + baseCommit
}

// getOrCreateShadowBranch gets or creates the shadow branch for checkpoints.
// Returns (parentHash, baseTreeHash, error).
func (s *GitStore) getOrCreateShadowBranch(branchName string) (plumbing.Hash, plumbing.Hash, error) {
	refName := plumbing.NewBranchReferenceName(branchName)
	ref, err := s.repo.Reference(refName, true)

	if err == nil {
		// Branch exists
		commit, err := s.repo.CommitObject(ref.Hash())
		if err != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
		}
		return ref.Hash(), commit.TreeHash, nil
	}

	// Branch doesn't exist, use current HEAD's tree as base
	head, err := s.repo.Head()
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
	}

	headCommit, err := s.repo.CommitObject(head.Hash())
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	return plumbing.ZeroHash, headCommit.TreeHash, nil
}

// buildTreeWithChanges builds a git tree with the given changes.
// metadataDir is the relative path for git tree entries, metadataDirAbs is the absolute path
// for filesystem operations (needed when CLI is run from a subdirectory).
func (s *GitStore) buildTreeWithChanges(
	baseTreeHash plumbing.Hash,
	modifiedFiles, deletedFiles []string,
	metadataDir, metadataDirAbs string,
) (plumbing.Hash, error) {
	// Get repo root for resolving file paths
	// This is critical because fileExists() and createBlobFromFile() use os.Stat()
	// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
	// so we must resolve them against repo root, not CWD.
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get repo root: %w", err)
	}

	// Get the base tree
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	// Flatten existing tree
	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten base tree: %w", err)
	}

	// Remove deleted files
	for _, file := range deletedFiles {
		delete(entries, file)
	}

	// Add/update modified files
	for _, file := range modifiedFiles {
		// Resolve path relative to repo root for filesystem operations
		absPath := filepath.Join(repoRoot, file)
		if !fileExists(absPath) {
			delete(entries, file)
			continue
		}

		blobHash, mode, err := createBlobFromFile(s.repo, absPath)
		if err != nil {
			// Skip files that can't be staged (may have been deleted since detection)
			continue
		}

		entries[file] = object.TreeEntry{
			Name: file,
			Mode: mode,
			Hash: blobHash,
		}
	}

	// Add metadata directory files
	if metadataDir != "" && metadataDirAbs != "" {
		if err := addDirectoryToEntriesWithAbsPath(s.repo, metadataDirAbs, metadataDir, entries); err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", err)
		}
	}

	// Build tree
	return BuildTreeFromEntries(s.repo, entries)
}

// createCommit creates a commit object.
func (s *GitStore) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}

	// Add parent if not a new branch
	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	obj := s.repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := s.repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

// Helper functions extracted from strategy/common.go
// These are exported for use by strategy package (push_common.go, session_test.go)

// FlattenTree recursively flattens a tree into a map of full paths to entries.
func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
	for _, entry := range tree.Entries {
		fullPath := entry.Name
		if prefix != "" {
			fullPath = prefix + "/" + entry.Name
		}

		if entry.Mode == filemode.Dir {
			// Recurse into subtree
			subtree, err := repo.TreeObject(entry.Hash)
			if err != nil {
				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
			}
			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
				return err
			}
		} else {
			entries[fullPath] = object.TreeEntry{
				Name: fullPath,
				Mode: entry.Mode,
				Hash: entry.Hash,
			}
		}
	}
	return nil
}

// fileExists checks if a file exists at the given path.
func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// createBlobFromFile creates a blob object from a file in the working directory.
func createBlobFromFile(repo *git.Repository, filePath string) (plumbing.Hash, filemode.FileMode, error) {
	info, err := os.Stat(filePath)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
	}

	// Determine file mode
	mode := filemode.Regular
	if info.Mode()&0o111 != 0 {
		mode = filemode.Executable
	}
	if info.Mode()&os.ModeSymlink != 0 {
		mode = filemode.Symlink
	}

	// Read file contents
	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
	}

	// Create blob object
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(content)))

	writer, err := obj.Writer()
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
	}

	_, err = writer.Write(content)
	if err != nil {
		_ = writer.Close()
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to write blob content: %w", err)
	}
	if err := writer.Close(); err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to close blob writer: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to store blob object: %w", err)
	}

	return hash, mode, nil
}

// addDirectoryToEntriesWithAbsPath recursively adds all files in a directory to the entries map.
func addDirectoryToEntriesWithAbsPath(repo *git.Repository, dirPathAbs, dirPathRel string, entries map[string]object.TreeEntry) error {
	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		// Calculate relative path within the directory, then join with dirPathRel for tree entry
		relWithinDir, err := filepath.Rel(dirPathAbs, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}

		blobHash, mode, err := createBlobFromFile(repo, path)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}

		treePath := filepath.Join(dirPathRel, relWithinDir)
		entries[treePath] = object.TreeEntry{
			Name: treePath,
			Mode: mode,
			Hash: blobHash,
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
	}
	return nil
}

// treeNode represents a node in our tree structure.
type treeNode struct {
	entries map[string]*treeNode // subdirectories
	files   []object.TreeEntry   // files in this directory
}

// BuildTreeFromEntries builds a proper git tree structure from flattened file entries.
// Exported for use by strategy package (push_common.go, session_test.go)
func BuildTreeFromEntries(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	// Build a tree structure
	root := &treeNode{
		entries: make(map[string]*treeNode),
		files:   []object.TreeEntry{},
	}

	// Insert all entries into the tree structure
	for fullPath, entry := range entries {
		parts := strings.Split(fullPath, "/")
		insertIntoTree(root, parts, entry)
	}

	// Recursively build tree objects from bottom up
	return buildTreeObject(repo, root)
}

// insertIntoTree inserts a file entry into the tree structure.
func insertIntoTree(node *treeNode, pathParts []string, entry object.TreeEntry) {
	if len(pathParts) == 1 {
		// This is a file in the current directory
		node.files = append(node.files, object.TreeEntry{
			Name: pathParts[0],
			Mode: entry.Mode,
			Hash: entry.Hash,
		})
		return
	}

	// This is in a subdirectory
	dirName := pathParts[0]
	if node.entries[dirName] == nil {
		node.entries[dirName] = &treeNode{
			entries: make(map[string]*treeNode),
			files:   []object.TreeEntry{},
		}
	}
	insertIntoTree(node.entries[dirName], pathParts[1:], entry)
}

// buildTreeObject recursively builds tree objects from a treeNode.
func buildTreeObject(repo *git.Repository, node *treeNode) (plumbing.Hash, error) {
	var treeEntries []object.TreeEntry

	// Add files
	treeEntries = append(treeEntries, node.files...)

	// Recursively build subtrees
	for name, subnode := range node.entries {
		subHash, err := buildTreeObject(repo, subnode)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		treeEntries = append(treeEntries, object.TreeEntry{
			Name: name,
			Mode: filemode.Dir,
			Hash: subHash,
		})
	}

	// Sort entries (git requires sorted entries)
	sortTreeEntries(treeEntries)

	// Create tree object
	tree := &object.Tree{Entries: treeEntries}

	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
	}

	return hash, nil
}

// sortTreeEntries sorts tree entries in git's required order.
// Git sorts tree entries by name, with directories having a trailing /
func sortTreeEntries(entries []object.TreeEntry) {
	sort.Slice(entries, func(i, j int) bool {
		nameI := entries[i].Name
		nameJ := entries[j].Name
		if entries[i].Mode == filemode.Dir {
			nameI += "/"
		}
		if entries[j].Mode == filemode.Dir {
			nameJ += "/"
		}
		return nameI < nameJ
	})
}

// collectWorkingDirectoryFiles collects all files in the working directory.
// Excludes .git/ and .entire/ directories.
func collectWorkingDirectoryFiles() ([]string, error) {
	// Get repository root to walk from there
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "." // Fallback to current directory
	}

	var files []string
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		// Get path relative to repo root
		relPath, err := filepath.Rel(repoRoot, path)
		if err != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories
		if info.IsDir() {
			// Skip .git and .entire directories
			if relPath == gitDir || relPath == entireDir ||
				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		files = append(files, relPath)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to walk directory: %w", err)
	}

	return files, nil
}

package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	// ShadowBranchPrefix is the prefix for shadow branches.
	ShadowBranchPrefix = "entire/"

	// ShadowBranchHashLength is the number of hex characters used in shadow branch names.
	// Shadow branches are named "entire/<hash>" using the first 7 characters of the commit hash.
	ShadowBranchHashLength = 7

	// gitDir and entireDir are excluded from tree operations.
	gitDir    = ".git"
	entireDir = ".entire"
)

// WriteTemporary writes a temporary checkpoint to a shadow branch.
// Shadow branches are named entire/<base-commit-short-hash>.
// Returns the result containing commit hash and whether it was skipped.
// If the new tree hash matches the last checkpoint's tree hash, the checkpoint
// is skipped to avoid duplicate commits (deduplication).
func (s *GitStore) WriteTemporary(ctx context.Context, opts WriteTemporaryOptions) (WriteTemporaryResult, error) {
	_ = ctx // Reserved for future use (e.g., cancellation)

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return WriteTemporaryResult{}, errors.New("BaseCommit is required for temporary checkpoint")
	}

	// Validate session ID to prevent path traversal
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("invalid temporary checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Get the last checkpoint's tree hash for deduplication
	var lastTreeHash plumbing.Hash
	if parentHash != plumbing.ZeroHash {
		if lastCommit, err := s.repo.CommitObject(parentHash); err == nil {
			lastTreeHash = lastCommit.TreeHash
		}
	}

	// Collect all files to include
	var allFiles []string
	if opts.IsFirstCheckpoint {
		// For the first checkpoint of this session, capture ALL files in working directory
		// This ensures untracked files present at session start are included
		allFiles, err = collectWorkingDirectoryFiles()
		if err != nil {
			return WriteTemporaryResult{}, fmt.Errorf("failed to collect working directory files: %w", err)
		}
	} else {
		// For subsequent checkpoints, only include modified/new files
		allFiles = make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
		allFiles = append(allFiles, opts.ModifiedFiles...)
		allFiles = append(allFiles, opts.NewFiles...)
	}

	// Build tree with changes
	treeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, opts.MetadataDir, opts.MetadataDirAbs)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to build tree: %w", err)
	}

	// Deduplication: skip if tree hash matches the last checkpoint
	if lastTreeHash != plumbing.ZeroHash && treeHash == lastTreeHash {
		return WriteTemporaryResult{
			CommitHash: parentHash,
			Skipped:    true,
		}, nil
	}

	// Create checkpoint commit with trailers
	commitMsg := trailers.FormatShadowCommit(opts.CommitMessage, opts.MetadataDir, opts.SessionID)

	commitHash, err := s.createCommit(treeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to update branch reference: %w", err)
	}

	return WriteTemporaryResult{
		CommitHash: commitHash,
		Skipped:    false,
	}, nil
}

// ReadTemporary reads the latest checkpoint from a shadow branch.
// Returns nil if the shadow branch doesn't exist.
func (s *GitStore) ReadTemporary(ctx context.Context, baseCommit string) (*ReadTemporaryResult, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Branch not found is an expected case
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	// Extract session ID and metadata dir from commit trailers
	sessionID, _ := paths.ParseSessionTrailer(commit.Message)
	metadataDir, _ := paths.ParseMetadataTrailer(commit.Message)

	return &ReadTemporaryResult{
		CommitHash:  ref.Hash(),
		TreeHash:    commit.TreeHash,
		SessionID:   sessionID,
		MetadataDir: metadataDir,
		Timestamp:   commit.Author.When,
	}, nil
}

// ListTemporary lists all shadow branches with their checkpoint info.
func (s *GitStore) ListTemporary(ctx context.Context) ([]TemporaryInfo, error) {
	_ = ctx // Reserved for future use

	iter, err := s.repo.Branches()
	if err != nil {
		return nil, fmt.Errorf("failed to list branches: %w", err)
	}

	var results []TemporaryInfo
	err = iter.ForEach(func(ref *plumbing.Reference) error {
		branchName := ref.Name().Short()
		if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
			return nil
		}

		// Skip the sessions branch
		if branchName == paths.MetadataBranchName {
			return nil
		}

		commit, commitErr := s.repo.CommitObject(ref.Hash())
		if commitErr != nil {
			//nolint:nilerr // Skip branches we can't read (non-fatal)
			return nil
		}

		sessionID, _ := paths.ParseSessionTrailer(commit.Message)

		// Extract base commit from branch name
		baseCommit := strings.TrimPrefix(branchName, ShadowBranchPrefix)

		results = append(results, TemporaryInfo{
			BranchName:   branchName,
			BaseCommit:   baseCommit,
			LatestCommit: ref.Hash(),
			SessionID:    sessionID,
			Timestamp:    commit.Author.When,
		})

		return nil
	})

	if err != nil {
		return nil, fmt.Errorf("failed to iterate branches: %w", err)
	}

	return results, nil
}

// WriteTemporaryTask writes a task checkpoint to a shadow branch.
// Task checkpoints include both code changes and task-specific metadata.
// Returns the commit hash of the created checkpoint.
func (s *GitStore) WriteTemporaryTask(ctx context.Context, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	_ = ctx // Reserved for future use

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return plumbing.ZeroHash, errors.New("BaseCommit is required for task checkpoint")
	}

	// Validate identifiers to prevent path traversal and malformed data
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Collect all files to include in the commit
	allFiles := make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
	allFiles = append(allFiles, opts.ModifiedFiles...)
	allFiles = append(allFiles, opts.NewFiles...)

	// Build new tree with code changes (no metadata dir yet)
	newTreeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, "", "")
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to build tree: %w", err)
	}

	// Add task metadata to tree
	newTreeHash, err = s.addTaskMetadataToTree(newTreeHash, opts)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to add task metadata: %w", err)
	}

	// Create the commit
	commitHash, err := s.createCommit(newTreeHash, parentHash, opts.CommitMessage, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update shadow branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to update shadow branch reference: %w", err)
	}

	return commitHash, nil
}

// addTaskMetadataToTree adds task checkpoint metadata to a git tree.
// When IsIncremental is true, only adds the incremental checkpoint file.
func (s *GitStore) addTaskMetadataToTree(baseTreeHash plumbing.Hash, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	// Get base tree and flatten it
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten tree: %w", err)
	}

	// Compute metadata paths
	sessionMetadataDir := paths.EntireMetadataDir + "/" + opts.SessionID
	taskMetadataDir := sessionMetadataDir + "/tasks/" + opts.ToolUseID

	if opts.IsIncremental {
		// Incremental checkpoint: only add the checkpoint file
		// Use proper JSON marshaling to handle nil/empty IncrementalData correctly
		incrementalCheckpoint := struct {
			Type      string          `json:"type"`
			ToolUseID string          `json:"tool_use_id"`
			Timestamp time.Time       `json:"timestamp"`
			Data      json.RawMessage `json:"data"`
		}{
			Type:      opts.IncrementalType,
			ToolUseID: opts.ToolUseID,
			Timestamp: time.Now().UTC(),
			Data:      opts.IncrementalData,
		}
		cpData, err := jsonutil.MarshalIndentWithNewline(incrementalCheckpoint, "", "  ")
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
		}

		cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
		}
		cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
		cpPath := taskMetadataDir + "/checkpoints/" + cpFilename
		entries[cpPath] = object.TreeEntry{
			Name: cpPath,
			Mode: filemode.Regular,
			Hash: cpBlobHash,
		}
	} else {
		// Final checkpoint: add transcripts and checkpoint.json

		// Add session transcript
		if opts.TranscriptPath != "" {
			if transcriptContent, readErr := os.ReadFile(opts.TranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, transcriptContent); blobErr == nil {
					transcriptPath := sessionMetadataDir + "/" + paths.TranscriptFileName
					entries[transcriptPath] = object.TreeEntry{
						Name: transcriptPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add subagent transcript if available
		if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
			if agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, agentContent); blobErr == nil {
					agentPath := taskMetadataDir + "/agent-" + opts.AgentID + ".jsonl"
					entries[agentPath] = object.TreeEntry{
						Name: agentPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add checkpoint.json
		checkpointJSON := fmt.Sprintf(`{
  "session_id": %q,
  "tool_use_id": %q,
  "checkpoint_uuid": %q,
  "agent_id": %q
}`, opts.SessionID, opts.ToolUseID, opts.CheckpointUUID, opts.AgentID)

		blobHash, err := CreateBlobFromContent(s.repo, []byte(checkpointJSON))
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint blob: %w", err)
		}
		checkpointPath := taskMetadataDir + "/checkpoint.json"
		entries[checkpointPath] = object.TreeEntry{
			Name: checkpointPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Build new tree from entries
	return BuildTreeFromEntries(s.repo, entries)
}

// ListTemporaryCheckpoints lists all checkpoint commits on a shadow branch.
// This returns individual commits (rewind points), not just branch info.
// The sessionID filter, if provided, limits results to commits from that session.
func (s *GitStore) ListTemporaryCheckpoints(ctx context.Context, baseCommit string, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilerr // No shadow branch is expected case
	}

	iter, err := s.repo.Log(&git.LogOptions{From: ref.Hash()})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var results []TemporaryCheckpointInfo
	count := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= limit*5 { // Scan more to allow for session filtering
			return errStop
		}
		count++

		// Verify commit belongs to target session via Entire-Session trailer
		commitSessionID, hasTrailer := paths.ParseSessionTrailer(c.Message)
		if !hasTrailer {
			return nil // Skip commits without session trailer
		}
		if sessionID != "" && commitSessionID != sessionID {
			return nil // Skip commits from other sessions
		}

		// Get first line of message
		message := c.Message
		if idx := strings.Index(message, "\n"); idx > 0 {
			message = message[:idx]
		}

		info := TemporaryCheckpointInfo{
			CommitHash: c.Hash,
			Message:    message,
			SessionID:  commitSessionID,
			Timestamp:  c.Author.When,
		}

		// Check for task checkpoint first
		taskMetadataDir, foundTask := paths.ParseTaskMetadataTrailer(c.Message)
		if foundTask {
			info.IsTaskCheckpoint = true
			info.MetadataDir = taskMetadataDir
			info.ToolUseID = extractToolUseIDFromPath(taskMetadataDir)
		} else {
			metadataDir, found := paths.ParseMetadataTrailer(c.Message)
			if found {
				info.MetadataDir = metadataDir
			}
		}

		results = append(results, info)

		if len(results) >= limit {
			return errStop
		}
		return nil
	})

	if err != nil && !errors.Is(err, errStop) {
		return nil, fmt.Errorf("error iterating commits: %w", err)
	}

	return results, nil
}

// extractToolUseIDFromPath extracts the ToolUseID from a task metadata directory path.
// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
func extractToolUseIDFromPath(metadataDir string) string {
	parts := strings.Split(metadataDir, "/")
	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
		return parts[len(parts)-1]
	}
	return ""
}

// errStop is a sentinel error used to break out of git log iteration.
var errStop = errors.New("stop iteration")

// ShadowBranchExists checks if a shadow branch exists for the given base commit.
func (s *GitStore) ShadowBranchExists(baseCommit string) bool {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	_, err := s.repo.Reference(refName, true)
	return err == nil
}

// DeleteShadowBranch deletes the shadow branch for the given base commit.
func (s *GitStore) DeleteShadowBranch(baseCommit string) error {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	if err := s.repo.Storer.RemoveReference(refName); err != nil {
		return fmt.Errorf("failed to delete shadow branch %s: %w", shadowBranchName, err)
	}
	return nil
}

// ShadowBranchNameForCommit returns the shadow branch name for a base commit hash.
// Uses the first ShadowBranchHashLength characters of the commit hash.
func ShadowBranchNameForCommit(baseCommit string) string {
	if len(baseCommit) >= ShadowBranchHashLength {
		return ShadowBranchPrefix + baseCommit[:ShadowBranchHashLength]
	}
	return ShadowBranchPrefix + baseCommit
}

// getOrCreateShadowBranch gets or creates the shadow branch for checkpoints.
// Returns (parentHash, baseTreeHash, error).
func (s *GitStore) getOrCreateShadowBranch(branchName string) (plumbing.Hash, plumbing.Hash, error) {
	refName := plumbing.NewBranchReferenceName(branchName)
	ref, err := s.repo.Reference(refName, true)

	if err == nil {
		// Branch exists
		commit, err := s.repo.CommitObject(ref.Hash())
		if err != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
		}
		return ref.Hash(), commit.TreeHash, nil
	}

	// Branch doesn't exist, use current HEAD's tree as base
	head, err := s.repo.Head()
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
	}

	headCommit, err := s.repo.CommitObject(head.Hash())
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	return plumbing.ZeroHash, headCommit.TreeHash, nil
}

// buildTreeWithChanges builds a git tree with the given changes.
// metadataDir is the relative path for git tree entries, metadataDirAbs is the absolute path
// for filesystem operations (needed when CLI is run from a subdirectory).
func (s *GitStore) buildTreeWithChanges(
	baseTreeHash plumbing.Hash,
	modifiedFiles, deletedFiles []string,
	metadataDir, metadataDirAbs string,
) (plumbing.Hash, error) {
	// Get repo root for resolving file paths
	// This is critical because fileExists() and createBlobFromFile() use os.Stat()
	// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
	// so we must resolve them against repo root, not CWD.
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get repo root: %w", err)
	}

	// Get the base tree
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	// Flatten existing tree
	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten base tree: %w", err)
	}

	// Remove deleted files
	for _, file := range deletedFiles {
		delete(entries, file)
	}

	// Add/update modified files
	for _, file := range modifiedFiles {
		// Resolve path relative to repo root for filesystem operations
		absPath := filepath.Join(repoRoot, file)
		if !fileExists(absPath) {
			delete(entries, file)
			continue
		}

		blobHash, mode, err := createBlobFromFile(s.repo, absPath)
		if err != nil {
			// Skip files that can't be staged (may have been deleted since detection)
			continue
		}

		entries[file] = object.TreeEntry{
			Name: file,
			Mode: mode,
			Hash: blobHash,
		}
	}

	// Add metadata directory files
	if metadataDir != "" && metadataDirAbs != "" {
		if err := addDirectoryToEntriesWithAbsPath(s.repo, metadataDirAbs, metadataDir, entries); err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", err)
		}
	}

	// Build tree
	return BuildTreeFromEntries(s.repo, entries)
}

// createCommit creates a commit object.
func (s *GitStore) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}

	// Add parent if not a new branch
	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	obj := s.repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := s.repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

// Helper functions extracted from strategy/common.go
// These are exported for use by strategy package (push_common.go, session_test.go)

// FlattenTree recursively flattens a tree into a map of full paths to entries.
func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
	for _, entry := range tree.Entries {
		fullPath := entry.Name
		if prefix != "" {
			fullPath = prefix + "/" + entry.Name
		}

		if entry.Mode == filemode.Dir {
			// Recurse into subtree
			subtree, err := repo.TreeObject(entry.Hash)
			if err != nil {
				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
			}
			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
				return err
			}
		} else {
			entries[fullPath] = object.TreeEntry{
				Name: fullPath,
				Mode: entry.Mode,
				Hash: entry.Hash,
			}
		}
	}
	return nil
}

// fileExists checks if a file exists at the given path.
func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// createBlobFromFile creates a blob object from a file in the working directory.
func createBlobFromFile(repo *git.Repository, filePath string) (plumbing.Hash, filemode.FileMode, error) {
	info, err := os.Stat(filePath)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
	}

	// Determine file mode
	mode := filemode.Regular
	if info.Mode()&0o111 != 0 {
		mode = filemode.Executable
	}
	if info.Mode()&os.ModeSymlink != 0 {
		mode = filemode.Symlink
	}

	// Read file contents
	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
	}

	// Create blob object
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(content)))

	writer, err := obj.Writer()
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
	}

	_, err = writer.Write(content)
	if err != nil {
		_ = writer.Close()
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to write blob content: %w", err)
	}
	if err := writer.Close(); err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to close blob writer: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to store blob object: %w", err)
	}

	return hash, mode, nil
}

// addDirectoryToEntriesWithAbsPath recursively adds all files in a directory to the entries map.
func addDirectoryToEntriesWithAbsPath(repo *git.Repository, dirPathAbs, dirPathRel string, entries map[string]object.TreeEntry) error {
	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		// Calculate relative path within the directory, then join with dirPathRel for tree entry
		relWithinDir, err := filepath.Rel(dirPathAbs, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}

		blobHash, mode, err := createBlobFromFile(repo, path)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}

		treePath := filepath.Join(dirPathRel, relWithinDir)
		entries[treePath] = object.TreeEntry{
			Name: treePath,
			Mode: mode,
			Hash: blobHash,
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
	}
	return nil
}

// treeNode represents a node in our tree structure.
type treeNode struct {
	entries map[string]*treeNode // subdirectories
	files   []object.TreeEntry   // files in this directory
}

// BuildTreeFromEntries builds a proper git tree structure from flattened file entries.
// Exported for use by strategy package (push_common.go, session_test.go)
func BuildTreeFromEntries(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	// Build a tree structure
	root := &treeNode{
		entries: make(map[string]*treeNode),
		files:   []object.TreeEntry{},
	}

	// Insert all entries into the tree structure
	for fullPath, entry := range entries {
		parts := strings.Split(fullPath, "/")
		insertIntoTree(root, parts, entry)
	}

	// Recursively build tree objects from bottom up
	return buildTreeObject(repo, root)
}

// insertIntoTree inserts a file entry into the tree structure.
func insertIntoTree(node *treeNode, pathParts []string, entry object.TreeEntry) {
	if len(pathParts) == 1 {
		// This is a file in the current directory
		node.files = append(node.files, object.TreeEntry{
			Name: pathParts[0],
			Mode: entry.Mode,
			Hash: entry.Hash,
		})
		return
	}

	// This is in a subdirectory
	dirName := pathParts[0]
	if node.entries[dirName] == nil {
		node.entries[dirName] = &treeNode{
			entries: make(map[string]*treeNode),
			files:   []object.TreeEntry{},
		}
	}
	insertIntoTree(node.entries[dirName], pathParts[1:], entry)
}

// buildTreeObject recursively builds tree objects from a treeNode.
func buildTreeObject(repo *git.Repository, node *treeNode) (plumbing.Hash, error) {
	var treeEntries []object.TreeEntry

	// Add files
	treeEntries = append(treeEntries, node.files...)

	// Recursively build subtrees
	for name, subnode := range node.entries {
		subHash, err := buildTreeObject(repo, subnode)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		treeEntries = append(treeEntries, object.TreeEntry{
			Name: name,
			Mode: filemode.Dir,
			Hash: subHash,
		})
	}

	// Sort entries (git requires sorted entries)
	sortTreeEntries(treeEntries)

	// Create tree object
	tree := &object.Tree{Entries: treeEntries}

	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
	}

	return hash, nil
}

// sortTreeEntries sorts tree entries in git's required order.
// Git sorts tree entries by name, with directories having a trailing /
func sortTreeEntries(entries []object.TreeEntry) {
	sort.Slice(entries, func(i, j int) bool {
		nameI := entries[i].Name
		nameJ := entries[j].Name
		if entries[i].Mode == filemode.Dir {
			nameI += "/"
		}
		if entries[j].Mode == filemode.Dir {
			nameJ += "/"
		}
		return nameI < nameJ
	})
}

// collectWorkingDirectoryFiles collects all files in the working directory.
// Excludes .git/ and .entire/ directories.
func collectWorkingDirectoryFiles() ([]string, error) {
	// Get repository root to walk from there
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "." // Fallback to current directory
	}

	var files []string
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		// Get path relative to repo root
		relPath, err := filepath.Rel(repoRoot, path)
		if err != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories
		if info.IsDir() {
			// Skip .git and .entire directories
			if relPath == gitDir || relPath == entireDir ||
				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		files = append(files, relPath)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to walk directory: %w", err)
	}

	return files, nil
}

package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	// ShadowBranchPrefix is the prefix for shadow branches.
	ShadowBranchPrefix = "entire/"

	// ShadowBranchHashLength is the number of hex characters used in shadow branch names.
	// Shadow branches are named "entire/<hash>" using the first 7 characters of the commit hash.
	ShadowBranchHashLength = 7

	// gitDir and entireDir are excluded from tree operations.
	gitDir    = ".git"
	entireDir = ".entire"
)

// WriteTemporary writes a temporary checkpoint to a shadow branch.
// Shadow branches are named entire/<base-commit-short-hash>.
// Returns the result containing commit hash and whether it was skipped.
// If the new tree hash matches the last checkpoint's tree hash, the checkpoint
// is skipped to avoid duplicate commits (deduplication).
func (s *GitStore) WriteTemporary(ctx context.Context, opts WriteTemporaryOptions) (WriteTemporaryResult, error) {
	_ = ctx // Reserved for future use (e.g., cancellation)

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return WriteTemporaryResult{}, errors.New("BaseCommit is required for temporary checkpoint")
	}

	// Validate session ID to prevent path traversal
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("invalid temporary checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Get the last checkpoint's tree hash for deduplication
	var lastTreeHash plumbing.Hash
	if parentHash != plumbing.ZeroHash {
		if lastCommit, err := s.repo.CommitObject(parentHash); err == nil {
			lastTreeHash = lastCommit.TreeHash
		}
	}

	// Collect all files to include
	var allFiles []string
	if opts.IsFirstCheckpoint {
		// For the first checkpoint of this session, capture ALL files in working directory
		// This ensures untracked files present at session start are included
		allFiles, err = collectWorkingDirectoryFiles()
		if err != nil {
			return WriteTemporaryResult{}, fmt.Errorf("failed to collect working directory files: %w", err)
		}
	} else {
		// For subsequent checkpoints, only include modified/new files
		allFiles = make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
		allFiles = append(allFiles, opts.ModifiedFiles...)
		allFiles = append(allFiles, opts.NewFiles...)
	}

	// Build tree with changes
	treeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, opts.MetadataDir, opts.MetadataDirAbs)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to build tree: %w", err)
	}

	// Deduplication: skip if tree hash matches the last checkpoint
	if lastTreeHash != plumbing.ZeroHash && treeHash == lastTreeHash {
		return WriteTemporaryResult{
			CommitHash: parentHash,
			Skipped:    true,
		}, nil
	}

	// Create checkpoint commit with trailers
	commitMsg := trailers.FormatShadowCommit(opts.CommitMessage, opts.MetadataDir, opts.SessionID)

	commitHash, err := s.createCommit(treeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to update branch reference: %w", err)
	}

	return WriteTemporaryResult{
		CommitHash: commitHash,
		Skipped:    false,
	}, nil
}

// ReadTemporary reads the latest checkpoint from a shadow branch.
// Returns nil if the shadow branch doesn't exist.
func (s *GitStore) ReadTemporary(ctx context.Context, baseCommit string) (*ReadTemporaryResult, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Branch not found is an expected case
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	// Extract session ID and metadata dir from commit trailers
	sessionID, _ := trailers.ParseSession(commit.Message)
	metadataDir, _ := paths.ParseMetadataTrailer(commit.Message)

	return &ReadTemporaryResult{
		CommitHash:  ref.Hash(),
		TreeHash:    commit.TreeHash,
		SessionID:   sessionID,
		MetadataDir: metadataDir,
		Timestamp:   commit.Author.When,
	}, nil
}

// ListTemporary lists all shadow branches with their checkpoint info.
func (s *GitStore) ListTemporary(ctx context.Context) ([]TemporaryInfo, error) {
	_ = ctx // Reserved for future use

	iter, err := s.repo.Branches()
	if err != nil {
		return nil, fmt.Errorf("failed to list branches: %w", err)
	}

	var results []TemporaryInfo
	err = iter.ForEach(func(ref *plumbing.Reference) error {
		branchName := ref.Name().Short()
		if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
			return nil
		}

		// Skip the sessions branch
		if branchName == paths.MetadataBranchName {
			return nil
		}

		commit, commitErr := s.repo.CommitObject(ref.Hash())
		if commitErr != nil {
			//nolint:nilerr // Skip branches we can't read (non-fatal)
			return nil
		}

		sessionID, _ := trailers.ParseSession(commit.Message)

		// Extract base commit from branch name
		baseCommit := strings.TrimPrefix(branchName, ShadowBranchPrefix)

		results = append(results, TemporaryInfo{
			BranchName:   branchName,
			BaseCommit:   baseCommit,
			LatestCommit: ref.Hash(),
			SessionID:    sessionID,
			Timestamp:    commit.Author.When,
		})

		return nil
	})

	if err != nil {
		return nil, fmt.Errorf("failed to iterate branches: %w", err)
	}

	return results, nil
}

// WriteTemporaryTask writes a task checkpoint to a shadow branch.
// Task checkpoints include both code changes and task-specific metadata.
// Returns the commit hash of the created checkpoint.
func (s *GitStore) WriteTemporaryTask(ctx context.Context, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	_ = ctx // Reserved for future use

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return plumbing.ZeroHash, errors.New("BaseCommit is required for task checkpoint")
	}

	// Validate identifiers to prevent path traversal and malformed data
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Collect all files to include in the commit
	allFiles := make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
	allFiles = append(allFiles, opts.ModifiedFiles...)
	allFiles = append(allFiles, opts.NewFiles...)

	// Build new tree with code changes (no metadata dir yet)
	newTreeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, "", "")
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to build tree: %w", err)
	}

	// Add task metadata to tree
	newTreeHash, err = s.addTaskMetadataToTree(newTreeHash, opts)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to add task metadata: %w", err)
	}

	// Create the commit
	commitHash, err := s.createCommit(newTreeHash, parentHash, opts.CommitMessage, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update shadow branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to update shadow branch reference: %w", err)
	}

	return commitHash, nil
}

// addTaskMetadataToTree adds task checkpoint metadata to a git tree.
// When IsIncremental is true, only adds the incremental checkpoint file.
func (s *GitStore) addTaskMetadataToTree(baseTreeHash plumbing.Hash, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	// Get base tree and flatten it
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten tree: %w", err)
	}

	// Compute metadata paths
	sessionMetadataDir := paths.EntireMetadataDir + "/" + opts.SessionID
	taskMetadataDir := sessionMetadataDir + "/tasks/" + opts.ToolUseID

	if opts.IsIncremental {
		// Incremental checkpoint: only add the checkpoint file
		// Use proper JSON marshaling to handle nil/empty IncrementalData correctly
		incrementalCheckpoint := struct {
			Type      string          `json:"type"`
			ToolUseID string          `json:"tool_use_id"`
			Timestamp time.Time       `json:"timestamp"`
			Data      json.RawMessage `json:"data"`
		}{
			Type:      opts.IncrementalType,
			ToolUseID: opts.ToolUseID,
			Timestamp: time.Now().UTC(),
			Data:      opts.IncrementalData,
		}
		cpData, err := jsonutil.MarshalIndentWithNewline(incrementalCheckpoint, "", "  ")
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
		}

		cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
		}
		cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
		cpPath := taskMetadataDir + "/checkpoints/" + cpFilename
		entries[cpPath] = object.TreeEntry{
			Name: cpPath,
			Mode: filemode.Regular,
			Hash: cpBlobHash,
		}
	} else {
		// Final checkpoint: add transcripts and checkpoint.json

		// Add session transcript
		if opts.TranscriptPath != "" {
			if transcriptContent, readErr := os.ReadFile(opts.TranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, transcriptContent); blobErr == nil {
					transcriptPath := sessionMetadataDir + "/" + paths.TranscriptFileName
					entries[transcriptPath] = object.TreeEntry{
						Name: transcriptPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add subagent transcript if available
		if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
			if agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, agentContent); blobErr == nil {
					agentPath := taskMetadataDir + "/agent-" + opts.AgentID + ".jsonl"
					entries[agentPath] = object.TreeEntry{
						Name: agentPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add checkpoint.json
		checkpointJSON := fmt.Sprintf(`{
  "session_id": %q,
  "tool_use_id": %q,
  "checkpoint_uuid": %q,
  "agent_id": %q
}`, opts.SessionID, opts.ToolUseID, opts.CheckpointUUID, opts.AgentID)

		blobHash, err := CreateBlobFromContent(s.repo, []byte(checkpointJSON))
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint blob: %w", err)
		}
		checkpointPath := taskMetadataDir + "/checkpoint.json"
		entries[checkpointPath] = object.TreeEntry{
			Name: checkpointPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Build new tree from entries
	return BuildTreeFromEntries(s.repo, entries)
}

// ListTemporaryCheckpoints lists all checkpoint commits on a shadow branch.
// This returns individual commits (rewind points), not just branch info.
// The sessionID filter, if provided, limits results to commits from that session.
func (s *GitStore) ListTemporaryCheckpoints(ctx context.Context, baseCommit string, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilerr // No shadow branch is expected case
	}

	iter, err := s.repo.Log(&git.LogOptions{From: ref.Hash()})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var results []TemporaryCheckpointInfo
	count := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= limit*5 { // Scan more to allow for session filtering
			return errStop
		}
		count++

		// Verify commit belongs to target session via Entire-Session trailer
		commitSessionID, hasTrailer := trailers.ParseSession(c.Message)
		if !hasTrailer {
			return nil // Skip commits without session trailer
		}
		if sessionID != "" && commitSessionID != sessionID {
			return nil // Skip commits from other sessions
		}

		// Get first line of message
		message := c.Message
		if idx := strings.Index(message, "\n"); idx > 0 {
			message = message[:idx]
		}

		info := TemporaryCheckpointInfo{
			CommitHash: c.Hash,
			Message:    message,
			SessionID:  commitSessionID,
			Timestamp:  c.Author.When,
		}

		// Check for task checkpoint first
		taskMetadataDir, foundTask := paths.ParseTaskMetadataTrailer(c.Message)
		if foundTask {
			info.IsTaskCheckpoint = true
			info.MetadataDir = taskMetadataDir
			info.ToolUseID = extractToolUseIDFromPath(taskMetadataDir)
		} else {
			metadataDir, found := paths.ParseMetadataTrailer(c.Message)
			if found {
				info.MetadataDir = metadataDir
			}
		}

		results = append(results, info)

		if len(results) >= limit {
			return errStop
		}
		return nil
	})

	if err != nil && !errors.Is(err, errStop) {
		return nil, fmt.Errorf("error iterating commits: %w", err)
	}

	return results, nil
}

// extractToolUseIDFromPath extracts the ToolUseID from a task metadata directory path.
// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
func extractToolUseIDFromPath(metadataDir string) string {
	parts := strings.Split(metadataDir, "/")
	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
		return parts[len(parts)-1]
	}
	return ""
}

// errStop is a sentinel error used to break out of git log iteration.
var errStop = errors.New("stop iteration")

// ShadowBranchExists checks if a shadow branch exists for the given base commit.
func (s *GitStore) ShadowBranchExists(baseCommit string) bool {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	_, err := s.repo.Reference(refName, true)
	return err == nil
}

// DeleteShadowBranch deletes the shadow branch for the given base commit.
func (s *GitStore) DeleteShadowBranch(baseCommit string) error {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	if err := s.repo.Storer.RemoveReference(refName); err != nil {
		return fmt.Errorf("failed to delete shadow branch %s: %w", shadowBranchName, err)
	}
	return nil
}

// ShadowBranchNameForCommit returns the shadow branch name for a base commit hash.
// Uses the first ShadowBranchHashLength characters of the commit hash.
func ShadowBranchNameForCommit(baseCommit string) string {
	if len(baseCommit) >= ShadowBranchHashLength {
		return ShadowBranchPrefix + baseCommit[:ShadowBranchHashLength]
	}
	return ShadowBranchPrefix + baseCommit
}

// getOrCreateShadowBranch gets or creates the shadow branch for checkpoints.
// Returns (parentHash, baseTreeHash, error).
func (s *GitStore) getOrCreateShadowBranch(branchName string) (plumbing.Hash, plumbing.Hash, error) {
	refName := plumbing.NewBranchReferenceName(branchName)
	ref, err := s.repo.Reference(refName, true)

	if err == nil {
		// Branch exists
		commit, err := s.repo.CommitObject(ref.Hash())
		if err != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
		}
		return ref.Hash(), commit.TreeHash, nil
	}

	// Branch doesn't exist, use current HEAD's tree as base
	head, err := s.repo.Head()
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
	}

	headCommit, err := s.repo.CommitObject(head.Hash())
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	return plumbing.ZeroHash, headCommit.TreeHash, nil
}

// buildTreeWithChanges builds a git tree with the given changes.
// metadataDir is the relative path for git tree entries, metadataDirAbs is the absolute path
// for filesystem operations (needed when CLI is run from a subdirectory).
func (s *GitStore) buildTreeWithChanges(
	baseTreeHash plumbing.Hash,
	modifiedFiles, deletedFiles []string,
	metadataDir, metadataDirAbs string,
) (plumbing.Hash, error) {
	// Get repo root for resolving file paths
	// This is critical because fileExists() and createBlobFromFile() use os.Stat()
	// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
	// so we must resolve them against repo root, not CWD.
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get repo root: %w", err)
	}

	// Get the base tree
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	// Flatten existing tree
	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten base tree: %w", err)
	}

	// Remove deleted files
	for _, file := range deletedFiles {
		delete(entries, file)
	}

	// Add/update modified files
	for _, file := range modifiedFiles {
		// Resolve path relative to repo root for filesystem operations
		absPath := filepath.Join(repoRoot, file)
		if !fileExists(absPath) {
			delete(entries, file)
			continue
		}

		blobHash, mode, err := createBlobFromFile(s.repo, absPath)
		if err != nil {
			// Skip files that can't be staged (may have been deleted since detection)
			continue
		}

		entries[file] = object.TreeEntry{
			Name: file,
			Mode: mode,
			Hash: blobHash,
		}
	}

	// Add metadata directory files
	if metadataDir != "" && metadataDirAbs != "" {
		if err := addDirectoryToEntriesWithAbsPath(s.repo, metadataDirAbs, metadataDir, entries); err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", err)
		}
	}

	// Build tree
	return BuildTreeFromEntries(s.repo, entries)
}

// createCommit creates a commit object.
func (s *GitStore) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}

	// Add parent if not a new branch
	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	obj := s.repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := s.repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

// Helper functions extracted from strategy/common.go
// These are exported for use by strategy package (push_common.go, session_test.go)

// FlattenTree recursively flattens a tree into a map of full paths to entries.
func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
	for _, entry := range tree.Entries {
		fullPath := entry.Name
		if prefix != "" {
			fullPath = prefix + "/" + entry.Name
		}

		if entry.Mode == filemode.Dir {
			// Recurse into subtree
			subtree, err := repo.TreeObject(entry.Hash)
			if err != nil {
				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
			}
			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
				return err
			}
		} else {
			entries[fullPath] = object.TreeEntry{
				Name: fullPath,
				Mode: entry.Mode,
				Hash: entry.Hash,
			}
		}
	}
	return nil
}

// fileExists checks if a file exists at the given path.
func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// createBlobFromFile creates a blob object from a file in the working directory.
func createBlobFromFile(repo *git.Repository, filePath string) (plumbing.Hash, filemode.FileMode, error) {
	info, err := os.Stat(filePath)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
	}

	// Determine file mode
	mode := filemode.Regular
	if info.Mode()&0o111 != 0 {
		mode = filemode.Executable
	}
	if info.Mode()&os.ModeSymlink != 0 {
		mode = filemode.Symlink
	}

	// Read file contents
	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
	}

	// Create blob object
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(content)))

	writer, err := obj.Writer()
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
	}

	_, err = writer.Write(content)
	if err != nil {
		_ = writer.Close()
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to write blob content: %w", err)
	}
	if err := writer.Close(); err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to close blob writer: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to store blob object: %w", err)
	}

	return hash, mode, nil
}

// addDirectoryToEntriesWithAbsPath recursively adds all files in a directory to the entries map.
func addDirectoryToEntriesWithAbsPath(repo *git.Repository, dirPathAbs, dirPathRel string, entries map[string]object.TreeEntry) error {
	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		// Calculate relative path within the directory, then join with dirPathRel for tree entry
		relWithinDir, err := filepath.Rel(dirPathAbs, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}

		blobHash, mode, err := createBlobFromFile(repo, path)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}

		treePath := filepath.Join(dirPathRel, relWithinDir)
		entries[treePath] = object.TreeEntry{
			Name: treePath,
			Mode: mode,
			Hash: blobHash,
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
	}
	return nil
}

// treeNode represents a node in our tree structure.
type treeNode struct {
	entries map[string]*treeNode // subdirectories
	files   []object.TreeEntry   // files in this directory
}

// BuildTreeFromEntries builds a proper git tree structure from flattened file entries.
// Exported for use by strategy package (push_common.go, session_test.go)
func BuildTreeFromEntries(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	// Build a tree structure
	root := &treeNode{
		entries: make(map[string]*treeNode),
		files:   []object.TreeEntry{},
	}

	// Insert all entries into the tree structure
	for fullPath, entry := range entries {
		parts := strings.Split(fullPath, "/")
		insertIntoTree(root, parts, entry)
	}

	// Recursively build tree objects from bottom up
	return buildTreeObject(repo, root)
}

// insertIntoTree inserts a file entry into the tree structure.
func insertIntoTree(node *treeNode, pathParts []string, entry object.TreeEntry) {
	if len(pathParts) == 1 {
		// This is a file in the current directory
		node.files = append(node.files, object.TreeEntry{
			Name: pathParts[0],
			Mode: entry.Mode,
			Hash: entry.Hash,
		})
		return
	}

	// This is in a subdirectory
	dirName := pathParts[0]
	if node.entries[dirName] == nil {
		node.entries[dirName] = &treeNode{
			entries: make(map[string]*treeNode),
			files:   []object.TreeEntry{},
		}
	}
	insertIntoTree(node.entries[dirName], pathParts[1:], entry)
}

// buildTreeObject recursively builds tree objects from a treeNode.
func buildTreeObject(repo *git.Repository, node *treeNode) (plumbing.Hash, error) {
	var treeEntries []object.TreeEntry

	// Add files
	treeEntries = append(treeEntries, node.files...)

	// Recursively build subtrees
	for name, subnode := range node.entries {
		subHash, err := buildTreeObject(repo, subnode)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		treeEntries = append(treeEntries, object.TreeEntry{
			Name: name,
			Mode: filemode.Dir,
			Hash: subHash,
		})
	}

	// Sort entries (git requires sorted entries)
	sortTreeEntries(treeEntries)

	// Create tree object
	tree := &object.Tree{Entries: treeEntries}

	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
	}

	return hash, nil
}

// sortTreeEntries sorts tree entries in git's required order.
// Git sorts tree entries by name, with directories having a trailing /
func sortTreeEntries(entries []object.TreeEntry) {
	sort.Slice(entries, func(i, j int) bool {
		nameI := entries[i].Name
		nameJ := entries[j].Name
		if entries[i].Mode == filemode.Dir {
			nameI += "/"
		}
		if entries[j].Mode == filemode.Dir {
			nameJ += "/"
		}
		return nameI < nameJ
	})
}

// collectWorkingDirectoryFiles collects all files in the working directory.
// Excludes .git/ and .entire/ directories.
func collectWorkingDirectoryFiles() ([]string, error) {
	// Get repository root to walk from there
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "." // Fallback to current directory
	}

	var files []string
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		// Get path relative to repo root
		relPath, err := filepath.Rel(repoRoot, path)
		if err != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories
		if info.IsDir() {
			// Skip .git and .entire directories
			if relPath == gitDir || relPath == entireDir ||
				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		files = append(files, relPath)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to walk directory: %w", err)
	}

	return files, nil
}

package checkpoint

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/jsonutil"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	// ShadowBranchPrefix is the prefix for shadow branches.
	ShadowBranchPrefix = "entire/"

	// ShadowBranchHashLength is the number of hex characters used in shadow branch names.
	// Shadow branches are named "entire/<hash>" using the first 7 characters of the commit hash.
	ShadowBranchHashLength = 7

	// gitDir and entireDir are excluded from tree operations.
	gitDir    = ".git"
	entireDir = ".entire"
)

// WriteTemporary writes a temporary checkpoint to a shadow branch.
// Shadow branches are named entire/<base-commit-short-hash>.
// Returns the result containing commit hash and whether it was skipped.
// If the new tree hash matches the last checkpoint's tree hash, the checkpoint
// is skipped to avoid duplicate commits (deduplication).
func (s *GitStore) WriteTemporary(ctx context.Context, opts WriteTemporaryOptions) (WriteTemporaryResult, error) {
	_ = ctx // Reserved for future use (e.g., cancellation)

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return WriteTemporaryResult{}, errors.New("BaseCommit is required for temporary checkpoint")
	}

	// Validate session ID to prevent path traversal
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("invalid temporary checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Get the last checkpoint's tree hash for deduplication
	var lastTreeHash plumbing.Hash
	if parentHash != plumbing.ZeroHash {
		if lastCommit, err := s.repo.CommitObject(parentHash); err == nil {
			lastTreeHash = lastCommit.TreeHash
		}
	}

	// Collect all files to include
	var allFiles []string
	if opts.IsFirstCheckpoint {
		// For the first checkpoint of this session, capture ALL files in working directory
		// This ensures untracked files present at session start are included
		allFiles, err = collectWorkingDirectoryFiles()
		if err != nil {
			return WriteTemporaryResult{}, fmt.Errorf("failed to collect working directory files: %w", err)
		}
	} else {
		// For subsequent checkpoints, only include modified/new files
		allFiles = make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
		allFiles = append(allFiles, opts.ModifiedFiles...)
		allFiles = append(allFiles, opts.NewFiles...)
	}

	// Build tree with changes
	treeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, opts.MetadataDir, opts.MetadataDirAbs)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to build tree: %w", err)
	}

	// Deduplication: skip if tree hash matches the last checkpoint
	if lastTreeHash != plumbing.ZeroHash && treeHash == lastTreeHash {
		return WriteTemporaryResult{
			CommitHash: parentHash,
			Skipped:    true,
		}, nil
	}

	// Create checkpoint commit with trailers
	commitMsg := trailers.FormatShadowCommit(opts.CommitMessage, opts.MetadataDir, opts.SessionID)

	commitHash, err := s.createCommit(treeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(newRef); err != nil {
		return WriteTemporaryResult{}, fmt.Errorf("failed to update branch reference: %w", err)
	}

	return WriteTemporaryResult{
		CommitHash: commitHash,
		Skipped:    false,
	}, nil
}

// ReadTemporary reads the latest checkpoint from a shadow branch.
// Returns nil if the shadow branch doesn't exist.
func (s *GitStore) ReadTemporary(ctx context.Context, baseCommit string) (*ReadTemporaryResult, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilnil,nilerr // Branch not found is an expected case
	}

	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	// Extract session ID and metadata dir from commit trailers
	sessionID, _ := trailers.ParseSession(commit.Message)
	metadataDir, _ := trailers.ParseMetadata(commit.Message)

	return &ReadTemporaryResult{
		CommitHash:  ref.Hash(),
		TreeHash:    commit.TreeHash,
		SessionID:   sessionID,
		MetadataDir: metadataDir,
		Timestamp:   commit.Author.When,
	}, nil
}

// ListTemporary lists all shadow branches with their checkpoint info.
func (s *GitStore) ListTemporary(ctx context.Context) ([]TemporaryInfo, error) {
	_ = ctx // Reserved for future use

	iter, err := s.repo.Branches()
	if err != nil {
		return nil, fmt.Errorf("failed to list branches: %w", err)
	}

	var results []TemporaryInfo
	err = iter.ForEach(func(ref *plumbing.Reference) error {
		branchName := ref.Name().Short()
		if !strings.HasPrefix(branchName, ShadowBranchPrefix) {
			return nil
		}

		// Skip the sessions branch
		if branchName == paths.MetadataBranchName {
			return nil
		}

		commit, commitErr := s.repo.CommitObject(ref.Hash())
		if commitErr != nil {
			//nolint:nilerr // Skip branches we can't read (non-fatal)
			return nil
		}

		sessionID, _ := trailers.ParseSession(commit.Message)

		// Extract base commit from branch name
		baseCommit := strings.TrimPrefix(branchName, ShadowBranchPrefix)

		results = append(results, TemporaryInfo{
			BranchName:   branchName,
			BaseCommit:   baseCommit,
			LatestCommit: ref.Hash(),
			SessionID:    sessionID,
			Timestamp:    commit.Author.When,
		})

		return nil
	})

	if err != nil {
		return nil, fmt.Errorf("failed to iterate branches: %w", err)
	}

	return results, nil
}

// WriteTemporaryTask writes a task checkpoint to a shadow branch.
// Task checkpoints include both code changes and task-specific metadata.
// Returns the commit hash of the created checkpoint.
func (s *GitStore) WriteTemporaryTask(ctx context.Context, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	_ = ctx // Reserved for future use

	// Validate base commit - required for shadow branch naming
	if opts.BaseCommit == "" {
		return plumbing.ZeroHash, errors.New("BaseCommit is required for task checkpoint")
	}

	// Validate identifiers to prevent path traversal and malformed data
	if err := paths.ValidateSessionID(opts.SessionID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateToolUseID(opts.ToolUseID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}
	if err := paths.ValidateAgentID(opts.AgentID); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("invalid task checkpoint options: %w", err)
	}

	// Get shadow branch name
	shadowBranchName := ShadowBranchNameForCommit(opts.BaseCommit)

	// Get or create shadow branch
	parentHash, baseTreeHash, err := s.getOrCreateShadowBranch(shadowBranchName)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get shadow branch: %w", err)
	}

	// Collect all files to include in the commit
	allFiles := make([]string, 0, len(opts.ModifiedFiles)+len(opts.NewFiles))
	allFiles = append(allFiles, opts.ModifiedFiles...)
	allFiles = append(allFiles, opts.NewFiles...)

	// Build new tree with code changes (no metadata dir yet)
	newTreeHash, err := s.buildTreeWithChanges(baseTreeHash, allFiles, opts.DeletedFiles, "", "")
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to build tree: %w", err)
	}

	// Add task metadata to tree
	newTreeHash, err = s.addTaskMetadataToTree(newTreeHash, opts)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to add task metadata: %w", err)
	}

	// Create the commit
	commitHash, err := s.createCommit(newTreeHash, parentHash, opts.CommitMessage, opts.AuthorName, opts.AuthorEmail)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to create commit: %w", err)
	}

	// Update shadow branch reference
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref := plumbing.NewHashReference(refName, commitHash)
	if err := s.repo.Storer.SetReference(ref); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to update shadow branch reference: %w", err)
	}

	return commitHash, nil
}

// addTaskMetadataToTree adds task checkpoint metadata to a git tree.
// When IsIncremental is true, only adds the incremental checkpoint file.
func (s *GitStore) addTaskMetadataToTree(baseTreeHash plumbing.Hash, opts WriteTemporaryTaskOptions) (plumbing.Hash, error) {
	// Get base tree and flatten it
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten tree: %w", err)
	}

	// Compute metadata paths
	sessionMetadataDir := paths.EntireMetadataDir + "/" + opts.SessionID
	taskMetadataDir := sessionMetadataDir + "/tasks/" + opts.ToolUseID

	if opts.IsIncremental {
		// Incremental checkpoint: only add the checkpoint file
		// Use proper JSON marshaling to handle nil/empty IncrementalData correctly
		incrementalCheckpoint := struct {
			Type      string          `json:"type"`
			ToolUseID string          `json:"tool_use_id"`
			Timestamp time.Time       `json:"timestamp"`
			Data      json.RawMessage `json:"data"`
		}{
			Type:      opts.IncrementalType,
			ToolUseID: opts.ToolUseID,
			Timestamp: time.Now().UTC(),
			Data:      opts.IncrementalData,
		}
		cpData, err := jsonutil.MarshalIndentWithNewline(incrementalCheckpoint, "", "  ")
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
		}

		cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
		}
		cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
		cpPath := taskMetadataDir + "/checkpoints/" + cpFilename
		entries[cpPath] = object.TreeEntry{
			Name: cpPath,
			Mode: filemode.Regular,
			Hash: cpBlobHash,
		}
	} else {
		// Final checkpoint: add transcripts and checkpoint.json

		// Add session transcript
		if opts.TranscriptPath != "" {
			if transcriptContent, readErr := os.ReadFile(opts.TranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, transcriptContent); blobErr == nil {
					transcriptPath := sessionMetadataDir + "/" + paths.TranscriptFileName
					entries[transcriptPath] = object.TreeEntry{
						Name: transcriptPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add subagent transcript if available
		if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
			if agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath); readErr == nil {
				if blobHash, blobErr := CreateBlobFromContent(s.repo, agentContent); blobErr == nil {
					agentPath := taskMetadataDir + "/agent-" + opts.AgentID + ".jsonl"
					entries[agentPath] = object.TreeEntry{
						Name: agentPath,
						Mode: filemode.Regular,
						Hash: blobHash,
					}
				}
			}
		}

		// Add checkpoint.json
		checkpointJSON := fmt.Sprintf(`{
  "session_id": %q,
  "tool_use_id": %q,
  "checkpoint_uuid": %q,
  "agent_id": %q
}`, opts.SessionID, opts.ToolUseID, opts.CheckpointUUID, opts.AgentID)

		blobHash, err := CreateBlobFromContent(s.repo, []byte(checkpointJSON))
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to create checkpoint blob: %w", err)
		}
		checkpointPath := taskMetadataDir + "/checkpoint.json"
		entries[checkpointPath] = object.TreeEntry{
			Name: checkpointPath,
			Mode: filemode.Regular,
			Hash: blobHash,
		}
	}

	// Build new tree from entries
	return BuildTreeFromEntries(s.repo, entries)
}

// ListTemporaryCheckpoints lists all checkpoint commits on a shadow branch.
// This returns individual commits (rewind points), not just branch info.
// The sessionID filter, if provided, limits results to commits from that session.
func (s *GitStore) ListTemporaryCheckpoints(ctx context.Context, baseCommit string, sessionID string, limit int) ([]TemporaryCheckpointInfo, error) {
	_ = ctx // Reserved for future use

	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	ref, err := s.repo.Reference(refName, true)
	if err != nil {
		return nil, nil //nolint:nilerr // No shadow branch is expected case
	}

	iter, err := s.repo.Log(&git.LogOptions{From: ref.Hash()})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var results []TemporaryCheckpointInfo
	count := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= limit*5 { // Scan more to allow for session filtering
			return errStop
		}
		count++

		// Verify commit belongs to target session via Entire-Session trailer
		commitSessionID, hasTrailer := trailers.ParseSession(c.Message)
		if !hasTrailer {
			return nil // Skip commits without session trailer
		}
		if sessionID != "" && commitSessionID != sessionID {
			return nil // Skip commits from other sessions
		}

		// Get first line of message
		message := c.Message
		if idx := strings.Index(message, "\n"); idx > 0 {
			message = message[:idx]
		}

		info := TemporaryCheckpointInfo{
			CommitHash: c.Hash,
			Message:    message,
			SessionID:  commitSessionID,
			Timestamp:  c.Author.When,
		}

		// Check for task checkpoint first
		taskMetadataDir, foundTask := paths.ParseTaskMetadataTrailer(c.Message)
		if foundTask {
			info.IsTaskCheckpoint = true
			info.MetadataDir = taskMetadataDir
			info.ToolUseID = extractToolUseIDFromPath(taskMetadataDir)
		} else {
			metadataDir, found := trailers.ParseMetadata(c.Message)
			if found {
				info.MetadataDir = metadataDir
			}
		}

		results = append(results, info)

		if len(results) >= limit {
			return errStop
		}
		return nil
	})

	if err != nil && !errors.Is(err, errStop) {
		return nil, fmt.Errorf("error iterating commits: %w", err)
	}

	return results, nil
}

// extractToolUseIDFromPath extracts the ToolUseID from a task metadata directory path.
// Task metadata dirs have format: .entire/metadata/<session>/tasks/<toolUseID>
func extractToolUseIDFromPath(metadataDir string) string {
	parts := strings.Split(metadataDir, "/")
	if len(parts) >= 2 && parts[len(parts)-2] == "tasks" {
		return parts[len(parts)-1]
	}
	return ""
}

// errStop is a sentinel error used to break out of git log iteration.
var errStop = errors.New("stop iteration")

// ShadowBranchExists checks if a shadow branch exists for the given base commit.
func (s *GitStore) ShadowBranchExists(baseCommit string) bool {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	_, err := s.repo.Reference(refName, true)
	return err == nil
}

// DeleteShadowBranch deletes the shadow branch for the given base commit.
func (s *GitStore) DeleteShadowBranch(baseCommit string) error {
	shadowBranchName := ShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	if err := s.repo.Storer.RemoveReference(refName); err != nil {
		return fmt.Errorf("failed to delete shadow branch %s: %w", shadowBranchName, err)
	}
	return nil
}

// ShadowBranchNameForCommit returns the shadow branch name for a base commit hash.
// Uses the first ShadowBranchHashLength characters of the commit hash.
func ShadowBranchNameForCommit(baseCommit string) string {
	if len(baseCommit) >= ShadowBranchHashLength {
		return ShadowBranchPrefix + baseCommit[:ShadowBranchHashLength]
	}
	return ShadowBranchPrefix + baseCommit
}

// getOrCreateShadowBranch gets or creates the shadow branch for checkpoints.
// Returns (parentHash, baseTreeHash, error).
func (s *GitStore) getOrCreateShadowBranch(branchName string) (plumbing.Hash, plumbing.Hash, error) {
	refName := plumbing.NewBranchReferenceName(branchName)
	ref, err := s.repo.Reference(refName, true)

	if err == nil {
		// Branch exists
		commit, err := s.repo.CommitObject(ref.Hash())
		if err != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
		}
		return ref.Hash(), commit.TreeHash, nil
	}

	// Branch doesn't exist, use current HEAD's tree as base
	head, err := s.repo.Head()
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
	}

	headCommit, err := s.repo.CommitObject(head.Hash())
	if err != nil {
		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get HEAD commit: %w", err)
	}

	return plumbing.ZeroHash, headCommit.TreeHash, nil
}

// buildTreeWithChanges builds a git tree with the given changes.
// metadataDir is the relative path for git tree entries, metadataDirAbs is the absolute path
// for filesystem operations (needed when CLI is run from a subdirectory).
func (s *GitStore) buildTreeWithChanges(
	baseTreeHash plumbing.Hash,
	modifiedFiles, deletedFiles []string,
	metadataDir, metadataDirAbs string,
) (plumbing.Hash, error) {
	// Get repo root for resolving file paths
	// This is critical because fileExists() and createBlobFromFile() use os.Stat()
	// which resolves relative to CWD. The modifiedFiles are repo-relative paths,
	// so we must resolve them against repo root, not CWD.
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get repo root: %w", err)
	}

	// Get the base tree
	baseTree, err := s.repo.TreeObject(baseTreeHash)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get base tree: %w", err)
	}

	// Flatten existing tree
	entries := make(map[string]object.TreeEntry)
	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to flatten base tree: %w", err)
	}

	// Remove deleted files
	for _, file := range deletedFiles {
		delete(entries, file)
	}

	// Add/update modified files
	for _, file := range modifiedFiles {
		// Resolve path relative to repo root for filesystem operations
		absPath := filepath.Join(repoRoot, file)
		if !fileExists(absPath) {
			delete(entries, file)
			continue
		}

		blobHash, mode, err := createBlobFromFile(s.repo, absPath)
		if err != nil {
			// Skip files that can't be staged (may have been deleted since detection)
			continue
		}

		entries[file] = object.TreeEntry{
			Name: file,
			Mode: mode,
			Hash: blobHash,
		}
	}

	// Add metadata directory files
	if metadataDir != "" && metadataDirAbs != "" {
		if err := addDirectoryToEntriesWithAbsPath(s.repo, metadataDirAbs, metadataDir, entries); err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to add metadata directory: %w", err)
		}
	}

	// Build tree
	return BuildTreeFromEntries(s.repo, entries)
}

// createCommit creates a commit object.
func (s *GitStore) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:  treeHash,
		Author:    sig,
		Committer: sig,
		Message:   message,
	}

	// Add parent if not a new branch
	if parentHash != plumbing.ZeroHash {
		commit.ParentHashes = []plumbing.Hash{parentHash}
	}

	obj := s.repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := s.repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

// Helper functions extracted from strategy/common.go
// These are exported for use by strategy package (push_common.go, session_test.go)

// FlattenTree recursively flattens a tree into a map of full paths to entries.
func FlattenTree(repo *git.Repository, tree *object.Tree, prefix string, entries map[string]object.TreeEntry) error {
	for _, entry := range tree.Entries {
		fullPath := entry.Name
		if prefix != "" {
			fullPath = prefix + "/" + entry.Name
		}

		if entry.Mode == filemode.Dir {
			// Recurse into subtree
			subtree, err := repo.TreeObject(entry.Hash)
			if err != nil {
				return fmt.Errorf("failed to get subtree %s: %w", fullPath, err)
			}
			if err := FlattenTree(repo, subtree, fullPath, entries); err != nil {
				return err
			}
		} else {
			entries[fullPath] = object.TreeEntry{
				Name: fullPath,
				Mode: entry.Mode,
				Hash: entry.Hash,
			}
		}
	}
	return nil
}

// fileExists checks if a file exists at the given path.
func fileExists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

// createBlobFromFile creates a blob object from a file in the working directory.
func createBlobFromFile(repo *git.Repository, filePath string) (plumbing.Hash, filemode.FileMode, error) {
	info, err := os.Stat(filePath)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
	}

	// Determine file mode
	mode := filemode.Regular
	if info.Mode()&0o111 != 0 {
		mode = filemode.Executable
	}
	if info.Mode()&os.ModeSymlink != 0 {
		mode = filemode.Symlink
	}

	// Read file contents
	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the repository
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
	}

	// Create blob object
	obj := repo.Storer.NewEncodedObject()
	obj.SetType(plumbing.BlobObject)
	obj.SetSize(int64(len(content)))

	writer, err := obj.Writer()
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to get object writer: %w", err)
	}

	_, err = writer.Write(content)
	if err != nil {
		_ = writer.Close()
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to write blob content: %w", err)
	}
	if err := writer.Close(); err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to close blob writer: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, 0, fmt.Errorf("failed to store blob object: %w", err)
	}

	return hash, mode, nil
}

// addDirectoryToEntriesWithAbsPath recursively adds all files in a directory to the entries map.
func addDirectoryToEntriesWithAbsPath(repo *git.Repository, dirPathAbs, dirPathRel string, entries map[string]object.TreeEntry) error {
	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		// Calculate relative path within the directory, then join with dirPathRel for tree entry
		relWithinDir, err := filepath.Rel(dirPathAbs, path)
		if err != nil {
			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
		}

		blobHash, mode, err := createBlobFromFile(repo, path)
		if err != nil {
			return fmt.Errorf("failed to create blob for %s: %w", path, err)
		}

		treePath := filepath.Join(dirPathRel, relWithinDir)
		entries[treePath] = object.TreeEntry{
			Name: treePath,
			Mode: mode,
			Hash: blobHash,
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
	}
	return nil
}

// treeNode represents a node in our tree structure.
type treeNode struct {
	entries map[string]*treeNode // subdirectories
	files   []object.TreeEntry   // files in this directory
}

// BuildTreeFromEntries builds a proper git tree structure from flattened file entries.
// Exported for use by strategy package (push_common.go, session_test.go)
func BuildTreeFromEntries(repo *git.Repository, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
	// Build a tree structure
	root := &treeNode{
		entries: make(map[string]*treeNode),
		files:   []object.TreeEntry{},
	}

	// Insert all entries into the tree structure
	for fullPath, entry := range entries {
		parts := strings.Split(fullPath, "/")
		insertIntoTree(root, parts, entry)
	}

	// Recursively build tree objects from bottom up
	return buildTreeObject(repo, root)
}

// insertIntoTree inserts a file entry into the tree structure.
func insertIntoTree(node *treeNode, pathParts []string, entry object.TreeEntry) {
	if len(pathParts) == 1 {
		// This is a file in the current directory
		node.files = append(node.files, object.TreeEntry{
			Name: pathParts[0],
			Mode: entry.Mode,
			Hash: entry.Hash,
		})
		return
	}

	// This is in a subdirectory
	dirName := pathParts[0]
	if node.entries[dirName] == nil {
		node.entries[dirName] = &treeNode{
			entries: make(map[string]*treeNode),
			files:   []object.TreeEntry{},
		}
	}
	insertIntoTree(node.entries[dirName], pathParts[1:], entry)
}

// buildTreeObject recursively builds tree objects from a treeNode.
func buildTreeObject(repo *git.Repository, node *treeNode) (plumbing.Hash, error) {
	var treeEntries []object.TreeEntry

	// Add files
	treeEntries = append(treeEntries, node.files...)

	// Recursively build subtrees
	for name, subnode := range node.entries {
		subHash, err := buildTreeObject(repo, subnode)
		if err != nil {
			return plumbing.ZeroHash, err
		}
		treeEntries = append(treeEntries, object.TreeEntry{
			Name: name,
			Mode: filemode.Dir,
			Hash: subHash,
		})
	}

	// Sort entries (git requires sorted entries)
	sortTreeEntries(treeEntries)

	// Create tree object
	tree := &object.Tree{Entries: treeEntries}

	obj := repo.Storer.NewEncodedObject()
	if err := tree.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
	}

	return hash, nil
}

// sortTreeEntries sorts tree entries in git's required order.
// Git sorts tree entries by name, with directories having a trailing /
func sortTreeEntries(entries []object.TreeEntry) {
	sort.Slice(entries, func(i, j int) bool {
		nameI := entries[i].Name
		nameJ := entries[j].Name
		if entries[i].Mode == filemode.Dir {
			nameI += "/"
		}
		if entries[j].Mode == filemode.Dir {
			nameJ += "/"
		}
		return nameI < nameJ
	})
}

// collectWorkingDirectoryFiles collects all files in the working directory.
// Excludes .git/ and .entire/ directories.
func collectWorkingDirectoryFiles() ([]string, error) {
	// Get repository root to walk from there
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		repoRoot = "." // Fallback to current directory
	}

	var files []string
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		// Get path relative to repo root
		relPath, err := filepath.Rel(repoRoot, path)
		if err != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories
		if info.IsDir() {
			// Skip .git and .entire directories
			if relPath == gitDir || relPath == entireDir ||
				strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip files in special directories (shouldn't reach here due to SkipDir, but safety check)
		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		files = append(files, relPath)
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to walk directory: %w", err)
	}

	return files, nil
}

package strategy

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"entire.io/cli/cmd/entire/cli/checkpoint"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// isNotFoundError checks if an error represents a "not found" condition in go-git.
// This includes entry not found, file not found, directory not found, and object not found.
func isNotFoundError(err error) bool {
	return errors.Is(err, object.ErrEntryNotFound) ||
		errors.Is(err, object.ErrFileNotFound) ||
		errors.Is(err, object.ErrDirectoryNotFound) ||
		errors.Is(err, plumbing.ErrObjectNotFound) ||
		errors.Is(err, plumbing.ErrReferenceNotFound)
}

// commitOrHead attempts to create a commit. If the commit would be empty (files already
// committed), it returns HEAD hash instead. This handles the case where files were
// modified during a session but already committed by the user before the hook runs.
func commitOrHead(repo *git.Repository, worktree *git.Worktree, msg string, author *object.Signature) (plumbing.Hash, error) {
	commitHash, err := worktree.Commit(msg, &git.CommitOptions{Author: author})
	if errors.Is(err, git.ErrEmptyCommit) {
		fmt.Fprintf(os.Stderr, "No changes to commit (files already committed)\n")
		head, err := repo.Head()
		if err != nil {
			return plumbing.ZeroHash, fmt.Errorf("failed to get HEAD: %w", err)
		}
		return head.Hash(), nil
	}
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to commit: %w", err)
	}
	return commitHash, nil
}

// AutoCommitStrategy implements the auto-commit strategy:
// - Code changes are committed to the active branch (like commit strategy)
// - Session logs are committed to a shadow branch (like manual-commit strategy)
// - Code commits can reference the shadow branch via trailers
type AutoCommitStrategy struct {
	// checkpointStore manages checkpoint data on entire/sessions branch
	checkpointStore *checkpoint.GitStore
	// checkpointStoreOnce ensures thread-safe lazy initialization
	checkpointStoreOnce sync.Once
	// checkpointStoreErr captures any error during initialization
	checkpointStoreErr error
}

// getCheckpointStore returns the checkpoint store, initializing it lazily if needed.
// Thread-safe via sync.Once.
func (s *AutoCommitStrategy) getCheckpointStore() (*checkpoint.GitStore, error) {
	s.checkpointStoreOnce.Do(func() {
		repo, err := OpenRepository()
		if err != nil {
			s.checkpointStoreErr = fmt.Errorf("failed to open repository: %w", err)
			return
		}
		s.checkpointStore = checkpoint.NewGitStore(repo)
	})
	return s.checkpointStore, s.checkpointStoreErr
}

// NewAutoCommitStrategy creates a new AutoCommitStrategy instance
//

func NewAutoCommitStrategy() Strategy {
	return &AutoCommitStrategy{}
}

// NewDualStrategy creates a new auto-commit strategy instance.
// This legacy constructor delegates to NewAutoCommitStrategy.
//

func NewDualStrategy() Strategy {
	return NewAutoCommitStrategy()
}

func (s *AutoCommitStrategy) Name() string {
	return StrategyNameAutoCommit
}

func (s *AutoCommitStrategy) Description() string {
	return "Auto-commits code to active branch with metadata on entire/sessions"
}

// AllowsMainBranch returns true to allow auto-commit strategy on main branch.
// The strategy creates clean commits with Entire-Checkpoint trailers, and detailed
// metadata is stored on the separate entire/sessions orphan branch.
func (s *AutoCommitStrategy) AllowsMainBranch() bool {
	return true
}

func (s *AutoCommitStrategy) ValidateRepository() error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}

	_, err = repo.Worktree()
	if err != nil {
		return fmt.Errorf("failed to access worktree: %w", err)
	}

	return nil
}

// PrePush is called by the git pre-push hook before pushing to a remote.
// It pushes the entire/sessions branch alongside the user's push.
// Configuration options (stored in .entire/settings.json under strategy_options.push_sessions):
//   - "auto": always push automatically
//   - "prompt" (default): ask user with option to enable auto
//   - "false"/"off"/"no": never push
func (s *AutoCommitStrategy) PrePush(remote string) error {
	return pushSessionsBranchCommon(remote, paths.MetadataBranchName)
}

func (s *AutoCommitStrategy) SaveChanges(ctx SaveContext) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Generate checkpoint ID for this commit
	checkpointID := paths.GenerateCheckpointID()

	// Step 1: Commit code changes to active branch with checkpoint ID trailer
	// We do code first to avoid orphaned metadata if this step fails.
	// If metadata commit fails after this, the code commit exists but GetRewindPoints
	// already handles missing metadata gracefully (skips commits without metadata).
	codeResult, err := s.commitCodeToActive(repo, ctx, checkpointID)
	if err != nil {
		return fmt.Errorf("failed to commit code to active branch: %w", err)
	}

	// If no code commit was created (no changes), skip metadata creation
	// This prevents orphaned metadata commits that don't correspond to any code commit
	if !codeResult.Created {
		logCtx := logging.WithComponent(context.Background(), "checkpoint")
		logging.Info(logCtx, "checkpoint skipped (no changes)",
			slog.String("strategy", "auto-commit"),
			slog.String("checkpoint_type", "session"),
		)
		fmt.Fprintf(os.Stderr, "Skipped checkpoint (no changes since last commit)\n")
		return nil
	}

	// Step 2: Commit metadata to entire/sessions branch using sharded path
	// Path is <checkpointID[:2]>/<checkpointID[2:]>/ for direct lookup
	_, err = s.commitMetadataToMetadataBranch(repo, ctx, checkpointID)
	if err != nil {
		return fmt.Errorf("failed to commit metadata to entire/sessions branch: %w", err)
	}

	// Log checkpoint creation
	logCtx := logging.WithComponent(context.Background(), "checkpoint")
	logging.Info(logCtx, "checkpoint saved",
		slog.String("strategy", "auto-commit"),
		slog.String("checkpoint_type", "session"),
		slog.String("checkpoint_id", checkpointID),
		slog.Int("modified_files", len(ctx.ModifiedFiles)),
		slog.Int("new_files", len(ctx.NewFiles)),
		slog.Int("deleted_files", len(ctx.DeletedFiles)),
	)

	return nil
}

// commitCodeResult contains the result of committing code to the active branch.
type commitCodeResult struct {
	CommitHash plumbing.Hash
	Created    bool // True if a new commit was created, false if skipped (no changes)
}

// commitCodeToActive commits code changes to the active branch.
// Adds an Entire-Checkpoint trailer for metadata lookup that survives amend/rebase.
// Returns the result containing commit hash and whether a commit was created.
func (s *AutoCommitStrategy) commitCodeToActive(repo *git.Repository, ctx SaveContext, checkpointID string) (commitCodeResult, error) {
	// Check if there are any code changes to commit
	if len(ctx.ModifiedFiles) == 0 && len(ctx.NewFiles) == 0 && len(ctx.DeletedFiles) == 0 {
		fmt.Fprintf(os.Stderr, "No code changes to commit to active branch\n")
		// Return current HEAD hash but mark as not created
		head, err := repo.Head()
		if err != nil {
			return commitCodeResult{}, fmt.Errorf("failed to get HEAD: %w", err)
		}
		return commitCodeResult{CommitHash: head.Hash(), Created: false}, nil
	}

	worktree, err := repo.Worktree()
	if err != nil {
		return commitCodeResult{}, fmt.Errorf("failed to get worktree: %w", err)
	}

	// Get HEAD hash before commit to detect if commitOrHead actually creates a new commit
	// (commitOrHead returns HEAD hash without error when git.ErrEmptyCommit occurs)
	headBefore, err := repo.Head()
	if err != nil {
		return commitCodeResult{}, fmt.Errorf("failed to get HEAD: %w", err)
	}

	// Stage code changes
	StageFiles(worktree, ctx.ModifiedFiles, ctx.NewFiles, ctx.DeletedFiles, StageForSession)

	// Add checkpoint ID trailer to commit message
	commitMsg := ctx.CommitMessage + "\n\n" + paths.CheckpointTrailerKey + ": " + checkpointID

	author := &object.Signature{
		Name:  ctx.AuthorName,
		Email: ctx.AuthorEmail,
		When:  time.Now(),
	}
	commitHash, err := commitOrHead(repo, worktree, commitMsg, author)
	if err != nil {
		return commitCodeResult{}, err
	}

	// Check if a new commit was actually created by comparing with HEAD before
	created := commitHash != headBefore.Hash()
	if created {
		fmt.Fprintf(os.Stderr, "Committed code changes to active branch (%s)\n", commitHash.String()[:7])
	}
	return commitCodeResult{CommitHash: commitHash, Created: created}, nil
}

// commitMetadataToMetadataBranch commits session metadata to the entire/sessions branch.
// Metadata is stored at sharded path: <checkpointID[:2]>/<checkpointID[2:]>/
// This allows direct lookup from the checkpoint ID trailer on the code commit.
// Uses checkpoint.WriteCommitted for git operations.
func (s *AutoCommitStrategy) commitMetadataToMetadataBranch(repo *git.Repository, ctx SaveContext, checkpointID string) (plumbing.Hash, error) {
	store, err := s.getCheckpointStore()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Extract session ID from metadata dir
	sessionID := filepath.Base(ctx.MetadataDir)

	// Get current branch name
	branchName := GetCurrentBranchName(repo)

	// Write committed checkpoint using the checkpoint store
	err = store.WriteCommitted(context.Background(), checkpoint.WriteCommittedOptions{
		CheckpointID:           checkpointID,
		SessionID:              sessionID,
		Strategy:               StrategyNameAutoCommit, // Use new strategy name
		Branch:                 branchName,
		MetadataDir:            ctx.MetadataDirAbs, // Copy all files from metadata dir
		AuthorName:             ctx.AuthorName,
		AuthorEmail:            ctx.AuthorEmail,
		Agent:                  ctx.AgentType,
		TranscriptUUIDAtStart:  ctx.TranscriptUUIDAtStart,
		TranscriptLinesAtStart: ctx.TranscriptLinesAtStart,
		TokenUsage:             ctx.TokenUsage,
	})
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to write committed checkpoint: %w", err)
	}

	fmt.Fprintf(os.Stderr, "Committed session metadata to %s (%s)\n", paths.MetadataBranchName, checkpointID)
	return plumbing.ZeroHash, nil // Commit hash not needed by callers
}

func (s *AutoCommitStrategy) GetRewindPoints(limit int) ([]RewindPoint, error) {
	// For auto-commit strategy, rewind points are found by looking for Entire-Checkpoint trailers
	// in the current branch's commit history. The checkpoint ID provides direct lookup
	// to metadata on entire/sessions branch.
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	// Get metadata branch tree for lookups
	metadataTree, err := GetMetadataBranchTree(repo)
	if err != nil {
		// No metadata branch yet is fine
		return []RewindPoint{}, nil //nolint:nilerr // Expected when no metadata exists
	}

	// Get the main branch commit hash to determine branch-only commits
	mainBranchHash := GetMainBranchHash(repo)

	// Walk current branch history looking for commits with checkpoint trailers
	iter, err := repo.Log(&git.LogOptions{
		From:  head.Hash(),
		Order: git.LogOrderCommitterTime,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var points []RewindPoint
	count := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= logsOnlyScanLimit || len(points) >= limit {
			return errStop
		}
		count++

		// Check for Entire-Checkpoint trailer
		checkpointID, found := paths.ParseCheckpointTrailer(c.Message)
		if !found {
			return nil
		}

		// Look up metadata from sharded path
		checkpointPath := paths.CheckpointPath(checkpointID)
		metadata, err := ReadCheckpointMetadata(metadataTree, checkpointPath)
		if err != nil {
			// Checkpoint exists in commit but no metadata found - skip this commit
			return nil //nolint:nilerr // Intentional: skip commits without metadata
		}

		message := strings.Split(c.Message, "\n")[0]

		// Determine if this is a full rewind or logs-only
		// Full rewind is allowed if commit is only on this branch (not reachable from main)
		isLogsOnly := false
		if mainBranchHash != plumbing.ZeroHash {
			if isAncestor(repo, c.Hash, mainBranchHash) {
				isLogsOnly = true
			}
		}

		// Build metadata path - for task checkpoints, include the task path
		metadataDir := checkpointPath
		if metadata.IsTask && metadata.ToolUseID != "" {
			metadataDir = checkpointPath + "/tasks/" + metadata.ToolUseID
		}

		// Read session prompt from metadata tree
		sessionPrompt := ReadSessionPromptFromTree(metadataTree, checkpointPath)

		points = append(points, RewindPoint{
			ID:               c.Hash.String(),
			Message:          message,
			MetadataDir:      metadataDir,
			Date:             c.Author.When,
			IsLogsOnly:       isLogsOnly,
			CheckpointID:     checkpointID,
			IsTaskCheckpoint: metadata.IsTask,
			ToolUseID:        metadata.ToolUseID,
			Agent:            metadata.Agent,
			SessionID:        metadata.SessionID,
			SessionPrompt:    sessionPrompt,
		})

		return nil
	})

	if err != nil && !errors.Is(err, errStop) {
		return nil, fmt.Errorf("failed to iterate commits: %w", err)
	}

	return points, nil
}

// isAncestor checks if commit is an ancestor of (or equal to) target.
// Returns true if target can reach commit by following parent links.
func isAncestor(repo *git.Repository, commit, target plumbing.Hash) bool {
	if commit == target {
		return true
	}

	// Walk from target backwards to see if we reach commit
	iter, err := repo.Log(&git.LogOptions{From: target})
	if err != nil {
		return false
	}

	found := false
	count := 0
	_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are non-fatal
		count++
		if count > 1000 {
			return errStop // Limit search depth
		}
		if c.Hash == commit {
			found = true
			return errStop
		}
		return nil
	})

	return found
}

// findTaskMetadataPathForCommit looks up the task metadata path for a task checkpoint commit
// by searching the entire/sessions branch commit history for the checkpoint directory.
// Returns ("", nil) if metadata is not found - this is expected for commits without metadata.
func (s *AutoCommitStrategy) findTaskMetadataPathForCommit(repo *git.Repository, commitSHA, toolUseID string) (string, error) {
	// Get the entire/sessions branch
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		if isNotFoundError(err) {
			return "", nil // No metadata branch yet
		}
		return "", fmt.Errorf("failed to get metadata branch: %w", err)
	}

	// Search commit history for a commit referencing this code commit SHA and tool use ID
	shortSHA := commitSHA
	if len(shortSHA) > 7 {
		shortSHA = shortSHA[:7]
	}

	iter, err := repo.Log(&git.LogOptions{From: ref.Hash()})
	if err != nil {
		return "", fmt.Errorf("failed to get commit log: %w", err)
	}

	var foundTaskPath string
	err = iter.ForEach(func(commit *object.Commit) error {
		// Check if commit message contains "Commit: <sha>" and the tool use ID
		if strings.Contains(commit.Message, "Commit: "+shortSHA) &&
			strings.Contains(commit.Message, toolUseID) {
			// Parse task metadata trailer
			if taskPath, found := paths.ParseTaskMetadataTrailer(commit.Message); found {
				foundTaskPath = taskPath
				return errStop // Found it
			}
		}
		return nil
	})
	if err != nil && !errors.Is(err, errStop) {
		return "", fmt.Errorf("failed to iterate commits: %w", err)
	}

	return foundTaskPath, nil
}

func (s *AutoCommitStrategy) Rewind(point RewindPoint) error {
	commitHash := plumbing.NewHash(point.ID)
	shortID, err := HardResetWithProtection(commitHash)
	if err != nil {
		return err
	}

	fmt.Println()
	fmt.Printf("Reset to commit %s\n", shortID)
	fmt.Println()

	return nil
}

