			}
		}
		return nil
	})

	// Filter sessions
	filtered := make([]strategy.Session, 0, len(sessions))
	for _, sess := range sessions {
		if matchingSessionIDs[sess.ID] {
			filtered = append(filtered, sess)
		}
	}

	return filtered
}

