	head, err := repo.Head()
	if err != nil {
		t.Fatalf("failed to get HEAD: %v", err)
	}

	// The auto-commit strategy amends the HEAD commit to add source ref trailer,
	// so HEAD will be different from the initial commit even without file changes.
