				t.Errorf("ParseMetadataTrailer() found = %v, want %v", gotFound, tt.wantFound)
			}
			if gotDir != tt.wantDir {
				t.Errorf("ParseMetadataTrailer() dir = %v, want %v", gotDir, tt.wantDir)
			}
		})
	}
}

