// GetRewindPoints returns available rewind points.
// Uses checkpoint.GitStore.ListTemporaryCheckpoints for reading from shadow branches.
func (s *ManualCommitStrategy) GetRewindPoints(limit int) ([]RewindPoint, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get checkpoint store
	store, err := s.getCheckpointStore()
	if err != nil {
		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Get current HEAD to find matching shadow branch
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	// Find sessions for current HEAD
	sessions, err := s.findSessionsForCommit(head.Hash().String())
	if err != nil {
		// Log error but continue to check for logs-only points
		sessions = nil
	}

	var allPoints []RewindPoint

	// Collect checkpoint points from active sessions using checkpoint.GitStore
	// Cache session prompts by session ID to avoid re-reading the same prompt file
	sessionPrompts := make(map[string]string)

	for _, state := range sessions {
		checkpoints, err := store.ListTemporaryCheckpoints(context.Background(), state.BaseCommit, state.SessionID, limit)
		if err != nil {
			continue // Error reading checkpoints, skip this session
		}

		for _, cp := range checkpoints {
			// Get session prompt (cached by session ID)
			sessionPrompt, ok := sessionPrompts[cp.SessionID]
			if !ok {
				sessionPrompt = readSessionPrompt(repo, cp.CommitHash, cp.MetadataDir)
				sessionPrompts[cp.SessionID] = sessionPrompt
			}

			allPoints = append(allPoints, RewindPoint{
				ID:               cp.CommitHash.String(),
				Message:          cp.Message,
				MetadataDir:      cp.MetadataDir,
				Date:             cp.Timestamp,
				IsTaskCheckpoint: cp.IsTaskCheckpoint,
				ToolUseID:        cp.ToolUseID,
				SessionID:        cp.SessionID,
				SessionPrompt:    sessionPrompt,
			})
		}
	}

	// Sort by date, most recent first
	sort.Slice(allPoints, func(i, j int) bool {
		return allPoints[i].Date.After(allPoints[j].Date)
	})

	if len(allPoints) > limit {
		allPoints = allPoints[:limit]
	}

	// Also include logs-only points from commit history
	logsOnlyPoints, err := s.GetLogsOnlyRewindPoints(limit)
	if err == nil && len(logsOnlyPoints) > 0 {
		// Build set of existing point IDs for deduplication
		existingIDs := make(map[string]bool)
		for _, p := range allPoints {
			existingIDs[p.ID] = true
		}

		// Add logs-only points that aren't already in the list
		for _, p := range logsOnlyPoints {
			if !existingIDs[p.ID] {
				allPoints = append(allPoints, p)
			}
		}

		// Re-sort by date
		sort.Slice(allPoints, func(i, j int) bool {
			return allPoints[i].Date.After(allPoints[j].Date)
		})

		// Re-trim to limit
		if len(allPoints) > limit {
			allPoints = allPoints[:limit]
		}
	}

	return allPoints, nil
}

// GetLogsOnlyRewindPoints finds commits in the current branch's history that have
// condensed session logs on the entire/sessions branch. These are commits that
// were created with session data but the shadow branch has been condensed.
//
// The function works by:
// 1. Getting all checkpoints from the entire/sessions branch
// 2. Building a map of checkpoint ID -> checkpoint info
// 3. Scanning the current branch history for commits with Entire-Checkpoint trailers
// 4. Matching by checkpoint ID (stable across amend/rebase)
func (s *ManualCommitStrategy) GetLogsOnlyRewindPoints(limit int) ([]RewindPoint, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, err
	}

	// Get all checkpoints from entire/sessions branch
	checkpoints, err := s.listCheckpoints()
	if err != nil {
		// No checkpoints yet is fine
		return nil, nil //nolint:nilerr // Expected when no checkpoints exist
	}

	if len(checkpoints) == 0 {
		return nil, nil
	}

	// Build map of checkpoint ID -> checkpoint info
	// Checkpoint ID is the stable link from Entire-Checkpoint trailer
	checkpointInfoMap := make(map[string]CheckpointInfo)
	for _, cp := range checkpoints {
		if cp.CheckpointID != "" {
			checkpointInfoMap[cp.CheckpointID] = cp
		}
	}

	// Get metadata branch tree for reading session prompts (best-effort, ignore errors)
	metadataTree, _ := GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort for session prompts

	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	// Use LogOptions with Order=LogOrderCommitterTime to traverse all parents of merge commits.
	iter, err := repo.Log(&git.LogOptions{
		From:  head.Hash(),
		Order: git.LogOrderCommitterTime,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var points []RewindPoint
	count := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= logsOnlyScanLimit {
			return errStop
		}
		count++

		// Extract checkpoint ID from Entire-Checkpoint trailer
		cpID, hasTrailer := trailers.ParseCheckpoint(c.Message)
		if !hasTrailer || cpID.IsEmpty() {
			return nil
		}
		checkpointID := cpID.String()

		// Check if this checkpoint ID has metadata on entire/sessions
		cpInfo, found := checkpointInfoMap[checkpointID]
		if !found {
			return nil
		}

		// Create logs-only rewind point
		message := strings.Split(c.Message, "\n")[0]

		// Read session prompts from metadata tree
		var sessionPrompt string
		var sessionPrompts []string
		if metadataTree != nil {
			checkpointPath := trailers.CheckpointPath(cpInfo.CheckpointID)
			// For multi-session checkpoints, read all prompts
			if cpInfo.SessionCount > 1 && len(cpInfo.SessionIDs) > 1 {
				sessionPrompts = ReadAllSessionPromptsFromTree(metadataTree, checkpointPath, cpInfo.SessionCount, cpInfo.SessionIDs)
				// Use the last (most recent) prompt as the main session prompt
				if len(sessionPrompts) > 0 {
					sessionPrompt = sessionPrompts[len(sessionPrompts)-1]
				}
			} else {
				sessionPrompt = ReadSessionPromptFromTree(metadataTree, checkpointPath)
				if sessionPrompt != "" {
					sessionPrompts = []string{sessionPrompt}
				}
			}
		}

		points = append(points, RewindPoint{
			ID:             c.Hash.String(),
			Message:        message,
			Date:           c.Author.When,
			IsLogsOnly:     true,
			CheckpointID:   cpInfo.CheckpointID,
			Agent:          cpInfo.Agent,
			SessionID:      cpInfo.SessionID,
			SessionPrompt:  sessionPrompt,
			SessionCount:   cpInfo.SessionCount,
			SessionIDs:     cpInfo.SessionIDs,
			SessionPrompts: sessionPrompts,
		})

		return nil
	})

	if err != nil && !errors.Is(err, errStop) {
		return nil, fmt.Errorf("error iterating commits: %w", err)
	}

	if len(points) > limit {
		points = points[:limit]
	}

	return points, nil
}

// Rewind restores the working directory to a checkpoint.
//
//nolint:maintidx // Complex rewind flow spans multiple recovery modes.
func (s *ManualCommitStrategy) Rewind(point RewindPoint) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get the checkpoint commit
	commitHash := plumbing.NewHash(point.ID)
	commit, err := repo.CommitObject(commitHash)
	if err != nil {
		return fmt.Errorf("failed to get commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get tree: %w", err)
	}

	// Reset the shadow branch to the rewound checkpoint
	// This ensures the next checkpoint will only include prompts from this point forward
	if err := s.resetShadowBranchToCheckpoint(repo, commit); err != nil {
		// Log warning but don't fail - file restoration is the primary operation
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
	}

	// Load session state to get untracked files that existed at session start
	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
	var preservedUntrackedFiles map[string]bool
	if hasSessionTrailer {
		state, stateErr := s.loadSessionState(sessionID)
		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
			preservedUntrackedFiles = make(map[string]bool)
			for _, f := range state.UntrackedFilesAtStart {
				preservedUntrackedFiles[f] = true
			}
		}
	}

	// Build set of files in the checkpoint tree (excluding metadata)
	checkpointFiles := make(map[string]bool)
	err = tree.Files().ForEach(func(f *object.File) error {
		if !strings.HasPrefix(f.Name, entireDir) {
			checkpointFiles[f.Name] = true
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to list checkpoint files: %w", err)
	}

	// Get HEAD tree to identify tracked files
	head, err := repo.Head()
	if err != nil {
		return fmt.Errorf("failed to get HEAD: %w", err)
	}
	headCommit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return fmt.Errorf("failed to get HEAD commit: %w", err)
	}
	headTree, err := headCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get HEAD tree: %w", err)
	}

	// Build set of files tracked in HEAD
	trackedFiles := make(map[string]bool)
	//nolint:errcheck // Error is not critical for rewind
	_ = headTree.Files().ForEach(func(f *object.File) error {
		trackedFiles[f.Name] = true
		return nil
	})

	// Get repository root to walk from there
	repoRoot, err := GetWorktreePath()
	if err != nil {
		repoRoot = "." // Fallback to current directory
	}

	// Find and delete untracked files that aren't in the checkpoint
	// These are likely files created by Claude in later checkpoints
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		// Get path relative to repo root
		relPath, relErr := filepath.Rel(repoRoot, path)
		if relErr != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories and special paths
		if info.IsDir() {
			if relPath == gitDir || relPath == claudeDir || relPath == entireDir || strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip if path is a special directory
		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		// If file is in checkpoint, it will be restored
		if checkpointFiles[relPath] {
			return nil
		}

		// If file is tracked in HEAD, don't delete (user's committed work)
		if trackedFiles[relPath] {
			return nil
		}

		// If file existed at session start, preserve it (untracked user files)
		if preservedUntrackedFiles[relPath] {
			return nil
		}

		// File is untracked and not in checkpoint - delete it (use absolute path)
		if removeErr := os.Remove(path); removeErr == nil {
			fmt.Fprintf(os.Stderr, "  Deleted: %s\n", relPath)
		}

		return nil
	})
	if err != nil {
		// Non-fatal - continue with restoration
		fmt.Fprintf(os.Stderr, "Warning: error walking directory: %v\n", err)
	}

	// Restore files from checkpoint
	err = tree.Files().ForEach(func(f *object.File) error {
		// Skip metadata directories - these are for checkpoint storage, not working dir
		if strings.HasPrefix(f.Name, entireDir) {
			return nil
		}

		contents, err := f.Contents()
		if err != nil {
			return fmt.Errorf("failed to read file %s: %w", f.Name, err)
		}

		// Ensure directory exists
		dir := filepath.Dir(f.Name)
		if dir != "." {
			//nolint:gosec // G301: Need 0o755 for user directories during rewind
			if err := os.MkdirAll(dir, 0o755); err != nil {
				return fmt.Errorf("failed to create directory %s: %w", dir, err)
			}
		}

		// Write file with appropriate permissions
		var perm os.FileMode = 0o644
		if f.Mode == filemode.Executable {
			perm = 0o755
		}
		if err := os.WriteFile(f.Name, []byte(contents), perm); err != nil {
			return fmt.Errorf("failed to write file %s: %w", f.Name, err)
		}

		fmt.Fprintf(os.Stderr, "  Restored: %s\n", f.Name)
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to iterate tree files: %w", err)
	}

	fmt.Println()
	if len(point.ID) >= 7 {
		fmt.Printf("Restored files from shadow commit %s\n", point.ID[:7])
	} else {
		fmt.Printf("Restored files from shadow commit %s\n", point.ID)
	}
	fmt.Println()

	return nil
}

// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
// This ensures that when the user commits after rewinding, the next checkpoint will only
// include prompts from the rewound point, not prompts from later checkpoints.
func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(repo *git.Repository, commit *object.Commit) error {
	// Extract session ID from the checkpoint commit's Entire-Session trailer
	sessionID, found := trailers.ParseSession(commit.Message)
	if !found {
		return errors.New("checkpoint has no Entire-Session trailer")
	}

	// Load session state to get the shadow branch name
	state, err := s.loadSessionState(sessionID)
	if err != nil {
		return fmt.Errorf("failed to load session state: %w", err)
	}
	if state == nil {
		return fmt.Errorf("session %s not found", sessionID)
	}

	// Reset the shadow branch to the checkpoint commit
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	// Update the reference to point to the checkpoint commit
	ref := plumbing.NewHashReference(refName, commit.Hash)
	if err := repo.Storer.SetReference(ref); err != nil {
		return fmt.Errorf("failed to update shadow branch: %w", err)
	}

	fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
	return nil
}

// CanRewind checks if rewinding is possible.
// For manual-commit strategy, rewind restores files from a checkpoint - uncommitted changes are expected
// and will be replaced by the checkpoint contents. Returns true with a warning message showing
// what changes will be reverted.
func (s *ManualCommitStrategy) CanRewind() (bool, string, error) {
	return checkCanRewindWithWarning()
}

// PreviewRewind returns what will happen if rewinding to the given point.
// This allows showing warnings about untracked files that will be deleted.
func (s *ManualCommitStrategy) PreviewRewind(point RewindPoint) (*RewindPreview, error) {
	// Logs-only points don't modify the working directory
	if point.IsLogsOnly {
		return &RewindPreview{}, nil
	}

	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get the checkpoint commit
	commitHash := plumbing.NewHash(point.ID)
	commit, err := repo.CommitObject(commitHash)
	if err != nil {
		return nil, fmt.Errorf("failed to get commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get tree: %w", err)
	}

	// Load session state to get untracked files that existed at session start
	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
	var preservedUntrackedFiles map[string]bool
	if hasSessionTrailer {
		state, stateErr := s.loadSessionState(sessionID)
		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
			preservedUntrackedFiles = make(map[string]bool)
			for _, f := range state.UntrackedFilesAtStart {
				preservedUntrackedFiles[f] = true
			}
		}
	}

	// Build set of files in the checkpoint tree (excluding metadata)
	checkpointFiles := make(map[string]bool)
	var filesToRestore []string
	err = tree.Files().ForEach(func(f *object.File) error {
		if !strings.HasPrefix(f.Name, entireDir) {
			checkpointFiles[f.Name] = true
			filesToRestore = append(filesToRestore, f.Name)
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
	}

	// Get HEAD tree to identify tracked files
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}
	headCommit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
	}
	headTree, err := headCommit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
	}

	// Build set of files tracked in HEAD
	trackedFiles := make(map[string]bool)
	//nolint:errcheck // Error is not critical for preview
	_ = headTree.Files().ForEach(func(f *object.File) error {
		trackedFiles[f.Name] = true
		return nil
	})

	// Get repository root to walk from there
	repoRoot, err := GetWorktreePath()
	if err != nil {
		repoRoot = "."
	}

	// Find untracked files that would be deleted
	var filesToDelete []string
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		relPath, relErr := filepath.Rel(repoRoot, path)
		if relErr != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories and special paths
		if info.IsDir() {
			if relPath == gitDir || relPath == claudeDir || relPath == entireDir ||
				strings.HasPrefix(relPath, gitDir+"/") ||
				strings.HasPrefix(relPath, claudeDir+"/") ||
				strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip special directories
		if strings.HasPrefix(relPath, gitDir+"/") ||
			strings.HasPrefix(relPath, claudeDir+"/") ||
			strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		// If file is in checkpoint, it will be restored (not deleted)
		if checkpointFiles[relPath] {
			return nil
		}

		// If file is tracked in HEAD, don't delete (user's committed work)
		if trackedFiles[relPath] {
			return nil
		}

		// If file existed at session start, preserve it (untracked user files)
		if preservedUntrackedFiles[relPath] {
			return nil
		}

		// File is untracked and not in checkpoint - will be deleted
		filesToDelete = append(filesToDelete, relPath)
		return nil
	})
	if err != nil {
		// Non-fatal, return what we have
		return &RewindPreview{ //nolint:nilerr // Partial result is still useful
			FilesToRestore: filesToRestore,
			FilesToDelete:  filesToDelete,
		}, nil
	}

	// Sort for consistent output
	sort.Strings(filesToRestore)
	sort.Strings(filesToDelete)

	return &RewindPreview{
		FilesToRestore: filesToRestore,
		FilesToDelete:  filesToDelete,
	}, nil
}

// RestoreLogsOnly restores session logs from a logs-only rewind point.
// This fetches the transcript from entire/sessions and writes it to Claude's project directory.
// Does not modify the working directory.
// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
// If force is false, prompts for confirmation when local logs have newer timestamps.
func (s *ManualCommitStrategy) RestoreLogsOnly(point RewindPoint, force bool) error {
	if !point.IsLogsOnly {
		return errors.New("not a logs-only rewind point")
	}

	if point.CheckpointID == "" {
		return errors.New("missing checkpoint ID")
	}

	// Get checkpoint store
	store, err := s.getCheckpointStore()
	if err != nil {
		return fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Read full checkpoint data including archived sessions
	result, err := store.ReadCommitted(context.Background(), point.CheckpointID)
	if err != nil {
		return fmt.Errorf("failed to read checkpoint: %w", err)
	}
	if result == nil {
		return fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
	}
	if len(result.Transcript) == 0 {
		return fmt.Errorf("no transcript found for checkpoint: %s", point.CheckpointID)
	}

	// Get repo root for Claude project path lookup
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return fmt.Errorf("failed to get repository root: %w", err)
	}

	claudeProjectDir, err := paths.GetClaudeProjectDir(repoRoot)
	if err != nil {
		return fmt.Errorf("failed to get Claude project directory: %w", err)
	}

	// Ensure project directory exists
	if err := os.MkdirAll(claudeProjectDir, 0o750); err != nil {
		return fmt.Errorf("failed to create Claude project directory: %w", err)
	}

	// Check for newer local logs if not forcing
	if !force {
		sessions := s.classifySessionsForRestore(claudeProjectDir, result)
		hasConflicts := false
		for _, sess := range sessions {
			if sess.Status == StatusLocalNewer {
				hasConflicts = true
				break
			}
		}
		if hasConflicts {
			shouldOverwrite, promptErr := PromptOverwriteNewerLogs(sessions)
			if promptErr != nil {
				return promptErr
			}
			if !shouldOverwrite {
				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session logs preserved.\n")
				return nil
			}
		}
	}

	// Count sessions to restore
	totalSessions := 1 + len(result.ArchivedSessions)
	if totalSessions > 1 {
		fmt.Fprintf(os.Stderr, "Restoring %d sessions from checkpoint:\n", totalSessions)
	}

	// Restore archived sessions first (oldest to newest)
	for _, archived := range result.ArchivedSessions {
		if len(archived.Transcript) == 0 {
			continue
		}

		sessionID := archived.SessionID
		if sessionID == "" {
			// Fallback: can't identify session without ID
			fmt.Fprintf(os.Stderr, "  Warning: archived session %d has no session ID, skipping\n", archived.FolderIndex)
			continue
		}

		modelSessionID := paths.ModelSessionID(sessionID)
		claudeSessionFile := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")

		// Get first prompt for display
		promptPreview := ExtractFirstPrompt(archived.Prompts)
		if promptPreview != "" {
			fmt.Fprintf(os.Stderr, "  Session %d: %s\n", archived.FolderIndex, promptPreview)
		}

		fmt.Fprintf(os.Stderr, "    Writing to: %s\n", claudeSessionFile)
		if err := os.WriteFile(claudeSessionFile, archived.Transcript, 0o600); err != nil {
			fmt.Fprintf(os.Stderr, "    Warning: failed to write transcript: %v\n", err)
			continue
		}
	}

	// Restore the most recent session (at root level)
	sessionID := result.Metadata.SessionID
	if sessionID == "" {
		// Fall back to extracting from commit's Entire-Session trailer
		sessionID = s.extractSessionIDFromCommit(point.ID)
		if sessionID == "" {
			return errors.New("failed to determine session ID for latest session")
		}
	}

	modelSessionID := paths.ModelSessionID(sessionID)
	claudeSessionFile := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")

	if totalSessions > 1 {
		promptPreview := ExtractFirstPrompt(result.Prompts)
		if promptPreview != "" {
			fmt.Fprintf(os.Stderr, "  Session %d (latest): %s\n", totalSessions, promptPreview)
		}
		fmt.Fprintf(os.Stderr, "    Writing to: %s\n", claudeSessionFile)
	} else {
		fmt.Fprintf(os.Stderr, "Writing transcript to: %s\n", claudeSessionFile)
	}

	if err := os.WriteFile(claudeSessionFile, result.Transcript, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// extractSessionIDFromCommit extracts the session ID from a commit's Entire-Session trailer.
func (s *ManualCommitStrategy) extractSessionIDFromCommit(commitHash string) string {
	repo, err := OpenRepository()
	if err != nil {
		return ""
	}

	hash, err := repo.ResolveRevision(plumbing.Revision(commitHash))
	if err != nil {
		return ""
	}

	commit, err := repo.CommitObject(*hash)
	if err != nil {
		return ""
	}

	// Parse Entire-Session trailer
	sessionID, found := trailers.ParseSession(commit.Message)
	if found {
		return sessionID
	}

	return ""
}

// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
// Returns an empty string if the prompt cannot be read.
func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
	// Get the commit and its tree
	commit, err := repo.CommitObject(commitHash)
	if err != nil {
		return ""
	}

	tree, err := commit.Tree()
	if err != nil {
		return ""
	}

	// Look for prompt.txt in the metadata directory
	promptPath := metadataDir + "/" + paths.PromptFileName
	promptEntry, err := tree.File(promptPath)
	if err != nil {
		return ""
	}

	content, err := promptEntry.Contents()
	if err != nil {
		return ""
	}

	return ExtractFirstPrompt(content)
}

// SessionRestoreStatus represents the status of a session being restored.
type SessionRestoreStatus int

const (
	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
	StatusUnchanged                                   // Local and checkpoint are the same
	StatusCheckpointNewer                             // Checkpoint has newer entries
	StatusLocalNewer                                  // Local has newer entries (conflict)
)

// SessionRestoreInfo contains information about a session being restored.
type SessionRestoreInfo struct {
	SessionID      string
	Prompt         string               // First prompt preview for display
	Status         SessionRestoreStatus // Status of this session
	LocalTime      time.Time
	CheckpointTime time.Time
}

// classifySessionsForRestore checks all sessions in a checkpoint result and returns info
// about each session, including whether local logs have newer timestamps.
func (s *ManualCommitStrategy) classifySessionsForRestore(claudeProjectDir string, result *cpkg.ReadCommittedResult) []SessionRestoreInfo {
	var sessions []SessionRestoreInfo

	// Check archived sessions
	for _, archived := range result.ArchivedSessions {
		if len(archived.Transcript) == 0 || archived.SessionID == "" {
			continue
		}

		modelSessionID := paths.ModelSessionID(archived.SessionID)
		localPath := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")

		localTime := paths.GetLastTimestampFromFile(localPath)
		checkpointTime := paths.GetLastTimestampFromBytes(archived.Transcript)
		status := ClassifyTimestamps(localTime, checkpointTime)

		sessions = append(sessions, SessionRestoreInfo{
			SessionID:      archived.SessionID,
			Prompt:         ExtractFirstPrompt(archived.Prompts),
			Status:         status,
			LocalTime:      localTime,
			CheckpointTime: checkpointTime,
		})
	}

	// Check primary session
	if result.Metadata.SessionID != "" && len(result.Transcript) > 0 {
		modelSessionID := paths.ModelSessionID(result.Metadata.SessionID)
		localPath := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")

		localTime := paths.GetLastTimestampFromFile(localPath)
		checkpointTime := paths.GetLastTimestampFromBytes(result.Transcript)
		status := ClassifyTimestamps(localTime, checkpointTime)

		sessions = append(sessions, SessionRestoreInfo{
			SessionID:      result.Metadata.SessionID,
			Prompt:         ExtractFirstPrompt(result.Prompts),
			Status:         status,
			LocalTime:      localTime,
			CheckpointTime: checkpointTime,
		})
	}

	return sessions
}

// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
	// Local file doesn't exist (no timestamp found)
	if localTime.IsZero() {
		return StatusNew
	}

	// Can't determine checkpoint time - treat as new/safe
	if checkpointTime.IsZero() {
		return StatusNew
	}

	// Compare timestamps
	if localTime.After(checkpointTime) {
		return StatusLocalNewer
	}
	if checkpointTime.After(localTime) {
		return StatusCheckpointNewer
	}
	return StatusUnchanged
}

// StatusToText returns a human-readable status string.
func StatusToText(status SessionRestoreStatus) string {
	switch status {
	case StatusNew:
		return "(new)"
	case StatusUnchanged:
		return "(unchanged)"
	case StatusCheckpointNewer:
		return "(checkpoint is newer)"
	case StatusLocalNewer:
		return "(local is newer)" // shouldn't appear in non-conflict list
	default:
		return ""
	}
}

// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
// session logs that have newer timestamps than the checkpoint versions.
func PromptOverwriteNewerLogs(sessions []SessionRestoreInfo) (bool, error) {
	// Separate conflicting and non-conflicting sessions
	var conflicting, nonConflicting []SessionRestoreInfo
	for _, s := range sessions {
		if s.Status == StatusLocalNewer {
			conflicting = append(conflicting, s)
		} else {
			nonConflicting = append(nonConflicting, s)
		}
	}

	fmt.Fprintf(os.Stderr, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
	for _, info := range conflicting {
		// Show prompt if available, otherwise fall back to session ID
		if info.Prompt != "" {
			fmt.Fprintf(os.Stderr, "  \"%s\"\n", info.Prompt)
		} else {
			fmt.Fprintf(os.Stderr, "  Session: %s\n", info.SessionID)
		}
		fmt.Fprintf(os.Stderr, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
		fmt.Fprintf(os.Stderr, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
	}

	// Show non-conflicting sessions with their status
	if len(nonConflicting) > 0 {
		fmt.Fprintf(os.Stderr, "\nThese other session(s) will also be restored:\n")
		for _, info := range nonConflicting {
			statusText := StatusToText(info.Status)
			if info.Prompt != "" {
				fmt.Fprintf(os.Stderr, "  \"%s\" %s\n", info.Prompt, statusText)
			} else {
				fmt.Fprintf(os.Stderr, "  Session: %s %s\n", info.SessionID, statusText)
			}
		}
	}

	fmt.Fprintf(os.Stderr, "\nOverwriting will lose the newer local entries.\n\n")

	var confirmed bool
	form := huh.NewForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Overwrite local session logs with checkpoint versions?").
				Value(&confirmed),
		),
	)
	if isAccessibleMode() {
		form = form.WithAccessible(true)
	}

	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) {
			return false, nil
		}
		return false, fmt.Errorf("failed to get confirmation: %w", err)
	}

	return confirmed, nil
}

package strategy

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/trailers"
	"github.com/go-git/go-git/v5"
)

// NoDescription is the default description for sessions without one.
const NoDescription = "No description"

// Session represents a Claude Code session with its checkpoints.
// A session is created when a user runs `claude` and tracks all changes
// made during that interaction.
type Session struct {
	// ID is the unique session identifier (e.g., "2025-12-01-8f76b0e8-b8f1-4a87-9186-848bdd83d62e")
	ID string

	// Description is a human-readable summary of the session
	// (typically the first prompt or derived from commit messages)
	Description string

	// Strategy is the name of the strategy that created this session
	Strategy string

	// StartTime is when the session was started
	StartTime time.Time

	// Checkpoints is the list of save points within this session
	Checkpoints []Checkpoint
}

// Checkpoint represents a save point within a session.
// Checkpoints can be either session-level (on Stop) or task-level (on subagent completion).
type Checkpoint struct {
	// CheckpointID is the stable 12-hex-char identifier for this checkpoint.
	// Used to look up metadata at <id[:2]>/<id[2:]>/ on entire/sessions branch.
	CheckpointID string

	// Message is the commit message or checkpoint description
	Message string

	// Timestamp is when this checkpoint was created
	Timestamp time.Time

	// IsTaskCheckpoint indicates if this is a task checkpoint (vs a session checkpoint)
	IsTaskCheckpoint bool

	// ToolUseID is the tool use ID for task checkpoints (empty for session checkpoints)
	ToolUseID string
}

// PromptResponse represents a single user prompt and assistant response pair.
type PromptResponse struct {
	// Prompt is the user's message
	Prompt string

	// Response is the assistant's response
	Response string

	// Files is the list of files modified during this prompt/response
	Files []string
}

// CheckpointDetails contains detailed information extracted from a checkpoint's transcript.
// This is used by the explain command to display checkpoint content.
type CheckpointDetails struct {
	// Interactions contains all prompt/response pairs in this checkpoint.
	// For strategies like auto-commit/commit, this typically has one entry.
	// For strategies like shadow, this may have multiple entries.
	Interactions []PromptResponse

	// Files is the aggregate list of all files modified in this checkpoint.
	// This is a convenience field that combines files from all interactions.
	Files []string
}

// ListSessions returns all sessions from the entire/sessions branch,
// plus any additional sessions from strategies implementing SessionSource.
// It automatically discovers all registered strategies and merges their sessions.
func ListSessions() ([]Session, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get checkpoints from the entire/sessions branch
	checkpoints, err := ListCheckpoints()
	if err != nil {
		return nil, fmt.Errorf("failed to list checkpoints: %w", err)
	}

	// Group checkpoints by session ID
	// For multi-session checkpoints, expand SessionIDs array so each session gets the checkpoint
	sessionMap := make(map[string]*Session)
	for _, cp := range checkpoints {
		// Determine which session IDs this checkpoint belongs to
		// Multi-session checkpoints have SessionIDs populated; single-session use SessionID
		sessionIDs := cp.SessionIDs
		if len(sessionIDs) == 0 {
			sessionIDs = []string{cp.SessionID}
		}

		for _, sessionID := range sessionIDs {
			if sessionID == "" {
				continue
			}

			if existing, ok := sessionMap[sessionID]; ok {
				existing.Checkpoints = append(existing.Checkpoints, Checkpoint{
					CheckpointID:     cp.CheckpointID,
					Message:          "Checkpoint: " + cp.CheckpointID,
					Timestamp:        cp.CreatedAt,
					IsTaskCheckpoint: cp.IsTask,
					ToolUseID:        cp.ToolUseID,
				})
			} else {
				// Get description from the checkpoint tree
				description := getDescriptionForCheckpoint(repo, cp.CheckpointID)

				sessionMap[sessionID] = &Session{
					ID:          sessionID,
					Description: description,
					Strategy:    "", // Will be set from metadata if available
					StartTime:   cp.CreatedAt,
					Checkpoints: []Checkpoint{{
						CheckpointID:     cp.CheckpointID,
						Message:          "Checkpoint: " + cp.CheckpointID,
						Timestamp:        cp.CreatedAt,
						IsTaskCheckpoint: cp.IsTask,
						ToolUseID:        cp.ToolUseID,
					}},
				}
			}
		}
	}

	// Check all registered strategies for additional sessions
	for _, name := range List() {
		strat, stratErr := Get(name)
		if stratErr != nil {
			continue
		}
		source, ok := strat.(SessionSource)
		if !ok {
			continue
		}
		additionalSessions, addErr := source.GetAdditionalSessions()
		if addErr != nil {
			continue // Skip strategies that fail to provide additional sessions
		}
		for _, addSession := range additionalSessions {
			if addSession == nil {
				continue
			}
			if existing, ok := sessionMap[addSession.ID]; ok {
				// Merge checkpoints - deduplicate by CheckpointID
				existingCPIDs := make(map[string]bool)
				for _, cp := range existing.Checkpoints {
					existingCPIDs[cp.CheckpointID] = true
				}
				for _, cp := range addSession.Checkpoints {
					if !existingCPIDs[cp.CheckpointID] {
						existing.Checkpoints = append(existing.Checkpoints, cp)
					}
				}
				// Update start time if additional session is older
				if addSession.StartTime.Before(existing.StartTime) {
					existing.StartTime = addSession.StartTime
				}
				// Use description from additional source if existing is empty
				if existing.Description == "" || existing.Description == NoDescription {
					existing.Description = addSession.Description
				}
			} else {
				// New session from additional source
				sessionMap[addSession.ID] = addSession
			}
		}
	}

	// Convert map to slice
	sessions := make([]Session, 0, len(sessionMap))
	for _, session := range sessionMap {
		// Sort checkpoints within each session by timestamp (most recent first)
		sort.Slice(session.Checkpoints, func(i, j int) bool {
			return session.Checkpoints[i].Timestamp.After(session.Checkpoints[j].Timestamp)
		})
		sessions = append(sessions, *session)
	}

	// Sort sessions by start time (most recent first)
	sort.Slice(sessions, func(i, j int) bool {
		return sessions[i].StartTime.After(sessions[j].StartTime)
	})

	return sessions, nil
}

// GetSession finds a session by ID (supports prefix matching).
// Returns ErrNoSession if no matching session is found.
func GetSession(sessionID string) (*Session, error) {
	sessions, err := ListSessions()
	if err != nil {
		return nil, err
	}
	return findSessionByID(sessions, sessionID)
}

// getDescriptionForCheckpoint reads the description for a checkpoint from the entire/sessions branch.
func getDescriptionForCheckpoint(repo *git.Repository, checkpointID string) string {
	tree, err := GetMetadataBranchTree(repo)
	if err != nil {
		return NoDescription
	}

	checkpointPath := trailers.CheckpointPath(checkpointID)
	return getSessionDescriptionFromTree(tree, checkpointPath)
}

// findSessionByID finds a session by exact ID or prefix match.
func findSessionByID(sessions []Session, sessionID string) (*Session, error) {
	for _, session := range sessions {
		if session.ID == sessionID || strings.HasPrefix(session.ID, sessionID) {
			return &session, nil
		}
	}
	return nil, ErrNoSession
}

package strategy

import (
	"context"
	"fmt"
	"log/slog"
	"regexp"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/checkpoint"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/session"

	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

const (
	// sessionGracePeriod is the minimum age a session must have before it can be
	// considered orphaned. This protects active sessions that haven't created
	// their first checkpoint yet.
	sessionGracePeriod = 10 * time.Minute

	// shadowBranchHashLength is the number of hex characters used in shadow branch names.
	// Shadow branches are named "entire/<hash[:7]>" using a 7-char prefix of the commit hash.
	shadowBranchHashLength = 7
)

// CleanupType identifies the type of orphaned item.
type CleanupType string

const (
	CleanupTypeShadowBranch CleanupType = "shadow-branch"
	CleanupTypeSessionState CleanupType = "session-state"
	CleanupTypeCheckpoint   CleanupType = "checkpoint"
)

// CleanupItem represents an orphaned item that can be cleaned up.
type CleanupItem struct {
	Type   CleanupType
	ID     string // Branch name, session ID, or checkpoint ID
	Reason string // Why this item is considered orphaned
}

// CleanupResult contains the results of a cleanup operation.
type CleanupResult struct {
	ShadowBranches    []string // Deleted shadow branches
	SessionStates     []string // Deleted session state files
	Checkpoints       []string // Deleted checkpoint metadata
	FailedBranches    []string // Shadow branches that failed to delete
	FailedStates      []string // Session states that failed to delete
	FailedCheckpoints []string // Checkpoints that failed to delete
}

// shadowBranchPattern matches shadow branch names: entire/<7+ hex chars>
// The pattern requires at least 7 hex characters after "entire/"
var shadowBranchPattern = regexp.MustCompile(`^entire/[0-9a-fA-F]{7,}$`)

// IsShadowBranch returns true if the branch name matches the shadow branch pattern.
// Shadow branches have the format "entire/<commit-hash>" where the commit hash
// is at least 7 hex characters. The "entire/sessions" branch is NOT a shadow branch.
func IsShadowBranch(branchName string) bool {
	// Explicitly exclude entire/sessions
	if branchName == "entire/sessions" {
		return false
	}
	return shadowBranchPattern.MatchString(branchName)
}

// ListShadowBranches returns all shadow branches in the repository.
// Shadow branches match the pattern "entire/<commit-hash>" (7+ hex chars).
// The "entire/sessions" branch is excluded as it stores permanent metadata.
// Returns an empty slice (not nil) if no shadow branches exist.
func ListShadowBranches() ([]string, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	refs, err := repo.References()
	if err != nil {
		return nil, fmt.Errorf("failed to get references: %w", err)
	}

	var shadowBranches []string

	err = refs.ForEach(func(ref *plumbing.Reference) error {
		// Only look at branch references
		if !ref.Name().IsBranch() {
			return nil
		}

		// Extract branch name without refs/heads/ prefix
		branchName := strings.TrimPrefix(ref.Name().String(), "refs/heads/")

		if IsShadowBranch(branchName) {
			shadowBranches = append(shadowBranches, branchName)
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to iterate references: %w", err)
	}

	// Ensure we return empty slice, not nil
	if shadowBranches == nil {
		shadowBranches = []string{}
	}

	return shadowBranches, nil
}

// DeleteShadowBranches deletes the specified branches from the repository.
// Returns two slices: successfully deleted branches and branches that failed to delete.
// Individual branch deletion failures do not stop the operation - all branches are attempted.
// Returns an error only if the repository cannot be opened.
func DeleteShadowBranches(branches []string) (deleted []string, failed []string, err error) {
	if len(branches) == 0 {
		return []string{}, []string{}, nil
	}

	repo, err := OpenRepository()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	for _, branch := range branches {
		refName := plumbing.NewBranchReferenceName(branch)

		// Check if reference exists before trying to delete
		ref, err := repo.Reference(refName, true)
		if err != nil {
			failed = append(failed, branch)
			continue
		}

		// Delete the reference
		if err := repo.Storer.RemoveReference(ref.Name()); err != nil {
			failed = append(failed, branch)
			continue
		}

		deleted = append(deleted, branch)
	}

	return deleted, failed, nil
}

// ListOrphanedSessionStates returns session state files that are orphaned.
// A session state is orphaned if:
//   - No checkpoints on entire/sessions reference this session ID
//   - No shadow branch exists for the session's base commit
//
// This is strategy-agnostic as session states are shared by all strategies.
func ListOrphanedSessionStates() ([]CleanupItem, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get all session states
	store, err := session.NewStateStore()
	if err != nil {
		return nil, fmt.Errorf("failed to create state store: %w", err)
	}

	states, err := store.List(context.Background())
	if err != nil {
		return nil, fmt.Errorf("failed to list session states: %w", err)
	}

	if len(states) == 0 {
		return []CleanupItem{}, nil
	}

	// Get all checkpoints to find which sessions have checkpoints
	cpStore := checkpoint.NewGitStore(repo)

	sessionsWithCheckpoints := make(map[string]bool)
	checkpoints, listErr := cpStore.ListCommitted(context.Background())
	if listErr == nil {
		for _, cp := range checkpoints {
			sessionsWithCheckpoints[cp.SessionID] = true
		}
	}

	// Get all shadow branches
	shadowBranches, _ := ListShadowBranches() //nolint:errcheck // Best effort
	shadowBranchSet := make(map[string]bool)
	for _, branch := range shadowBranches {
		// Extract commit hash from branch name (entire/<hash>)
		if strings.HasPrefix(branch, "entire/") {
			hash := strings.TrimPrefix(branch, "entire/")
			shadowBranchSet[hash] = true
		}
	}

	var orphaned []CleanupItem
	now := time.Now()

	for _, state := range states {
		// Skip sessions that started recently - they may be actively in use
		// but haven't created their first checkpoint yet
		if now.Sub(state.StartedAt) < sessionGracePeriod {
			continue
		}

		// Check if session has checkpoints on entire/sessions
		hasCheckpoints := sessionsWithCheckpoints[state.SessionID]

		// Check if shadow branch exists for base commit
		// Shadow branches use 7-char hash prefixes, so we need to match by prefix
		hasShadowBranch := false
		if len(state.BaseCommit) >= shadowBranchHashLength {
			hasShadowBranch = shadowBranchSet[state.BaseCommit[:shadowBranchHashLength]]
		}

		// Session is orphaned if it has no checkpoints AND no shadow branch
		if !hasCheckpoints && !hasShadowBranch {
			reason := "no checkpoints or shadow branch found"
			orphaned = append(orphaned, CleanupItem{
				Type:   CleanupTypeSessionState,
				ID:     state.SessionID,
				Reason: reason,
			})
		}
	}

	return orphaned, nil
}

// DeleteOrphanedSessionStates deletes the specified session state files.
func DeleteOrphanedSessionStates(sessionIDs []string) (deleted []string, failed []string, err error) {
	if len(sessionIDs) == 0 {
		return []string{}, []string{}, nil
	}

	store, err := session.NewStateStore()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to create state store: %w", err)
	}

	for _, sessionID := range sessionIDs {
		if err := store.Clear(context.Background(), sessionID); err != nil {
			failed = append(failed, sessionID)
		} else {
			deleted = append(deleted, sessionID)
		}
	}

	return deleted, failed, nil
}

// DeleteOrphanedCheckpoints removes checkpoint directories from the entire/sessions branch.
func DeleteOrphanedCheckpoints(checkpointIDs []string) (deleted []string, failed []string, err error) {
	if len(checkpointIDs) == 0 {
		return []string{}, []string{}, nil
	}

	repo, err := OpenRepository()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get sessions branch
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		return nil, nil, fmt.Errorf("sessions branch not found: %w", err)
	}

	parentCommit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get commit: %w", err)
	}

	baseTree, err := parentCommit.Tree()
	if err != nil {
		return nil, nil, fmt.Errorf("failed to get tree: %w", err)
	}

	// Flatten tree to entries
	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(repo, baseTree, "", entries); err != nil {
		return nil, nil, fmt.Errorf("failed to flatten tree: %w", err)
	}

	// Remove entries for each checkpoint
	checkpointSet := make(map[string]bool)
	for _, id := range checkpointIDs {
		checkpointSet[id] = true
	}

	// Find and remove entries matching checkpoint paths
	for path := range entries {
		for checkpointID := range checkpointSet {
			cpPath := trailers.CheckpointPath(checkpointID)
			if strings.HasPrefix(path, cpPath+"/") {
				delete(entries, path)
			}
		}
	}

	// Build new tree
	newTreeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to build tree: %w", err)
	}

	// Create commit
	commit := &object.Commit{
		Author: object.Signature{
			Name:  "Entire CLI",
			Email: "cli@entire.io",
			When:  parentCommit.Author.When,
		},
		Committer: object.Signature{
			Name:  "Entire CLI",
			Email: "cli@entire.io",
			When:  parentCommit.Committer.When,
		},
		Message:      fmt.Sprintf("Cleanup: removed %d orphaned checkpoints", len(checkpointIDs)),
		TreeHash:     newTreeHash,
		ParentHashes: []plumbing.Hash{ref.Hash()},
	}

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return nil, nil, fmt.Errorf("failed to encode commit: %w", err)
	}

	commitHash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return nil, nil, fmt.Errorf("failed to store commit: %w", err)
	}

	// Update branch reference
	newRef := plumbing.NewHashReference(refName, commitHash)
	if err := repo.Storer.SetReference(newRef); err != nil {
		return nil, nil, fmt.Errorf("failed to update branch: %w", err)
	}

	// All checkpoints deleted successfully
	return checkpointIDs, []string{}, nil
}

// ListAllCleanupItems returns all orphaned items across all categories.
// It iterates over all registered strategies and calls ListOrphanedItems on those
// that implement OrphanedItemsLister.
// Returns an error if the repository cannot be opened.
func ListAllCleanupItems() ([]CleanupItem, error) {
	var items []CleanupItem
	var firstErr error

	// Iterate over all registered strategies
	for _, name := range List() {
		// Skip legacy names to avoid duplicates
		if IsLegacyStrategyName(name) {
			continue
		}

		strat, err := Get(name)
		if err != nil {
			if firstErr == nil {
				firstErr = err
			}
			continue
		}

		// Check if strategy implements OrphanedItemsLister
		if lister, ok := strat.(OrphanedItemsLister); ok {
			stratItems, err := lister.ListOrphanedItems()
			if err != nil {
				if firstErr == nil {
					firstErr = err
				}
				continue
			}
			items = append(items, stratItems...)
		}
	}

	// Orphaned session states (strategy-agnostic)
	states, err := ListOrphanedSessionStates()
	if err != nil {
		if firstErr == nil {
			firstErr = err
		}
	} else {
		items = append(items, states...)
	}

	return items, firstErr
}

// DeleteAllCleanupItems deletes all specified cleanup items.
// Logs each deletion for audit purposes.
func DeleteAllCleanupItems(items []CleanupItem) (*CleanupResult, error) {
	result := &CleanupResult{}
	logCtx := logging.WithComponent(context.Background(), "cleanup")

	// Build ID-to-Reason map for logging after deletion
	reasonMap := make(map[string]string)
	for _, item := range items {
		reasonMap[item.ID] = item.Reason
	}

	// Group items by type
	var branches, states, checkpoints []string
	for _, item := range items {
		switch item.Type {
		case CleanupTypeShadowBranch:
			branches = append(branches, item.ID)
		case CleanupTypeSessionState:
			states = append(states, item.ID)
		case CleanupTypeCheckpoint:
			checkpoints = append(checkpoints, item.ID)
		}
	}

	// Delete shadow branches
	if len(branches) > 0 {
		deleted, failed, err := DeleteShadowBranches(branches)
		if err != nil {
			return result, err
		}
		result.ShadowBranches = deleted
		result.FailedBranches = failed

		// Log deleted branches
		for _, id := range deleted {
			logging.Info(logCtx, "deleted orphaned shadow branch",
				slog.String("type", string(CleanupTypeShadowBranch)),
				slog.String("id", id),
				slog.String("reason", reasonMap[id]),
			)
		}
		// Log failed branches
		for _, id := range failed {
			logging.Warn(logCtx, "failed to delete orphaned shadow branch",
				slog.String("type", string(CleanupTypeShadowBranch)),
				slog.String("id", id),
				slog.String("reason", reasonMap[id]),
			)
		}
	}

	// Delete session states
	if len(states) > 0 {
		deleted, failed, err := DeleteOrphanedSessionStates(states)
		if err != nil {
			return result, err
		}
		result.SessionStates = deleted
		result.FailedStates = failed

		// Log deleted session states
		for _, id := range deleted {
			logging.Info(logCtx, "deleted orphaned session state",
				slog.String("type", string(CleanupTypeSessionState)),
				slog.String("id", id),
				slog.String("reason", reasonMap[id]),
			)
		}
		// Log failed session states
		for _, id := range failed {
			logging.Warn(logCtx, "failed to delete orphaned session state",
				slog.String("type", string(CleanupTypeSessionState)),
				slog.String("id", id),
				slog.String("reason", reasonMap[id]),
			)
		}
	}

	// Delete checkpoints
	if len(checkpoints) > 0 {
		deleted, failed, err := DeleteOrphanedCheckpoints(checkpoints)
		if err != nil {
			return result, err
		}
		result.Checkpoints = deleted
		result.FailedCheckpoints = failed

		// Log deleted checkpoints
		for _, id := range deleted {
			logging.Info(logCtx, "deleted orphaned checkpoint",
				slog.String("type", string(CleanupTypeCheckpoint)),
				slog.String("id", id),
				slog.String("reason", reasonMap[id]),
			)
		}
		// Log failed checkpoints
		for _, id := range failed {
			logging.Warn(logCtx, "failed to delete orphaned checkpoint",
				slog.String("type", string(CleanupTypeCheckpoint)),
				slog.String("id", id),
				slog.String("reason", reasonMap[id]),
			)
		}
	}

	// Log summary
	totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints)
	totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints)
	if totalDeleted > 0 || totalFailed > 0 {
		logging.Info(logCtx, "cleanup completed",
			slog.Int("deleted_branches", len(result.ShadowBranches)),
			slog.Int("deleted_session_states", len(result.SessionStates)),
			slog.Int("deleted_checkpoints", len(result.Checkpoints)),
			slog.Int("failed_branches", len(result.FailedBranches)),
			slog.Int("failed_session_states", len(result.FailedStates)),
			slog.Int("failed_checkpoints", len(result.FailedCheckpoints)),
		)
	}

	return result, nil
}

package strategy

import (
	"bufio"
	"context"
	"fmt"
	"log/slog"
	"os"
	"strings"

	"entire.io/cli/cmd/entire/cli/agent"
	"entire.io/cli/cmd/entire/cli/checkpoint/id"
	"entire.io/cli/cmd/entire/cli/logging"
	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/stringutil"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
)

// askConfirmTTY prompts the user for a yes/no confirmation via /dev/tty.
// This works even when stdin is redirected (e.g., git commit -m).
// Returns true for yes, false for no. If TTY is unavailable, returns the default.
// If context is non-empty, it is displayed on a separate line before the prompt.
func askConfirmTTY(prompt string, context string, defaultYes bool) bool {
	// Open /dev/tty for both reading and writing
	// This is the controlling terminal, which works even when stdin/stderr are redirected
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		// Can't open TTY (e.g., running in CI), use default
		return defaultYes
	}
	defer tty.Close()

	// Show context if provided
	if context != "" {
		fmt.Fprintf(tty, "%s\n", context)
	}

	// Show prompt with default indicator
	// Write to tty directly, not stderr, since git hooks may redirect stderr to /dev/null
	var hint string
	if defaultYes {
		hint = "[Y/n]"
	} else {
		hint = "[y/N]"
	}
	fmt.Fprintf(tty, "%s %s ", prompt, hint)

	// Read response
	reader := bufio.NewReader(tty)
	response, err := reader.ReadString('\n')
	if err != nil {
		return defaultYes
	}

	response = strings.TrimSpace(strings.ToLower(response))
	switch response {
	case "y", "yes":
		return true
	case "n", "no":
		return false
	default:
		// Empty or invalid input - use default
		return defaultYes
	}
}

// CommitMsg is called by the git commit-msg hook after the user edits the message.
// If the message contains only our trailer (no actual user content), strip it
// so git will abort the commit due to empty message.
//
//nolint:unparam // error return required by interface but hooks must return nil
func (s *ManualCommitStrategy) CommitMsg(commitMsgFile string) error {
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // Path comes from git hook
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	message := string(content)

	// Check if our trailer is present
	cpID, found := trailers.ParseCheckpoint(message)
	if !found || cpID.IsEmpty() {
		// No trailer, nothing to do
		return nil
	}
	_ = cpID // Used only to verify trailer presence

	// Check if there's any user content (non-comment, non-trailer lines)
	if !hasUserContent(message) {
		// No user content - strip the trailer so git aborts
		message = stripCheckpointTrailer(message)
		if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil {
			return nil //nolint:nilerr // Hook must be silent on failure
		}
	}

	return nil
}

// hasUserContent checks if the message has any content besides comments and our trailer.
func hasUserContent(message string) bool {
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	for _, line := range strings.Split(message, "\n") {
		trimmed := strings.TrimSpace(line)
		// Skip empty lines
		if trimmed == "" {
			continue
		}
		// Skip comment lines
		if strings.HasPrefix(trimmed, "#") {
			continue
		}
		// Skip our trailer line
		if strings.HasPrefix(trimmed, trailerPrefix) {
			continue
		}
		// Found user content
		return true
	}
	return false
}

// stripCheckpointTrailer removes the Entire-Checkpoint trailer line from the message.
func stripCheckpointTrailer(message string) string {
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	var result []string
	for _, line := range strings.Split(message, "\n") {
		if !strings.HasPrefix(strings.TrimSpace(line), trailerPrefix) {
			result = append(result, line)
		}
	}
	return strings.Join(result, "\n")
}

// PrepareCommitMsg is called by the git prepare-commit-msg hook.
// Adds an Entire-Checkpoint trailer to the commit message with a stable checkpoint ID.
// Only adds a trailer if there's actually new session content to condense.
// The actual condensation happens in PostCommit - if the user removes the trailer,
// the commit will not be linked to the session (useful for "manual" commits).
// For amended commits, preserves the existing checkpoint ID.
//
// The source parameter indicates how the commit was initiated:
//   - "" or "template": normal editor flow - adds trailer with explanatory comment
//   - "message": using -m or -F flag - prompts user interactively via /dev/tty
//   - "merge", "squash", "commit": skip trailer entirely (auto-generated or amend commits)
//
//nolint:unparam // error return required by interface but hooks must return nil
func (s *ManualCommitStrategy) PrepareCommitMsg(commitMsgFile string, source string) error {
	logCtx := logging.WithComponent(context.Background(), "checkpoint")

	// Skip for merge, squash, and commit (amend) sources
	// These are auto-generated or reusing existing messages - not from Claude sessions
	switch source {
	case "merge", "squash", "commit":
		logging.Debug(logCtx, "prepare-commit-msg: skipped for source",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil
	}
	repo, err := OpenRepository()
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	worktreePath, err := GetWorktreePath()
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Find all active sessions for this worktree
	// We match by worktree (not BaseCommit) because the user may have made
	// intermediate commits without entering new prompts, causing HEAD to diverge
	sessions, err := s.findSessionsForWorktree(worktreePath)
	if err != nil || len(sessions) == 0 {
		// No active sessions or error listing - silently skip (hooks must be resilient)
		logging.Debug(logCtx, "prepare-commit-msg: no active sessions",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
		)
		return nil //nolint:nilerr // Intentional: hooks must be silent on failure
	}

	// Check if any session has new content to condense
	sessionsWithContent := s.filterSessionsWithNewContent(repo, sessions)

	// Determine which checkpoint ID to use
	var checkpointID string
	var hasNewContent bool
	var reusedSession *SessionState

	if len(sessionsWithContent) > 0 {
		// New content exists - will generate new checkpoint ID below
		hasNewContent = true
	} else {
		// No new content - check if any session has a LastCheckpointID to reuse
		// This handles the case where user splits Claude's work across multiple commits
		// Reuse if: LastCheckpointID exists AND (FilesTouched is empty OR files overlap)
		// - FilesTouched empty: commits made before session stop, reuse checkpoint
		// - FilesTouched populated: only reuse if files overlap (prevents unrelated commits from reusing)

		// Get current HEAD to filter sessions
		head, err := repo.Head()
		if err != nil {
			return nil //nolint:nilerr // Hook must be silent on failure
		}
		currentHeadHash := head.Hash().String()

		// Filter to sessions where BaseCommit matches current HEAD
		// This prevents reusing checkpoint IDs from old sessions
		// Note: BaseCommit is kept current both when new content is condensed (in the
		// condensation process) and when no new content is found (via PostCommit when
		// reusing checkpoint IDs). If none match, we don't add a trailer rather than
		// falling back to old sessions which could have stale checkpoint IDs.
		var currentSessions []*SessionState
		for _, session := range sessions {
			if session.BaseCommit == currentHeadHash {
				currentSessions = append(currentSessions, session)
			}
		}

		if len(currentSessions) == 0 {
			// No sessions match current HEAD - don't try to reuse checkpoint IDs
			// from old sessions as they may be stale
			logging.Debug(logCtx, "prepare-commit-msg: no sessions match current HEAD",
				slog.String("strategy", "manual-commit"),
				slog.String("source", source),
				slog.String("current_head", currentHeadHash[:7]),
				slog.Int("total_sessions", len(sessions)),
			)
			return nil
		}

		stagedFiles := getStagedFiles(repo)
		for _, session := range currentSessions {
			if session.LastCheckpointID != "" &&
				(len(session.FilesTouched) == 0 || hasOverlappingFiles(stagedFiles, session.FilesTouched)) {
				checkpointID = session.LastCheckpointID
				reusedSession = session
				break
			}
		}
		if checkpointID == "" {
			// No new content and no previous checkpoint to reference (or staged files are unrelated)
			logging.Debug(logCtx, "prepare-commit-msg: no content to link",
				slog.String("strategy", "manual-commit"),
				slog.String("source", source),
				slog.Int("sessions_found", len(sessions)),
				slog.Int("sessions_with_content", len(sessionsWithContent)),
			)
			return nil
		}
	}

	// Read current commit message
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // commitMsgFile is provided by git hook
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	message := string(content)

	// Get or generate checkpoint ID
	existingCpID, found := trailers.ParseCheckpoint(message)
	if found && !existingCpID.IsEmpty() {
		// Trailer already exists (e.g., amend) - keep it
		logging.Debug(logCtx, "prepare-commit-msg: trailer already exists",
			slog.String("strategy", "manual-commit"),
			slog.String("source", source),
			slog.String("existing_checkpoint_id", existingCpID.String()),
		)
		return nil
	}

	if hasNewContent {
		// New content: generate new checkpoint ID
		checkpointID = trailers.GenerateCheckpointID().String()
	}
	// Otherwise checkpointID is already set to LastCheckpointID from above

	// Determine agent name and last prompt from session
	agentName := DefaultAgentType // default for backward compatibility
	var lastPrompt string
	if hasNewContent && len(sessionsWithContent) > 0 {
		session := sessionsWithContent[0]
		if session.AgentType != "" {
			agentName = session.AgentType
		}
		lastPrompt = s.getLastPrompt(repo, session)
	} else if reusedSession != nil {
		// Reusing checkpoint from existing session - get agent type and prompt from that session
		if reusedSession.AgentType != "" {
			agentName = reusedSession.AgentType
		}
		lastPrompt = s.getLastPrompt(repo, reusedSession)
	}

	// Prepare prompt for display: collapse newlines/whitespace, then truncate (rune-safe)
	displayPrompt := stringutil.TruncateRunes(stringutil.CollapseWhitespace(lastPrompt), 80, "...")

	// Add trailer differently based on commit source
	if source == "message" {
		// Using -m or -F: ask user interactively whether to add trailer
		// (comments won't be stripped by git in this mode)

		// Build context string for interactive prompt
		var promptContext string
		if displayPrompt != "" {
			promptContext = "You have an active " + agentName + " session.\nLast Prompt: " + displayPrompt
		}

		if !askConfirmTTY("Link this commit to "+agentName+" session context?", promptContext, true) {
			// User declined - don't add trailer
			logging.Debug(logCtx, "prepare-commit-msg: user declined trailer",
				slog.String("strategy", "manual-commit"),
				slog.String("source", source),
			)
			return nil
		}
		message = addCheckpointTrailer(message, checkpointID)
	} else {
		// Normal editor flow: add trailer with explanatory comment (will be stripped by git)
		message = addCheckpointTrailerWithComment(message, checkpointID, agentName, displayPrompt)
	}

	logging.Info(logCtx, "prepare-commit-msg: trailer added",
		slog.String("strategy", "manual-commit"),
		slog.String("source", source),
		slog.String("checkpoint_id", checkpointID),
		slog.Bool("has_new_content", hasNewContent),
	)

	// Write updated message back
	if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	return nil
}

// PostCommit is called by the git post-commit hook after a commit is created.
// Checks if the commit has an Entire-Checkpoint trailer and if so, condenses
// session data from shadow branches to entire/sessions.
// If the user removed the trailer during commit message editing, this is treated
// as a "manual" commit and no condensation happens.
//
//nolint:unparam // error return required by interface but hooks must return nil
func (s *ManualCommitStrategy) PostCommit() error {
	logCtx := logging.WithComponent(context.Background(), "checkpoint")

	repo, err := OpenRepository()
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Get HEAD commit to check for trailer
	head, err := repo.Head()
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Check if commit has checkpoint trailer
	cpID, found := trailers.ParseCheckpoint(commit.Message)
	if !found || cpID.IsEmpty() {
		// No trailer - user removed it, treat as manual commit
		logging.Debug(logCtx, "post-commit: no checkpoint trailer",
			slog.String("strategy", "manual-commit"),
		)
		return nil
	}
	checkpointID := cpID.String()

	worktreePath, err := GetWorktreePath()
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Find all active sessions for this worktree
	sessions, err := s.findSessionsForWorktree(worktreePath)
	if err != nil || len(sessions) == 0 {
		logging.Warn(logCtx, "post-commit: no active sessions despite trailer",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", checkpointID),
		)
		return nil //nolint:nilerr // Intentional: hooks must be silent on failure
	}

	// Filter to sessions with new content
	sessionsWithContent := s.filterSessionsWithNewContent(repo, sessions)
	if len(sessionsWithContent) == 0 {
		logging.Debug(logCtx, "post-commit: no new content to condense",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", checkpointID),
			slog.Int("sessions_found", len(sessions)),
		)
		// Still update BaseCommit for all sessions in this worktree
		// This prevents stale BaseCommit when commits happen without condensation
		// (e.g., when reusing a previous checkpoint ID for split commits)
		newHead := head.Hash().String()
		for _, state := range sessions {
			if state.BaseCommit != newHead {
				state.BaseCommit = newHead
				if err := s.saveSessionState(state); err != nil {
					logging.Warn(logCtx, "post-commit: failed to update session BaseCommit",
						slog.String("session_id", state.SessionID),
						slog.String("error", err.Error()),
					)
				}
			}
		}
		return nil
	}

	// Track shadow branches to clean up after successful condensation
	shadowBranchesToDelete := make(map[string]struct{})

	// Condense sessions that have new content
	for _, state := range sessionsWithContent {
		result, err := s.CondenseSession(repo, checkpointID, state)
		if err != nil {
			fmt.Fprintf(os.Stderr, "[entire] Warning: condensation failed for session %s: %v\n",
				state.SessionID, err)
			continue
		}

		// Track this shadow branch for cleanup
		shadowBranchesToDelete[state.BaseCommit] = struct{}{}

		// Update session state for the new base commit
		// After condensation, the session continues from the NEW commit (HEAD), so we:
		// 1. Update BaseCommit to new HEAD - session now tracks from new commit
		// 2. Reset CheckpointCount to 0 - no checkpoints exist on new shadow branch yet
		// 3. Update CondensedTranscriptLines - track transcript offset for incremental context
		//
		// This is critical: if we don't update BaseCommit, listAllSessionStates will try
		// to find shadow branch for old commit (which gets deleted), and since CheckpointCount > 0,
		// it will clean up (delete) the session state file. By updating to new HEAD with
		// CheckpointCount = 0, the session is preserved even without a shadow branch.
		state.BaseCommit = head.Hash().String()
		state.CheckpointCount = 0
		state.CondensedTranscriptLines = result.TotalTranscriptLines

		// Save checkpoint ID so subsequent commits without new content can reuse it
		state.LastCheckpointID = checkpointID

		if err := s.saveSessionState(state); err != nil {
			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to update session state: %v\n", err)
		}

		shortID := state.SessionID
		if len(shortID) > 8 {
			shortID = shortID[:8]
		}
		fmt.Fprintf(os.Stderr, "[entire] Condensed session %s: %s (%d checkpoints)\n",
			shortID, result.CheckpointID, result.CheckpointsCount)

		// Log condensation
		logCtx := logging.WithComponent(context.Background(), "checkpoint")
		logging.Info(logCtx, "session condensed",
			slog.String("strategy", "manual-commit"),
			slog.String("checkpoint_id", result.CheckpointID),
			slog.Int("checkpoints_condensed", result.CheckpointsCount),
			slog.Int("transcript_lines", result.TotalTranscriptLines),
		)
	}

	// Clean up shadow branches after successful condensation
	// Data is now preserved on entire/sessions, so shadow branches are no longer needed
	for baseCommit := range shadowBranchesToDelete {
		shadowBranchName := getShadowBranchNameForCommit(baseCommit)
		if err := deleteShadowBranch(repo, shadowBranchName); err != nil {
			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to clean up %s: %v\n", shadowBranchName, err)
		} else {
			fmt.Fprintf(os.Stderr, "[entire] Cleaned up shadow branch: %s\n", shadowBranchName)

			// Log branch cleanup
			logCtx := logging.WithComponent(context.Background(), "checkpoint")
			logging.Info(logCtx, "shadow branch deleted",
				slog.String("strategy", "manual-commit"),
				slog.String("shadow_branch", shadowBranchName),
			)
		}
	}

	return nil
}

// filterSessionsWithNewContent returns sessions that have new transcript content
// beyond what was already condensed.
func (s *ManualCommitStrategy) filterSessionsWithNewContent(repo *git.Repository, sessions []*SessionState) []*SessionState {
	var result []*SessionState

	for _, state := range sessions {
		hasNew, err := s.sessionHasNewContent(repo, state)
		if err != nil {
			// On error, include the session (fail open for hooks)
			result = append(result, state)
			continue
		}
		if hasNew {
			result = append(result, state)
		}
	}

	return result
}

// sessionHasNewContent checks if a session has new transcript content
// beyond what was already condensed.
func (s *ManualCommitStrategy) sessionHasNewContent(repo *git.Repository, state *SessionState) (bool, error) {
	// Get shadow branch
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		// No shadow branch means no Stop has happened since the last condensation.
		// However, the agent may have done work (including commits) without a Stop.
		// Check the live transcript to detect this scenario.
		return s.sessionHasNewContentFromLiveTranscript(repo, state)
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return false, fmt.Errorf("failed to get commit object: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return false, fmt.Errorf("failed to get commit tree: %w", err)
	}

	// Look for transcript file
	metadataDir := paths.EntireMetadataDir + "/" + state.SessionID
	var transcriptLines int

	if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			transcriptLines = countTranscriptLines(content)
		}
	} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			transcriptLines = countTranscriptLines(content)
		}
	}

	// Has new content if there are more lines than already condensed
	return transcriptLines > state.CondensedTranscriptLines, nil
}

// countTranscriptLines counts lines in a transcript, matching the counting method used
// in extractSessionData for consistency. This trims trailing empty lines (from final \n
// in JSONL) but includes empty lines in the middle of the file.
func countTranscriptLines(content string) int {
	lines := strings.Split(content, "\n")
	// Trim trailing empty lines (from final \n in JSONL)
	for len(lines) > 0 && strings.TrimSpace(lines[len(lines)-1]) == "" {
		lines = lines[:len(lines)-1]
	}
	return len(lines)
}

// sessionHasNewContentFromLiveTranscript checks if a session has new content
// by examining the live transcript file. This is used when no shadow branch exists
// (i.e., no Stop has happened yet) but the agent may have done work.
//
// Returns true if:
//  1. The transcript has grown since the last condensation, AND
//  2. The new transcript portion contains file modifications, AND
//  3. At least one modified file overlaps with the currently staged files
//
// The overlap check ensures we don't add checkpoint trailers to commits that are
// unrelated to the agent's recent changes.
//
// This handles the scenario where the agent commits mid-session before Stop.
func (s *ManualCommitStrategy) sessionHasNewContentFromLiveTranscript(repo *git.Repository, state *SessionState) (bool, error) {
	// Need both transcript path and agent type to analyze
	if state.TranscriptPath == "" || state.AgentType == "" {
		return false, nil
	}

	// Get the agent for transcript analysis
	ag, err := agent.GetByAgentType(state.AgentType)
	if err != nil {
		return false, nil //nolint:nilerr // Unknown agent type, fail gracefully
	}

	// Cast to TranscriptAnalyzer
	analyzer, ok := ag.(agent.TranscriptAnalyzer)
	if !ok {
		return false, nil // Agent doesn't support transcript analysis
	}

	// Get current transcript position
	currentPos, err := analyzer.GetTranscriptPosition(state.TranscriptPath)
	if err != nil {
		return false, nil //nolint:nilerr // Error reading transcript, fail gracefully
	}

	// Check if transcript has grown since last condensation
	if currentPos <= state.CondensedTranscriptLines {
		return false, nil // No new content
	}

	// Transcript has grown - check if there are file modifications in the new portion
	modifiedFiles, _, err := analyzer.ExtractModifiedFilesFromOffset(state.TranscriptPath, state.CondensedTranscriptLines)
	if err != nil {
		return false, nil //nolint:nilerr // Error parsing transcript, fail gracefully
	}

	// No file modifications means no new content to checkpoint
	if len(modifiedFiles) == 0 {
		return false, nil
	}

	// Check if any modified files overlap with currently staged files
	// This ensures we only add checkpoint trailers to commits that include
	// files the agent actually modified
	stagedFiles := getStagedFiles(repo)
	if !hasOverlappingFiles(stagedFiles, modifiedFiles) {
		return false, nil // No overlap - staged files are unrelated to agent's work
	}

	return true, nil
}

// addCheckpointTrailer adds the Entire-Checkpoint trailer to a commit message.
// Handles proper trailer formatting (blank line before trailers if needed).
func addCheckpointTrailer(message, checkpointID string) string {
	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID

	// If message already ends with trailers (lines starting with key:), just append
	// Otherwise, add a blank line first
	lines := strings.Split(strings.TrimRight(message, "\n"), "\n")

	// Check if last non-empty, non-comment line looks like a trailer
	// Git comment lines start with # and may contain ": " (e.g., "# Changes to be committed:")
	hasTrailers := false
	for i := len(lines) - 1; i >= 0; i-- {
		line := strings.TrimSpace(lines[i])
		if line == "" {
			break
		}
		// Skip git comment lines
		if strings.HasPrefix(line, "#") {
			continue
		}
		if strings.Contains(line, ": ") {
			hasTrailers = true
			break
		}
		// Non-comment, non-trailer line found - no existing trailers
		break
	}

	if hasTrailers {
		// Append trailer directly
		return strings.TrimRight(message, "\n") + "\n" + trailer + "\n"
	}

	// Add blank line before trailer
	return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n"
}

// addCheckpointTrailerWithComment adds the Entire-Checkpoint trailer with an explanatory comment.
// The trailer is placed above the git comment block but below the user's message area,
// with a comment explaining that the user can remove it if they don't want to link the commit
// to the agent session. If prompt is non-empty, it's shown as context.
func addCheckpointTrailerWithComment(message, checkpointID, agentName, prompt string) string {
	trailer := trailers.CheckpointTrailerKey + ": " + checkpointID
	commentLines := []string{
		"# Remove the Entire-Checkpoint trailer above if you don't want to link this commit to " + agentName + " session context.",
	}
	if prompt != "" {
		commentLines = append(commentLines, "# Last Prompt: "+prompt)
	}
	commentLines = append(commentLines, "# The trailer will be added to your next commit based on this branch.")
	comment := strings.Join(commentLines, "\n")

	lines := strings.Split(message, "\n")

	// Find where the git comment block starts (first # line)
	commentStart := -1
	for i, line := range lines {
		if strings.HasPrefix(line, "#") {
			commentStart = i
			break
		}
	}

	if commentStart == -1 {
		// No git comments, append trailer at the end
		return strings.TrimRight(message, "\n") + "\n\n" + trailer + "\n" + comment + "\n"
	}

	// Split into user content and git comments
	userContent := strings.Join(lines[:commentStart], "\n")
	gitComments := strings.Join(lines[commentStart:], "\n")

	// Build result: user content, blank line, trailer, comment, blank line, git comments
	userContent = strings.TrimRight(userContent, "\n")
	if userContent == "" {
		// No user content yet - leave space for them to type, then trailer
		// Two newlines: first for user's message line, second for blank separator
		return "\n\n" + trailer + "\n" + comment + "\n\n" + gitComments
	}
	return userContent + "\n\n" + trailer + "\n" + comment + "\n\n" + gitComments
}

// InitializeSession creates session state for a new session or updates an existing one.
// This implements the optional SessionInitializer interface.
// Called during UserPromptSubmit to allow git hooks to detect active sessions.
//
// If the session already exists and HEAD has moved (e.g., user committed), updates
// BaseCommit to the new HEAD so future checkpoints go to the correct shadow branch.
//
// If there's an existing shadow branch with activity from a different worktree,
// returns a ShadowBranchConflictError to allow the caller to inform the user.
//
// agentType is the human-readable name of the agent (e.g., "Claude Code").
// transcriptPath is the path to the live transcript file (for mid-session commit detection).
func (s *ManualCommitStrategy) InitializeSession(sessionID string, agentType string, transcriptPath string) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get current HEAD
	head, err := repo.Head()
	if err != nil {
		return fmt.Errorf("failed to get HEAD: %w", err)
	}

	// Check if session already exists
	state, err := s.loadSessionState(sessionID)
	if err != nil {
		return fmt.Errorf("failed to check session state: %w", err)
	}

	// Check for shadow branch conflict before proceeding
	// This must happen even if session state exists but has no checkpoints yet
	// (e.g., state was created by concurrent warning but conflict later resolved)
	baseCommitHash := head.Hash().String()
	if state == nil || state.CheckpointCount == 0 {
		shadowBranch := getShadowBranchNameForCommit(baseCommitHash)
		refName := plumbing.NewBranchReferenceName(shadowBranch)

		ref, refErr := repo.Reference(refName, true)
		if refErr == nil {
			// Shadow branch exists - check if it has commits from a different session
			tipCommit, commitErr := repo.CommitObject(ref.Hash())
			if commitErr == nil {
				existingSessionID, found := trailers.ParseSession(tipCommit.Message)
				if found && existingSessionID != sessionID {
					// Check if the existing session has a state file
					// existingSessionID is the full Entire session ID (YYYY-MM-DD-uuid) from the trailer
					// We intentionally ignore load errors - treat them as "no state" (orphaned branch)
					existingState, _ := s.loadSessionState(existingSessionID) //nolint:errcheck // error means no state
					if existingState == nil {
						// Orphaned shadow branch - no state file for the existing session
						// Reset the branch so the new session can proceed
						fmt.Fprintf(os.Stderr, "Resetting orphaned shadow branch '%s' (previous session %s has no state)\n",
							shadowBranch, existingSessionID)
						if err := deleteShadowBranch(repo, shadowBranch); err != nil {
							return fmt.Errorf("failed to reset orphaned shadow branch: %w", err)
						}
					} else {
						// Existing session has state - this is a real conflict
						// (e.g., different worktree at same commit)
						return &SessionIDConflictError{
							ExistingSession: existingSessionID,
							NewSession:      sessionID,
							ShadowBranch:    shadowBranch,
						}
					}
				}
			}
		}
	}

	if state != nil && state.BaseCommit != "" {
		// Session is fully initialized
		needSave := false

		// Backfill AgentType if empty (for sessions created before the agent_type field was added)
		if state.AgentType == "" && agentType != "" {
			state.AgentType = agentType
			needSave = true
		}

		// Update transcript path if provided (may change on session resume)
		if transcriptPath != "" && state.TranscriptPath != transcriptPath {
			state.TranscriptPath = transcriptPath
			needSave = true
		}

		// Clear LastCheckpointID on every new prompt
		// This is set during PostCommit when a checkpoint is created, and should be
		// cleared when the user enters a new prompt (starting fresh work)
		if state.LastCheckpointID != "" {
			state.LastCheckpointID = ""
			needSave = true
		}

		// Check if HEAD has moved (user pulled/rebased or committed)
		if state.BaseCommit != head.Hash().String() {
			oldBaseCommit := state.BaseCommit
			newBaseCommit := head.Hash().String()

			// Check if old shadow branch exists - if so, user did NOT commit (would have been deleted)
			// This happens when user does: stash → pull → stash apply, or rebase, etc.
			oldShadowBranch := getShadowBranchNameForCommit(oldBaseCommit)
			oldRefName := plumbing.NewBranchReferenceName(oldShadowBranch)
			if oldRef, err := repo.Reference(oldRefName, true); err == nil {
				// Old shadow branch exists - move it to new base commit
				newShadowBranch := getShadowBranchNameForCommit(newBaseCommit)
				newRefName := plumbing.NewBranchReferenceName(newShadowBranch)

				// Create new reference pointing to same commit
				newRef := plumbing.NewHashReference(newRefName, oldRef.Hash())
				if err := repo.Storer.SetReference(newRef); err != nil {
					return fmt.Errorf("failed to create new shadow branch %s: %w", newShadowBranch, err)
				}

				// Delete old reference
				if err := repo.Storer.RemoveReference(oldRefName); err != nil {
					// Non-fatal: log but continue
					fmt.Fprintf(os.Stderr, "Warning: failed to remove old shadow branch %s: %v\n", oldShadowBranch, err)
				}

				fmt.Fprintf(os.Stderr, "Moved shadow branch from %s to %s (base commit changed after pull/rebase)\n",
					oldShadowBranch, newShadowBranch)
			}

			state.BaseCommit = newBaseCommit
			needSave = true
			fmt.Fprintf(os.Stderr, "Updated session base commit to %s\n", newBaseCommit[:7])
		}

		if needSave {
			if err := s.saveSessionState(state); err != nil {
				return fmt.Errorf("failed to update session state: %w", err)
			}
		}
		return nil
	}
	// If state exists but BaseCommit is empty, it's a partial state from concurrent warning
	// Continue below to properly initialize it

	currentWorktree, err := GetWorktreePath()
	if err != nil {
		return fmt.Errorf("failed to get worktree path: %w", err)
	}

	// Check for existing sessions on the same base commit from different worktrees
	existingSessions, err := s.findSessionsForCommit(head.Hash().String())
	if err != nil {
		// Log but continue - conflict detection is best-effort
		fmt.Fprintf(os.Stderr, "Warning: failed to check for existing sessions: %v\n", err)
	} else {
		for _, existingState := range existingSessions {
			// Skip sessions from the same worktree
			if existingState.WorktreePath == currentWorktree {
				continue
			}

			// Found a session from a different worktree on the same base commit
			shadowBranch := getShadowBranchNameForCommit(head.Hash().String())
			return &ShadowBranchConflictError{
				Branch:           shadowBranch,
				ExistingSession:  existingState.SessionID,
				ExistingWorktree: existingState.WorktreePath,
				LastActivity:     existingState.StartedAt,
				CurrentSession:   sessionID,
				CurrentWorktree:  currentWorktree,
			}
		}
	}

	// Initialize new session
	_, err = s.initializeSession(repo, sessionID, agentType, transcriptPath)
	if err != nil {
		return fmt.Errorf("failed to initialize session: %w", err)
	}

	fmt.Fprintf(os.Stderr, "Initialized shadow session: %s\n", sessionID)
	return nil
}

// getStagedFiles returns a list of files staged for commit.
func getStagedFiles(repo *git.Repository) []string {
	worktree, err := repo.Worktree()
	if err != nil {
		return nil
	}

	status, err := worktree.Status()
	if err != nil {
		return nil
	}

	var staged []string
	for path, fileStatus := range status {
		// Check if file is staged (in index)
		if fileStatus.Staging != git.Unmodified && fileStatus.Staging != git.Untracked {
			staged = append(staged, path)
		}
	}
	return staged
}

// getLastPrompt retrieves the most recent user prompt from a session's shadow branch.
// Returns empty string if no prompt can be retrieved.
func (s *ManualCommitStrategy) getLastPrompt(repo *git.Repository, state *SessionState) string {
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		return ""
	}

	// Extract session data (using 0 as startLine to get all prompts)
	// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini)
	sessionData, err := s.extractSessionData(repo, ref.Hash(), state.SessionID, 0, nil, state.AgentType)
	if err != nil || len(sessionData.Prompts) == 0 {
		return ""
	}

	// Return the last prompt (most recent work before commit)
	return sessionData.Prompts[len(sessionData.Prompts)-1]
}

// hasOverlappingFiles checks if any file in stagedFiles appears in filesTouched.
func hasOverlappingFiles(stagedFiles, filesTouched []string) bool {
	touchedSet := make(map[string]bool)
	for _, f := range filesTouched {
		touchedSet[f] = true
	}

	for _, staged := range stagedFiles {
		if touchedSet[staged] {
			return true
		}
	}
	return false
}

package strategy

import (
	"errors"
	"fmt"
	"path/filepath"
	"sort"
	"strings"

	"entire.io/cli/cmd/entire/cli/paths"
	"entire.io/cli/cmd/entire/cli/trailers"

	"github.com/go-git/go-git/v5/plumbing"
)

// GetSessionLog returns the session transcript and session ID.
func (s *ManualCommitStrategy) GetSessionLog(commitHash string) ([]byte, string, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, "", fmt.Errorf("failed to open git repository: %w", err)
	}

	// Try to look up by checkpoint ID first (12 hex chars)
	if len(commitHash) == 12 {
		log, err := s.getCheckpointLog(commitHash)
		if err == nil {
			// Find session ID from metadata (best-effort lookup)
			checkpoints, _ := s.listCheckpoints() //nolint:errcheck // Best-effort session ID lookup
			for _, cp := range checkpoints {
				if cp.CheckpointID == commitHash {
					return log, cp.SessionID, nil
				}
			}
			return log, "", nil
		}
	}

	// Try to look up by commit
	hash, err := repo.ResolveRevision(plumbing.Revision(commitHash))
	if err == nil {
		commit, err := repo.CommitObject(*hash)
		if err == nil {
			// Check for Entire-Checkpoint trailer
			cpID, hasTrailer := trailers.ParseCheckpoint(commit.Message)
			if hasTrailer && !cpID.IsEmpty() {
				checkpointID := cpID.String()
				log, logErr := s.getCheckpointLog(checkpointID)
				if logErr == nil {
					// Find session ID
					checkpoints, _ := s.listCheckpoints() //nolint:errcheck // Best-effort session ID lookup
					for _, cp := range checkpoints {
						if cp.CheckpointID == checkpointID {
							return log, cp.SessionID, nil
						}
					}
					return log, "", nil
				}
			}

			// Fall back to Entire-Session trailer
			sessionID, found := trailers.ParseSession(commit.Message)
			if found {
				log, err := s.getSessionLogBySessionID(sessionID)
				if err == nil {
					return log, sessionID, nil
				}
			}

			// Try metadata trailer (shadow branch commit)
			metadataDir, found := trailers.ParseMetadata(commit.Message)
			if found {
				sessionID := filepath.Base(metadataDir)
				tree, treeErr := commit.Tree()
				if treeErr == nil {
					// Try current format first, then legacy
					logPath := filepath.Join(metadataDir, paths.TranscriptFileName)
					if file, fileErr := tree.File(logPath); fileErr == nil {
						if content, contentErr := file.Contents(); contentErr == nil {
							return []byte(content), sessionID, nil
						}
					}
					logPath = filepath.Join(metadataDir, paths.TranscriptFileNameLegacy)
					if file, fileErr := tree.File(logPath); fileErr == nil {
						if content, contentErr := file.Contents(); contentErr == nil {
							return []byte(content), sessionID, nil
						}
					}
				}
			}
		}
	}

	// Try as session ID (commitHash is actually a sessionID)
	log, err := s.getSessionLogBySessionID(commitHash)
	if err != nil {
		return nil, "", err
	}
	return log, commitHash, nil
}

// getSessionLogBySessionID returns all transcripts for a session.
func (s *ManualCommitStrategy) getSessionLogBySessionID(sessionID string) ([]byte, error) {
	checkpoints, err := s.getCheckpointsForSession(sessionID)
	if err != nil {
		// Fall back to active session shadow branch
		return s.getSessionLogFromShadow(sessionID)
	}

	// Sort by time (oldest first)
	sort.Slice(checkpoints, func(i, j int) bool {
		return checkpoints[i].CreatedAt.Before(checkpoints[j].CreatedAt)
	})

	var result []byte
	for i, cp := range checkpoints {
		log, err := s.getCheckpointLog(cp.CheckpointID)
		if err != nil {
			continue
		}
		if i > 0 {
			result = append(result, []byte("\n\n--- Next commit ---\n\n")...)
		}
		result = append(result, log...)
	}

	if len(result) == 0 {
		return s.getSessionLogFromShadow(sessionID)
	}

	return result, nil
}

// getSessionLogFromShadow gets transcript from active shadow branch.
func (s *ManualCommitStrategy) getSessionLogFromShadow(sessionID string) ([]byte, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	state, err := s.loadSessionState(sessionID)
	if err != nil || state == nil {
		return nil, fmt.Errorf("no active session: %s", sessionID)
	}

	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		return nil, fmt.Errorf("failed to get shadow branch reference: %w", err)
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get commit object: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get commit tree: %w", err)
	}

	metadataDir := paths.SessionMetadataDir(sessionID)
	if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			return []byte(content), nil
		}
	}
	if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
		if content, contentErr := file.Contents(); contentErr == nil {
			return []byte(content), nil
		}
	}

	return nil, errors.New("no transcript found")
}

// GetTaskCheckpoint retrieves a task checkpoint.
func (s *ManualCommitStrategy) GetTaskCheckpoint(point RewindPoint) (*TaskCheckpoint, error) {
	return getTaskCheckpointFromTree(point)
}

// GetTaskCheckpointTranscript retrieves the transcript for a task checkpoint.
func (s *ManualCommitStrategy) GetTaskCheckpointTranscript(point RewindPoint) ([]byte, error) {
	return getTaskTranscriptFromTree(point)
}

// GetSessionInfo returns the current session info.
func (s *ManualCommitStrategy) GetSessionInfo() (*SessionInfo, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Check if we're on a shadow branch
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	if head.Name().IsBranch() {
		branchName := head.Name().Short()
		if strings.HasPrefix(branchName, shadowBranchPrefix) {
			return nil, ErrNoSession
		}
	}

	// Find sessions for current HEAD
	sessions, err := s.findSessionsForCommit(head.Hash().String())
	if err != nil || len(sessions) == 0 {
		return nil, ErrNoSession
	}

	// Return info for most recent session
	state := sessions[0]
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	info := &SessionInfo{
		SessionID: state.SessionID,
		Reference: shadowBranchName,
	}

	if ref, err := repo.Reference(refName, true); err == nil {
		info.CommitHash = ref.Hash().String()
	}

	return info, nil
}

// GetMetadataRef returns a reference to the metadata for the given checkpoint.
// For manual-commit strategy, returns the sharded path on entire/sessions branch.
func (s *ManualCommitStrategy) GetMetadataRef(checkpoint Checkpoint) string {
	if checkpoint.CheckpointID == "" {
		return ""
	}
	return paths.MetadataBranchName + ":" + trailers.CheckpointPath(checkpoint.CheckpointID)
}

// GetSessionMetadataRef returns a reference to the most recent metadata commit for a session.
// For manual-commit strategy, metadata lives on the entire/sessions branch.
func (s *ManualCommitStrategy) GetSessionMetadataRef(_ string) string {
	repo, err := OpenRepository()
	if err != nil {
		return ""
	}

	// Get the sessions branch
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		return ""
	}

	// The tip of entire/sessions contains all condensed sessions
	// Return a reference to it (sessionID is not used as all sessions are on the same branch)
	return trailers.FormatSourceRef(paths.MetadataBranchName, ref.Hash().String())
}

// GetSessionContext returns the context.md content for a session.
// For manual-commit strategy, reads from the entire/sessions branch using sharded paths.
func (s *ManualCommitStrategy) GetSessionContext(sessionID string) string {
	// Find a checkpoint for this session
	checkpoints, err := s.getCheckpointsForSession(sessionID)
	if err != nil || len(checkpoints) == 0 {
		return ""
	}

	// Use the most recent checkpoint
	sort.Slice(checkpoints, func(i, j int) bool {
		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
	})
	checkpointID := checkpoints[0].CheckpointID

	repo, err := OpenRepository()
	if err != nil {
		return ""
	}

	// Get the sessions branch
	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		return ""
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return ""
	}

	tree, err := commit.Tree()
	if err != nil {
		return ""
	}

	// Context.md is at <sharded-path>/context.md
	contextPath := trailers.CheckpointPath(checkpointID) + "/" + paths.ContextFileName
	file, err := tree.File(contextPath)
	if err != nil {
		return ""
	}
	content, err := file.Contents()
	if err != nil {
		return ""
	}
	return content
}

// GetCheckpointLog returns the session transcript for a specific checkpoint.
// For manual-commit strategy, metadata is stored at sharded paths on entire/sessions branch.
func (s *ManualCommitStrategy) GetCheckpointLog(checkpoint Checkpoint) ([]byte, error) {
	if checkpoint.CheckpointID == "" {
		return nil, ErrNoMetadata
	}
	return s.getCheckpointLog(checkpoint.CheckpointID)
}

// GetAdditionalSessions implements SessionSource interface.
// Returns active sessions from .git/entire-sessions/ that haven't yet been condensed.
func (s *ManualCommitStrategy) GetAdditionalSessions() ([]*Session, error) {
	activeStates, err := s.listAllSessionStates()
	if err != nil {
		return nil, fmt.Errorf("failed to list session states: %w", err)
	}

	if len(activeStates) == 0 {
		return nil, nil
	}

	var sessions []*Session
	for _, state := range activeStates {
		session := &Session{
			ID:          state.SessionID,
			Description: NoDescription,
			Strategy:    StrategyNameManualCommit,
			StartTime:   state.StartedAt,
		}

		// Try to get description from shadow branch
		if description := s.getDescriptionFromShadowBranch(state.SessionID, state.BaseCommit); description != "" {
			session.Description = description
		}

		sessions = append(sessions, session)
	}

	return sessions, nil
}

// getDescriptionFromShadowBranch reads the session description from the shadow branch.
// sessionID is expected to be an Entire session ID (already date-prefixed like "2026-01-12-abc123").
func (s *ManualCommitStrategy) getDescriptionFromShadowBranch(sessionID, baseCommit string) string {
	repo, err := OpenRepository()
	if err != nil {
		return ""
	}

	shadowBranchName := getShadowBranchNameForCommit(baseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil {
		return ""
	}

	commit, err := repo.CommitObject(ref.Hash())
	if err != nil {
		return ""
	}

	tree, err := commit.Tree()
	if err != nil {
		return ""
	}

	// Use SessionMetadataDirFromEntireID since sessionID is already an Entire session ID
	// (with date prefix like "2026-01-12-abc123")
	metadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
	return getSessionDescriptionFromTree(tree, metadataDir)
}

// Compile-time check that ManualCommitStrategy implements SessionSource
var _ SessionSource = (*ManualCommitStrategy)(nil)

package strategy

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	cpkg "entire.io/cli/cmd/entire/cli/checkpoint"
	"entire.io/cli/cmd/entire/cli/paths"

	"github.com/charmbracelet/huh"
	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// GetRewindPoints returns available rewind points.
// Uses checkpoint.GitStore.ListTemporaryCheckpoints for reading from shadow branches.
func (s *ManualCommitStrategy) GetRewindPoints(limit int) ([]RewindPoint, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get checkpoint store
	store, err := s.getCheckpointStore()
	if err != nil {
		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Get current HEAD to find matching shadow branch
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	// Find sessions for current HEAD
	sessions, err := s.findSessionsForCommit(head.Hash().String())
	if err != nil {
		// Log error but continue to check for logs-only points
		sessions = nil
	}

	var allPoints []RewindPoint

	// Collect checkpoint points from active sessions using checkpoint.GitStore
	// Cache session prompts by session ID to avoid re-reading the same prompt file
	sessionPrompts := make(map[string]string)

	for _, state := range sessions {
		checkpoints, err := store.ListTemporaryCheckpoints(context.Background(), state.BaseCommit, state.SessionID, limit)
		if err != nil {
			continue // Error reading checkpoints, skip this session
		}

		for _, cp := range checkpoints {
			// Get session prompt (cached by session ID)
			sessionPrompt, ok := sessionPrompts[cp.SessionID]
			if !ok {
				sessionPrompt = readSessionPrompt(repo, cp.CommitHash, cp.MetadataDir)
				sessionPrompts[cp.SessionID] = sessionPrompt
			}

			allPoints = append(allPoints, RewindPoint{
				ID:               cp.CommitHash.String(),
				Message:          cp.Message,
				MetadataDir:      cp.MetadataDir,
				Date:             cp.Timestamp,
				IsTaskCheckpoint: cp.IsTaskCheckpoint,
				ToolUseID:        cp.ToolUseID,
				SessionID:        cp.SessionID,
				SessionPrompt:    sessionPrompt,
			})
		}
	}

	// Sort by date, most recent first
	sort.Slice(allPoints, func(i, j int) bool {
		return allPoints[i].Date.After(allPoints[j].Date)
	})

	if len(allPoints) > limit {
		allPoints = allPoints[:limit]
	}

	// Also include logs-only points from commit history
	logsOnlyPoints, err := s.GetLogsOnlyRewindPoints(limit)
	if err == nil && len(logsOnlyPoints) > 0 {
		// Build set of existing point IDs for deduplication
		existingIDs := make(map[string]bool)
		for _, p := range allPoints {
			existingIDs[p.ID] = true
		}

		// Add logs-only points that aren't already in the list
		for _, p := range logsOnlyPoints {
			if !existingIDs[p.ID] {
				allPoints = append(allPoints, p)
			}
		}

		// Re-sort by date
		sort.Slice(allPoints, func(i, j int) bool {
			return allPoints[i].Date.After(allPoints[j].Date)
		})

		// Re-trim to limit
		if len(allPoints) > limit {
			allPoints = allPoints[:limit]
		}
	}

	return allPoints, nil
}

// GetLogsOnlyRewindPoints finds commits in the current branch's history that have
// condensed session logs on the entire/sessions branch. These are commits that
// were created with session data but the shadow branch has been condensed.
//
// The function works by:
// 1. Getting all checkpoints from the entire/sessions branch
// 2. Building a map of checkpoint ID -> checkpoint info
// 3. Scanning the current branch history for commits with Entire-Checkpoint trailers
// 4. Matching by checkpoint ID (stable across amend/rebase)
func (s *ManualCommitStrategy) GetLogsOnlyRewindPoints(limit int) ([]RewindPoint, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, err
	}

	// Get all checkpoints from entire/sessions branch
	checkpoints, err := s.listCheckpoints()
	if err != nil {
		// No checkpoints yet is fine
		return nil, nil //nolint:nilerr // Expected when no checkpoints exist
	}

	if len(checkpoints) == 0 {
		return nil, nil
	}

	// Build map of checkpoint ID -> checkpoint info
	// Checkpoint ID is the stable link from Entire-Checkpoint trailer
	checkpointInfoMap := make(map[string]CheckpointInfo)
	for _, cp := range checkpoints {
		if cp.CheckpointID != "" {
			checkpointInfoMap[cp.CheckpointID] = cp
		}
	}

	// Get metadata branch tree for reading session prompts (best-effort, ignore errors)
	metadataTree, _ := GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort for session prompts

	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}

	// Use LogOptions with Order=LogOrderCommitterTime to traverse all parents of merge commits.
	iter, err := repo.Log(&git.LogOptions{
		From:  head.Hash(),
		Order: git.LogOrderCommitterTime,
	})
	if err != nil {
		return nil, fmt.Errorf("failed to get commit log: %w", err)
	}

	var points []RewindPoint
	count := 0

	err = iter.ForEach(func(c *object.Commit) error {
		if count >= logsOnlyScanLimit {
			return errStop
		}
		count++

		// Extract checkpoint ID from Entire-Checkpoint trailer
		cpID, hasTrailer := trailers.ParseCheckpoint(c.Message)
		if !hasTrailer || cpID.IsEmpty() {
			return nil
		}
		checkpointID := cpID.String()

		// Check if this checkpoint ID has metadata on entire/sessions
		cpInfo, found := checkpointInfoMap[checkpointID]
		if !found {
			return nil
		}

		// Create logs-only rewind point
		message := strings.Split(c.Message, "\n")[0]

		// Read session prompts from metadata tree
		var sessionPrompt string
		var sessionPrompts []string
		if metadataTree != nil {
			checkpointPath := trailers.CheckpointPath(cpInfo.CheckpointID)
			// For multi-session checkpoints, read all prompts
			if cpInfo.SessionCount > 1 && len(cpInfo.SessionIDs) > 1 {
				sessionPrompts = ReadAllSessionPromptsFromTree(metadataTree, checkpointPath, cpInfo.SessionCount, cpInfo.SessionIDs)
				// Use the last (most recent) prompt as the main session prompt
				if len(sessionPrompts) > 0 {
					sessionPrompt = sessionPrompts[len(sessionPrompts)-1]
				}
			} else {
				sessionPrompt = ReadSessionPromptFromTree(metadataTree, checkpointPath)
				if sessionPrompt != "" {
					sessionPrompts = []string{sessionPrompt}
				}
			}
		}

		points = append(points, RewindPoint{
			ID:             c.Hash.String(),
			Message:        message,
			Date:           c.Author.When,
			IsLogsOnly:     true,
			CheckpointID:   cpInfo.CheckpointID,
			Agent:          cpInfo.Agent,
			SessionID:      cpInfo.SessionID,
			SessionPrompt:  sessionPrompt,
			SessionCount:   cpInfo.SessionCount,
			SessionIDs:     cpInfo.SessionIDs,
			SessionPrompts: sessionPrompts,
		})

		return nil
	})

	if err != nil && !errors.Is(err, errStop) {
		return nil, fmt.Errorf("error iterating commits: %w", err)
	}

	if len(points) > limit {
		points = points[:limit]
	}

	return points, nil
}

// Rewind restores the working directory to a checkpoint.
//
//nolint:maintidx // Complex rewind flow spans multiple recovery modes.
func (s *ManualCommitStrategy) Rewind(point RewindPoint) error {
	repo, err := OpenRepository()
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get the checkpoint commit
	commitHash := plumbing.NewHash(point.ID)
	commit, err := repo.CommitObject(commitHash)
	if err != nil {
		return fmt.Errorf("failed to get commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get tree: %w", err)
	}

	// Reset the shadow branch to the rewound checkpoint
	// This ensures the next checkpoint will only include prompts from this point forward
	if err := s.resetShadowBranchToCheckpoint(repo, commit); err != nil {
		// Log warning but don't fail - file restoration is the primary operation
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to reset shadow branch: %v\n", err)
	}

	// Load session state to get untracked files that existed at session start
	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
	var preservedUntrackedFiles map[string]bool
	if hasSessionTrailer {
		state, stateErr := s.loadSessionState(sessionID)
		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
			preservedUntrackedFiles = make(map[string]bool)
			for _, f := range state.UntrackedFilesAtStart {
				preservedUntrackedFiles[f] = true
			}
		}
	}

	// Build set of files in the checkpoint tree (excluding metadata)
	checkpointFiles := make(map[string]bool)
	err = tree.Files().ForEach(func(f *object.File) error {
		if !strings.HasPrefix(f.Name, entireDir) {
			checkpointFiles[f.Name] = true
		}
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to list checkpoint files: %w", err)
	}

	// Get HEAD tree to identify tracked files
	head, err := repo.Head()
	if err != nil {
		return fmt.Errorf("failed to get HEAD: %w", err)
	}
	headCommit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return fmt.Errorf("failed to get HEAD commit: %w", err)
	}
	headTree, err := headCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get HEAD tree: %w", err)
	}

	// Build set of files tracked in HEAD
	trackedFiles := make(map[string]bool)
	//nolint:errcheck // Error is not critical for rewind
	_ = headTree.Files().ForEach(func(f *object.File) error {
		trackedFiles[f.Name] = true
		return nil
	})

	// Get repository root to walk from there
	repoRoot, err := GetWorktreePath()
	if err != nil {
		repoRoot = "." // Fallback to current directory
	}

	// Find and delete untracked files that aren't in the checkpoint
	// These are likely files created by Claude in later checkpoints
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		// Get path relative to repo root
		relPath, relErr := filepath.Rel(repoRoot, path)
		if relErr != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories and special paths
		if info.IsDir() {
			if relPath == gitDir || relPath == claudeDir || relPath == entireDir || strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip if path is a special directory
		if strings.HasPrefix(relPath, gitDir+"/") || strings.HasPrefix(relPath, claudeDir+"/") || strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		// If file is in checkpoint, it will be restored
		if checkpointFiles[relPath] {
			return nil
		}

		// If file is tracked in HEAD, don't delete (user's committed work)
		if trackedFiles[relPath] {
			return nil
		}

		// If file existed at session start, preserve it (untracked user files)
		if preservedUntrackedFiles[relPath] {
			return nil
		}

		// File is untracked and not in checkpoint - delete it (use absolute path)
		if removeErr := os.Remove(path); removeErr == nil {
			fmt.Fprintf(os.Stderr, "  Deleted: %s\n", relPath)
		}

		return nil
	})
	if err != nil {
		// Non-fatal - continue with restoration
		fmt.Fprintf(os.Stderr, "Warning: error walking directory: %v\n", err)
	}

	// Restore files from checkpoint
	err = tree.Files().ForEach(func(f *object.File) error {
		// Skip metadata directories - these are for checkpoint storage, not working dir
		if strings.HasPrefix(f.Name, entireDir) {
			return nil
		}

		contents, err := f.Contents()
		if err != nil {
			return fmt.Errorf("failed to read file %s: %w", f.Name, err)
		}

		// Ensure directory exists
		dir := filepath.Dir(f.Name)
		if dir != "." {
			//nolint:gosec // G301: Need 0o755 for user directories during rewind
			if err := os.MkdirAll(dir, 0o755); err != nil {
				return fmt.Errorf("failed to create directory %s: %w", dir, err)
			}
		}

		// Write file with appropriate permissions
		var perm os.FileMode = 0o644
		if f.Mode == filemode.Executable {
			perm = 0o755
		}
		if err := os.WriteFile(f.Name, []byte(contents), perm); err != nil {
			return fmt.Errorf("failed to write file %s: %w", f.Name, err)
		}

		fmt.Fprintf(os.Stderr, "  Restored: %s\n", f.Name)
		return nil
	})
	if err != nil {
		return fmt.Errorf("failed to iterate tree files: %w", err)
	}

	fmt.Println()
	if len(point.ID) >= 7 {
		fmt.Printf("Restored files from shadow commit %s\n", point.ID[:7])
	} else {
		fmt.Printf("Restored files from shadow commit %s\n", point.ID)
	}
	fmt.Println()

	return nil
}

// resetShadowBranchToCheckpoint resets the shadow branch HEAD to the given checkpoint.
// This ensures that when the user commits after rewinding, the next checkpoint will only
// include prompts from the rewound point, not prompts from later checkpoints.
func (s *ManualCommitStrategy) resetShadowBranchToCheckpoint(repo *git.Repository, commit *object.Commit) error {
	// Extract session ID from the checkpoint commit's Entire-Session trailer
	sessionID, found := trailers.ParseSession(commit.Message)
	if !found {
		return errors.New("checkpoint has no Entire-Session trailer")
	}

	// Load session state to get the shadow branch name
	state, err := s.loadSessionState(sessionID)
	if err != nil {
		return fmt.Errorf("failed to load session state: %w", err)
	}
	if state == nil {
		return fmt.Errorf("session %s not found", sessionID)
	}

	// Reset the shadow branch to the checkpoint commit
	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit)
	refName := plumbing.NewBranchReferenceName(shadowBranchName)

	// Update the reference to point to the checkpoint commit
	ref := plumbing.NewHashReference(refName, commit.Hash)
	if err := repo.Storer.SetReference(ref); err != nil {
		return fmt.Errorf("failed to update shadow branch: %w", err)
	}

	fmt.Fprintf(os.Stderr, "[entire] Reset shadow branch %s to checkpoint %s\n", shadowBranchName, commit.Hash.String()[:7])
	return nil
}

// CanRewind checks if rewinding is possible.
// For manual-commit strategy, rewind restores files from a checkpoint - uncommitted changes are expected
// and will be replaced by the checkpoint contents. Returns true with a warning message showing
// what changes will be reverted.
func (s *ManualCommitStrategy) CanRewind() (bool, string, error) {
	return checkCanRewindWithWarning()
}

// PreviewRewind returns what will happen if rewinding to the given point.
// This allows showing warnings about untracked files that will be deleted.
func (s *ManualCommitStrategy) PreviewRewind(point RewindPoint) (*RewindPreview, error) {
	// Logs-only points don't modify the working directory
	if point.IsLogsOnly {
		return &RewindPreview{}, nil
	}

	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get the checkpoint commit
	commitHash := plumbing.NewHash(point.ID)
	commit, err := repo.CommitObject(commitHash)
	if err != nil {
		return nil, fmt.Errorf("failed to get commit: %w", err)
	}

	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get tree: %w", err)
	}

	// Load session state to get untracked files that existed at session start
	sessionID, hasSessionTrailer := trailers.ParseSession(commit.Message)
	var preservedUntrackedFiles map[string]bool
	if hasSessionTrailer {
		state, stateErr := s.loadSessionState(sessionID)
		if stateErr == nil && state != nil && len(state.UntrackedFilesAtStart) > 0 {
			preservedUntrackedFiles = make(map[string]bool)
			for _, f := range state.UntrackedFilesAtStart {
				preservedUntrackedFiles[f] = true
			}
		}
	}

	// Build set of files in the checkpoint tree (excluding metadata)
	checkpointFiles := make(map[string]bool)
	var filesToRestore []string
	err = tree.Files().ForEach(func(f *object.File) error {
		if !strings.HasPrefix(f.Name, entireDir) {
			checkpointFiles[f.Name] = true
			filesToRestore = append(filesToRestore, f.Name)
		}
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("failed to list checkpoint files: %w", err)
	}

	// Get HEAD tree to identify tracked files
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD: %w", err)
	}
	headCommit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
	}
	headTree, err := headCommit.Tree()
	if err != nil {
		return nil, fmt.Errorf("failed to get HEAD tree: %w", err)
	}

	// Build set of files tracked in HEAD
	trackedFiles := make(map[string]bool)
	//nolint:errcheck // Error is not critical for preview
	_ = headTree.Files().ForEach(func(f *object.File) error {
		trackedFiles[f.Name] = true
		return nil
	})

	// Get repository root to walk from there
	repoRoot, err := GetWorktreePath()
	if err != nil {
		repoRoot = "."
	}

	// Find untracked files that would be deleted
	var filesToDelete []string
	err = filepath.Walk(repoRoot, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil //nolint:nilerr // Skip filesystem errors during walk
		}

		relPath, relErr := filepath.Rel(repoRoot, path)
		if relErr != nil {
			return nil //nolint:nilerr // Skip paths we can't make relative
		}

		// Skip directories and special paths
		if info.IsDir() {
			if relPath == gitDir || relPath == claudeDir || relPath == entireDir ||
				strings.HasPrefix(relPath, gitDir+"/") ||
				strings.HasPrefix(relPath, claudeDir+"/") ||
				strings.HasPrefix(relPath, entireDir+"/") {
				return filepath.SkipDir
			}
			return nil
		}

		// Skip special directories
		if strings.HasPrefix(relPath, gitDir+"/") ||
			strings.HasPrefix(relPath, claudeDir+"/") ||
			strings.HasPrefix(relPath, entireDir+"/") {
			return nil
		}

		// If file is in checkpoint, it will be restored (not deleted)
		if checkpointFiles[relPath] {
			return nil
		}

		// If file is tracked in HEAD, don't delete (user's committed work)
		if trackedFiles[relPath] {
			return nil
		}

		// If file existed at session start, preserve it (untracked user files)
		if preservedUntrackedFiles[relPath] {
			return nil
		}

		// File is untracked and not in checkpoint - will be deleted
		filesToDelete = append(filesToDelete, relPath)
		return nil
	})
	if err != nil {
		// Non-fatal, return what we have
		return &RewindPreview{ //nolint:nilerr // Partial result is still useful
			FilesToRestore: filesToRestore,
			FilesToDelete:  filesToDelete,
		}, nil
	}

	// Sort for consistent output
	sort.Strings(filesToRestore)
	sort.Strings(filesToDelete)

	return &RewindPreview{
		FilesToRestore: filesToRestore,
		FilesToDelete:  filesToDelete,
	}, nil
}

// RestoreLogsOnly restores session logs from a logs-only rewind point.
// This fetches the transcript from entire/sessions and writes it to Claude's project directory.
// Does not modify the working directory.
// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
// If force is false, prompts for confirmation when local logs have newer timestamps.
func (s *ManualCommitStrategy) RestoreLogsOnly(point RewindPoint, force bool) error {
	if !point.IsLogsOnly {
		return errors.New("not a logs-only rewind point")
	}

	if point.CheckpointID == "" {
		return errors.New("missing checkpoint ID")
	}

	// Get checkpoint store
	store, err := s.getCheckpointStore()
	if err != nil {
		return fmt.Errorf("failed to get checkpoint store: %w", err)
	}

	// Read full checkpoint data including archived sessions
	result, err := store.ReadCommitted(context.Background(), point.CheckpointID)
	if err != nil {
		return fmt.Errorf("failed to read checkpoint: %w", err)
	}
	if result == nil {
		return fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
	}
	if len(result.Transcript) == 0 {
		return fmt.Errorf("no transcript found for checkpoint: %s", point.CheckpointID)
	}

	// Get repo root for Claude project path lookup
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		return fmt.Errorf("failed to get repository root: %w", err)
	}

	claudeProjectDir, err := paths.GetClaudeProjectDir(repoRoot)
	if err != nil {
		return fmt.Errorf("failed to get Claude project directory: %w", err)
	}

	// Ensure project directory exists
	if err := os.MkdirAll(claudeProjectDir, 0o750); err != nil {
		return fmt.Errorf("failed to create Claude project directory: %w", err)
	}

	// Check for newer local logs if not forcing
	if !force {
		sessions := s.classifySessionsForRestore(claudeProjectDir, result)
		hasConflicts := false
		for _, sess := range sessions {
			if sess.Status == StatusLocalNewer {
				hasConflicts = true
				break
			}
		}
		if hasConflicts {
			shouldOverwrite, promptErr := PromptOverwriteNewerLogs(sessions)
			if promptErr != nil {
				return promptErr
			}
			if !shouldOverwrite {
				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session logs preserved.\n")
				return nil
			}
		}
	}

	// Count sessions to restore
	totalSessions := 1 + len(result.ArchivedSessions)
	if totalSessions > 1 {
		fmt.Fprintf(os.Stderr, "Restoring %d sessions from checkpoint:\n", totalSessions)
	}

	// Restore archived sessions first (oldest to newest)
	for _, archived := range result.ArchivedSessions {
		if len(archived.Transcript) == 0 {
			continue
		}

		sessionID := archived.SessionID
		if sessionID == "" {
			// Fallback: can't identify session without ID
			fmt.Fprintf(os.Stderr, "  Warning: archived session %d has no session ID, skipping\n", archived.FolderIndex)
			continue
		}

		modelSessionID := paths.ModelSessionID(sessionID)
		claudeSessionFile := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")

		// Get first prompt for display
		promptPreview := ExtractFirstPrompt(archived.Prompts)
		if promptPreview != "" {
			fmt.Fprintf(os.Stderr, "  Session %d: %s\n", archived.FolderIndex, promptPreview)
		}

		fmt.Fprintf(os.Stderr, "    Writing to: %s\n", claudeSessionFile)
		if err := os.WriteFile(claudeSessionFile, archived.Transcript, 0o600); err != nil {
			fmt.Fprintf(os.Stderr, "    Warning: failed to write transcript: %v\n", err)
			continue
		}
	}

	// Restore the most recent session (at root level)
	sessionID := result.Metadata.SessionID
	if sessionID == "" {
		// Fall back to extracting from commit's Entire-Session trailer
		sessionID = s.extractSessionIDFromCommit(point.ID)
		if sessionID == "" {
			return errors.New("failed to determine session ID for latest session")
		}
	}

	modelSessionID := paths.ModelSessionID(sessionID)
	claudeSessionFile := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")

	if totalSessions > 1 {
		promptPreview := ExtractFirstPrompt(result.Prompts)
		if promptPreview != "" {
			fmt.Fprintf(os.Stderr, "  Session %d (latest): %s\n", totalSessions, promptPreview)
		}
		fmt.Fprintf(os.Stderr, "    Writing to: %s\n", claudeSessionFile)
	} else {
		fmt.Fprintf(os.Stderr, "Writing transcript to: %s\n", claudeSessionFile)
	}

	if err := os.WriteFile(claudeSessionFile, result.Transcript, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// extractSessionIDFromCommit extracts the session ID from a commit's Entire-Session trailer.
func (s *ManualCommitStrategy) extractSessionIDFromCommit(commitHash string) string {
	repo, err := OpenRepository()
	if err != nil {
		return ""
	}

	hash, err := repo.ResolveRevision(plumbing.Revision(commitHash))
	if err != nil {
		return ""
	}

	commit, err := repo.CommitObject(*hash)
	if err != nil {
		return ""
	}

	// Parse Entire-Session trailer
	sessionID, found := trailers.ParseSession(commit.Message)
	if found {
		return sessionID
	}

	return ""
}

// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
// Returns an empty string if the prompt cannot be read.
func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
	// Get the commit and its tree
	commit, err := repo.CommitObject(commitHash)
	if err != nil {
		return ""
	}

	tree, err := commit.Tree()
	if err != nil {
		return ""
	}

	// Look for prompt.txt in the metadata directory
	promptPath := metadataDir + "/" + paths.PromptFileName
	promptEntry, err := tree.File(promptPath)
	if err != nil {
		return ""
	}

	content, err := promptEntry.Contents()
	if err != nil {
		return ""
	}

	return ExtractFirstPrompt(content)
}

// SessionRestoreStatus represents the status of a session being restored.
type SessionRestoreStatus int

const (
	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
	StatusUnchanged                                   // Local and checkpoint are the same
	StatusCheckpointNewer                             // Checkpoint has newer entries
	StatusLocalNewer                                  // Local has newer entries (conflict)
)

// SessionRestoreInfo contains information about a session being restored.
type SessionRestoreInfo struct {
	SessionID      string
	Prompt         string               // First prompt preview for display
	Status         SessionRestoreStatus // Status of this session
	LocalTime      time.Time
	CheckpointTime time.Time
}

// classifySessionsForRestore checks all sessions in a checkpoint result and returns info
// about each session, including whether local logs have newer timestamps.
func (s *ManualCommitStrategy) classifySessionsForRestore(claudeProjectDir string, result *cpkg.ReadCommittedResult) []SessionRestoreInfo {
	var sessions []SessionRestoreInfo

	// Check archived sessions
	for _, archived := range result.ArchivedSessions {
		if len(archived.Transcript) == 0 || archived.SessionID == "" {
			continue
		}

		modelSessionID := paths.ModelSessionID(archived.SessionID)
		localPath := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")

		localTime := paths.GetLastTimestampFromFile(localPath)
		checkpointTime := paths.GetLastTimestampFromBytes(archived.Transcript)
		status := ClassifyTimestamps(localTime, checkpointTime)

		sessions = append(sessions, SessionRestoreInfo{
			SessionID:      archived.SessionID,
			Prompt:         ExtractFirstPrompt(archived.Prompts),
			Status:         status,
			LocalTime:      localTime,
			CheckpointTime: checkpointTime,
		})
	}

	// Check primary session
	if result.Metadata.SessionID != "" && len(result.Transcript) > 0 {
		modelSessionID := paths.ModelSessionID(result.Metadata.SessionID)
		localPath := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")

		localTime := paths.GetLastTimestampFromFile(localPath)
		checkpointTime := paths.GetLastTimestampFromBytes(result.Transcript)
		status := ClassifyTimestamps(localTime, checkpointTime)

		sessions = append(sessions, SessionRestoreInfo{
			SessionID:      result.Metadata.SessionID,
			Prompt:         ExtractFirstPrompt(result.Prompts),
			Status:         status,
			LocalTime:      localTime,
			CheckpointTime: checkpointTime,
		})
	}

	return sessions
}

// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
	// Local file doesn't exist (no timestamp found)
	if localTime.IsZero() {
		return StatusNew
	}

	// Can't determine checkpoint time - treat as new/safe
	if checkpointTime.IsZero() {
		return StatusNew
	}

	// Compare timestamps
	if localTime.After(checkpointTime) {
		return StatusLocalNewer
	}
	if checkpointTime.After(localTime) {
		return StatusCheckpointNewer
	}
	return StatusUnchanged
}

// StatusToText returns a human-readable status string.
func StatusToText(status SessionRestoreStatus) string {
	switch status {
	case StatusNew:
		return "(new)"
	case StatusUnchanged:
		return "(unchanged)"
	case StatusCheckpointNewer:
		return "(checkpoint is newer)"
	case StatusLocalNewer:
		return "(local is newer)" // shouldn't appear in non-conflict list
	default:
		return ""
	}
}

// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
// session logs that have newer timestamps than the checkpoint versions.
func PromptOverwriteNewerLogs(sessions []SessionRestoreInfo) (bool, error) {
	// Separate conflicting and non-conflicting sessions
	var conflicting, nonConflicting []SessionRestoreInfo
	for _, s := range sessions {
		if s.Status == StatusLocalNewer {
			conflicting = append(conflicting, s)
		} else {
			nonConflicting = append(nonConflicting, s)
		}
	}

	fmt.Fprintf(os.Stderr, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
	for _, info := range conflicting {
		// Show prompt if available, otherwise fall back to session ID
		if info.Prompt != "" {
			fmt.Fprintf(os.Stderr, "  \"%s\"\n", info.Prompt)
		} else {
			fmt.Fprintf(os.Stderr, "  Session: %s\n", info.SessionID)
		}
		fmt.Fprintf(os.Stderr, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
		fmt.Fprintf(os.Stderr, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
	}

	// Show non-conflicting sessions with their status
	if len(nonConflicting) > 0 {
		fmt.Fprintf(os.Stderr, "\nThese other session(s) will also be restored:\n")
		for _, info := range nonConflicting {
			statusText := StatusToText(info.Status)
			if info.Prompt != "" {
				fmt.Fprintf(os.Stderr, "  \"%s\" %s\n", info.Prompt, statusText)
			} else {
				fmt.Fprintf(os.Stderr, "  Session: %s %s\n", info.SessionID, statusText)
			}
		}
	}

	fmt.Fprintf(os.Stderr, "\nOverwriting will lose the newer local entries.\n\n")

	var confirmed bool
	form := huh.NewForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title("Overwrite local session logs with checkpoint versions?").
				Value(&confirmed),
		),
	)
	if isAccessibleMode() {
		form = form.WithAccessible(true)
	}

	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) {
			return false, nil
		}
		return false, fmt.Errorf("failed to get confirmation: %w", err)
	}

	return confirmed, nil
}

package strategy

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"entire.io/cli/cmd/entire/cli/paths"
	"github.com/go-git/go-git/v5"
)

// NoDescription is the default description for sessions without one.
const NoDescription = "No description"

// Session represents a Claude Code session with its checkpoints.
// A session is created when a user runs `claude` and tracks all changes
// made during that interaction.
type Session struct {
	// ID is the unique session identifier (e.g., "2025-12-01-8f76b0e8-b8f1-4a87-9186-848bdd83d62e")
	ID string

	// Description is a human-readable summary of the session
	// (typically the first prompt or derived from commit messages)
	Description string

	// Strategy is the name of the strategy that created this session
	Strategy string

	// StartTime is when the session was started
	StartTime time.Time

	// Checkpoints is the list of save points within this session
	Checkpoints []Checkpoint
}

// Checkpoint represents a save point within a session.
// Checkpoints can be either session-level (on Stop) or task-level (on subagent completion).
type Checkpoint struct {
	// CheckpointID is the stable 12-hex-char identifier for this checkpoint.
	// Used to look up metadata at <id[:2]>/<id[2:]>/ on entire/sessions branch.
	CheckpointID string

	// Message is the commit message or checkpoint description
	Message string

	// Timestamp is when this checkpoint was created
	Timestamp time.Time

	// IsTaskCheckpoint indicates if this is a task checkpoint (vs a session checkpoint)
	IsTaskCheckpoint bool

	// ToolUseID is the tool use ID for task checkpoints (empty for session checkpoints)
	ToolUseID string
}

// PromptResponse represents a single user prompt and assistant response pair.
type PromptResponse struct {
	// Prompt is the user's message
	Prompt string

	// Response is the assistant's response
	Response string

	// Files is the list of files modified during this prompt/response
	Files []string
}

// CheckpointDetails contains detailed information extracted from a checkpoint's transcript.
// This is used by the explain command to display checkpoint content.
type CheckpointDetails struct {
	// Interactions contains all prompt/response pairs in this checkpoint.
	// For strategies like auto-commit/commit, this typically has one entry.
	// For strategies like shadow, this may have multiple entries.
	Interactions []PromptResponse

	// Files is the aggregate list of all files modified in this checkpoint.
	// This is a convenience field that combines files from all interactions.
	Files []string
}

// ListSessions returns all sessions from the entire/sessions branch,
// plus any additional sessions from strategies implementing SessionSource.
// It automatically discovers all registered strategies and merges their sessions.
func ListSessions() ([]Session, error) {
	repo, err := OpenRepository()
	if err != nil {
		return nil, fmt.Errorf("failed to open git repository: %w", err)
	}

	// Get checkpoints from the entire/sessions branch
	checkpoints, err := ListCheckpoints()
	if err != nil {
		return nil, fmt.Errorf("failed to list checkpoints: %w", err)
	}

	// Group checkpoints by session ID
	// For multi-session checkpoints, expand SessionIDs array so each session gets the checkpoint
	sessionMap := make(map[string]*Session)
	for _, cp := range checkpoints {
		// Determine which session IDs this checkpoint belongs to
		// Multi-session checkpoints have SessionIDs populated; single-session use SessionID
		sessionIDs := cp.SessionIDs
		if len(sessionIDs) == 0 {
			sessionIDs = []string{cp.SessionID}
		}

		for _, sessionID := range sessionIDs {
			if sessionID == "" {
				continue
			}

			if existing, ok := sessionMap[sessionID]; ok {
				existing.Checkpoints = append(existing.Checkpoints, Checkpoint{
					CheckpointID:     cp.CheckpointID,
					Message:          "Checkpoint: " + cp.CheckpointID,
					Timestamp:        cp.CreatedAt,
					IsTaskCheckpoint: cp.IsTask,
					ToolUseID:        cp.ToolUseID,
				})
			} else {
				// Get description from the checkpoint tree
				description := getDescriptionForCheckpoint(repo, cp.CheckpointID)

				sessionMap[sessionID] = &Session{
					ID:          sessionID,
					Description: description,
					Strategy:    "", // Will be set from metadata if available
					StartTime:   cp.CreatedAt,
					Checkpoints: []Checkpoint{{
						CheckpointID:     cp.CheckpointID,
						Message:          "Checkpoint: " + cp.CheckpointID,
						Timestamp:        cp.CreatedAt,
						IsTaskCheckpoint: cp.IsTask,
						ToolUseID:        cp.ToolUseID,
					}},
				}
			}
		}
	}

	// Check all registered strategies for additional sessions
	for _, name := range List() {
		strat, stratErr := Get(name)
		if stratErr != nil {
			continue
		}
		source, ok := strat.(SessionSource)
		if !ok {
			continue
		}
		additionalSessions, addErr := source.GetAdditionalSessions()
		if addErr != nil {
			continue // Skip strategies that fail to provide additional sessions
		}
		for _, addSession := range additionalSessions {
			if addSession == nil {
				continue
			}
			if existing, ok := sessionMap[addSession.ID]; ok {
				// Merge checkpoints - deduplicate by CheckpointID
				existingCPIDs := make(map[string]bool)
				for _, cp := range existing.Checkpoints {
					existingCPIDs[cp.CheckpointID] = true
				}
				for _, cp := range addSession.Checkpoints {
					if !existingCPIDs[cp.CheckpointID] {
						existing.Checkpoints = append(existing.Checkpoints, cp)
					}
				}
				// Update start time if additional session is older
				if addSession.StartTime.Before(existing.StartTime) {
					existing.StartTime = addSession.StartTime
				}
				// Use description from additional source if existing is empty
				if existing.Description == "" || existing.Description == NoDescription {
					existing.Description = addSession.Description
				}
			} else {
				// New session from additional source
				sessionMap[addSession.ID] = addSession
			}
		}
	}

	// Convert map to slice
	sessions := make([]Session, 0, len(sessionMap))
	for _, session := range sessionMap {
		// Sort checkpoints within each session by timestamp (most recent first)
		sort.Slice(session.Checkpoints, func(i, j int) bool {
			return session.Checkpoints[i].Timestamp.After(session.Checkpoints[j].Timestamp)
		})
		sessions = append(sessions, *session)
	}

	// Sort sessions by start time (most recent first)
	sort.Slice(sessions, func(i, j int) bool {
		return sessions[i].StartTime.After(sessions[j].StartTime)
	})

	return sessions, nil
}

// GetSession finds a session by ID (supports prefix matching).
// Returns ErrNoSession if no matching session is found.
func GetSession(sessionID string) (*Session, error) {
	sessions, err := ListSessions()
	if err != nil {
		return nil, err
	}
	return findSessionByID(sessions, sessionID)
}

// getDescriptionForCheckpoint reads the description for a checkpoint from the entire/sessions branch.
func getDescriptionForCheckpoint(repo *git.Repository, checkpointID string) string {
	tree, err := GetMetadataBranchTree(repo)
	if err != nil {
		return NoDescription
	}

	checkpointPath := trailers.CheckpointPath(checkpointID)
	return getSessionDescriptionFromTree(tree, checkpointPath)
}

// findSessionByID finds a session by exact ID or prefix match.
func findSessionByID(sessions []Session, sessionID string) (*Session, error) {
	for _, session := range sessions {
		if session.ID == sessionID || strings.HasPrefix(session.ID, sessionID) {
			return &session, nil
		}
	}
	return nil, ErrNoSession
}

