func TestSessionStruct(t *testing.T) {
	now := time.Now()
	checkpoints := []Checkpoint{
		{
			CheckpointID:     "abc123def456",
			Message:          "First checkpoint",
			Timestamp:        now.Add(-time.Hour),
			IsTaskCheckpoint: false,
