	// Build tree
	treeHash, err := checkpoint.BuildTreeFromEntries(repo, entries)
	if err != nil {
		t.Fatalf("failed to build tree: %v", err)
	}

	// Create orphan commit
	now := time.Now()
	sig := object.Signature{
		Name:  "Test",
		Email: "test@test.com",
		When:  now,
	}
	commit := &object.Commit{
