		name    string
		input   string
		wantErr bool
	}{
		{
			name:    "valid 12-char hex",
			input:   "a1b2c3d4e5f6",
			wantErr: false,
		},
		{
			name:    "too short",
			input:   "a1b2c3",
			wantErr: true,
		},
		{
			name:    "too long",
			input:   "a1b2c3d4e5f6789012",
			wantErr: true,
		},
		{
			name:    "non-hex characters",
			input:   "a1b2c3d4e5gg",
			wantErr: true,
		},
		{
			name:    "empty",
			input:   "",
			wantErr: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			id, err := NewCheckpointID(tt.input)
			if tt.wantErr {
				if err == nil {
					t.Error("expected error, got nil")
